window.__D("text/maamarei-admur-haemtzai/c003",{"p":[[1900420030,"שמו העצמי בבחי' אח\"פ בתכלית, ולכך נק' שמו הגדול שגם שהוא בבחי' שם שהוא בחי' המל' אבל הוא בבחי' גדולתו העצמי' דלגדולתו אין חקר כלל (שזהו התנשאו' שמצד עצמו כנ\"ל). וזהו עדי עד ל' נצחי', כי גם במל' דא\"ס שבקו\"ח מאיר אור הא\"ס כנ\"ל, וגם עדי עד כמו עד כאן ותו לא וכמו ולא עד בכלל, כי למעלה מן הקו\"ח במל' דא\"ס שלפני הצמצום שם לא יוכלו לשבח מטעם הנ\"ל, רק שיכולי' להמשיך ברכה ממקורא דכולא גם בבחי' שמו הגדו\"ל הזה וכמו שאו' יהא שמי' רבא מברך לעלם כו', והברכה הזאת הוא מה שנמשך מבחי' שמו הגדול שלפני הארת הקו\"ח להיות מתצמצם בקו\"ח שיהי' נק' מלך וחי העולמי' (שהוא מח' דאמלוך כידוע בענין מלך ומלך וימלוך כו') להיו' בבחי' סובב וממלא. וזהו בא\"י מלך מהולל בתשבחו' שנמשך משמו הגדול להיו' מלך כו' וד\"ל.\n[יו\"ד] <b>אך</b> הנה באמת גם בחי' מל' דא\"ס עצמו כמו שהוא קודם הצמצום כנ\"ל שנק' שמ\"ו הגדול גם הוא אינו רק בחי' גילוי אור לבד מעצמו' דא\"ס, ואע\"פ שזהו בחי' אור של העצמו' דא\"ס כמו שהוא כנ\"ל, מ\"מ אין לו ערך לגבי מוה\"ע דא\"ס ממש כמו ערך גילוי האור וזיו דשמש לגבי גופו ומהותו של המאור שממנו נמצא גילוי האור דכלא חשיב לגביו, וכמו עד\"מ שמו של אדם אע\"פ שהוא שם העצם שלו שא\"א לקרותו בשם אחר כלל להיותו מורה על עצמותו ממש מ\"מ אינו מוה\"ע האדם רק שמו בלבד שנתפס בהן לזולתו, ואפי' שם של מלוכה שאינה בהתפשטו' על המדינה רק הוא ענין התנשאו' מצד עצמו אין זה מוה\"ע ממש רק מדת ההתנשאו' לבד (כמשי\"ת), וכך הוא למעלה גם בבחי' מל' דא\"ס עצמו הנ\"ל לגבי מוה\"ע א\"ס ב\"ה שנק' שם עכ\"פ שאינו אלא לגבי העולמו' ואינו נחשב בבחי' העצמו' כמו שהאור של השמש אינו מוה\"ע השמש כנ\"ל, וכן בענין בחי' המל' בהתנשאו' אע\"פ שנק' מלך יחיד לבדו אין זה כמו מדת מלוכה המתפשט על זולתו שאין זה נוגע בעצמו' ממש (כמשי\"ת).\n<b>אך</b> הנה באמת גם בבחי' מל' דא\"ס לא יתכן לומר בו בחי' מלוכה ממש אף מה שמתצמצם בעצמו להיות מלכותו מל' כ\"ע שזהו להיות בבחי' סובב וממלא אע\"פ שבא למטה בהתפשטו' והתנשאו' ממש מאחר שזהו הכל בעצמו' א\"ס ב\"ה שהוא בחי' אח\"פ ממש א\"כ גם מדותיו הכלולי' בעצמותו הן בבחי' אח\"פ כמו החכמ' הכלולה בו נק' חכים ולא בחכמ' ידיע' כלל כך גם בחי' האחרונה שהוא בחי' המל' שבו הוא באח\"פ שאין לך דבר חוץ ממנו ואין עוד מלבדו כי יחיד ומיוחד הוא כו', וא\"כ איך שייך ענין מלוכה וממשלה שזהו ענין ההתנשאו' וההתפשטו' על דבר נפרד זולתו ובאמת אין עוד מלבדו כו', ואם מצד שהתנשאו' זו היא מצד עצמו ממש כמלך המרומם בעצמותו גם כשהוא לבדו מצד עצם רוממותו שלמעלה הרבה מן הרוממו' שעל זולתו ויש בכלל מאתי' כו', עכ\"ז נק' בשם מדת התנשאו' עכ\"פ (כטבע האדם שהוא"],[1900420031,"בהתנשאו' מצד עצמו שהוא בבחי' אדם שהוא עליון על כל הברואי' ורודה בכולם כו' כידוע) וכל בחי' התנשאו' מורה בחי' ההתפשטו' לחוץ מן העצמות ולא יתכן זה ביחוד האמיתי דעצמו' א\"ס ומדותיו שהן מיוחדי' וכלולי' בו בתכלית האח\"פ כו', ואף מה שמתצמצם בעצמו להיו' מלך כל העולמי' שיהי' אחר הצמצום בקו\"ח כו' גם זה אינו נק' בבחי' מלוכה במהו' ומציא' דבר מה ואינו תופס מקום כלל וכלא ממש חשיב לגבי עצמותו ממש כמו שמו של אדם כנ\"ל, ואף בחי' ההתנשאו' שמצד עצמו שמזה נמשך מח' זו דאנא אמלוך להיו' מל' מלכו' כ\"ע אינו נוגע בעצמותו ממש מטעם הנ\"ל שאין מדה זו הגם שהיא בעצמי' כשאר המדו' דא\"ס חסד וגבו' וחכמ' שהן מעצמו' א\"ס ממש כמו נפש השכלי' כו' שכח השכל כלול בעצם הנפש ונחשב מן העצמו' ממש וכן כח החסד והטוב כו', משא\"כ מדה זו דהתנשאו' שהיא נבדלת מן העצמו' בהתפשטו' והתנשאו' לבד (אך יש בה מבחי' המקיף דכתר ברוממו' העצמו' דיחידה שבנפש כמ\"ש במ\"א<sup data-n=\"115\">115</sup>).\n<b>וזהו</b> לך ה' הממלכה, שאע\"פ שגם במדו' דחו\"ג א' לך ה' הגדולה והגבו' כו', אבל א' איהו וחיוהי חד ממש והיינו בחי' המדו' דא\"ס שכלולי' בו באח\"פ ממש, אבל על בחי' מל' דא\"ס אף כמו שהוא בעצמו' ממש א' בפסוק בפ\"ע לך ה' הממלכה פי' ממלכה ל' מפעיל שהוא מקור כל מלוכה והתנשאו' כמ\"ש והמתנשא לכל לראש כו' והיינו מ\"ש מלכות\"ך מל' כ\"ע ונק' מלך מלכי המלכי' דהיינו בחי' מל' דא\"ס עצמו הנ\"ל שמתצמצם בעצמו להיו' בהתנשאו' והתפשטו' על כל העולמו' להיו' בבחי' מקיף כללי לקו\"ח ומשם נמשך לכל עולם בפרט בחי' המל' שבא בגילוי בהשתלשלו' הפרצופי' דא\"ק וע\"י וא\"א כו' עד מל' דאצי' בבי\"ע עד מל' דעשי' שא' מלך אלקים על גוים ונק' מלך הגוים כו' וכן כי ה' עליון<sup data-n=\"116\">116</sup> נורא שנק' גדול כו' וד\"ל (ומה שא' בע\"ח דבבחי' מל' דא\"ס אין אנו רשאי'<sup data-n=\"117\">117</sup> לדבר בו כו' לפי שהוא בבחי' הסתר והעלם דעצמו' א\"ס ממש שנא' בזה כבוד אלקי' הסתר דבר<sup data-n=\"118\">118</sup> כו', ואע\"פ שמבחי' מל' דא\"ס יוכל לבא בהשתלשלו' להיו' מל' כ\"ע באבי\"ע א\"כ אין הסתר גמור כו', הענין הוא דודאי יש הפרש בזה בין בחי' פנימי' דמל' דא\"ס לבחי' החיצוניו' שבה שמתצמצם להיו' מל' כ\"ע, דבחי' הפנימי' דמל' עולה בפנימי' ועצמו' דא\"ס ממש כמו שבחי' מל' למטה עולה בכת\"ר כמו שא' דכתר מל' איהו כ\"ע ממש כו' כך הוא",[["115","115","<b>אך יש בה מבחי' המקיף דכתר ברוממות העצמו' דיחידה שבנפש כמ\"ש במ\"א</b>: ראה ס' פיה\"מ לאדהאמ\"צ פט, ב ואילך. שער היחודלאדהאמ\"צ פמ\"ח."],["116","116","<b>מלך אלקים על גוים. . כי ה' עליון</b>: תהלים מז, ט. ג."],["117","117","<b>בע\"ח דבבחי' מל' דא\"ס אין אנו רשאי'</b>: ראה ע\"ח שער מ\"ן ומ\"ד (שט\"ל) דרוש ד. ס' מאמרי אדה\"ז ענינים ע' שדמ. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תפו. במדבר ח\"ג ע' א'קנו. דברים ח\"ג ע' תתקלט [ובהמ\"מ במקומות אלו]."],["118","118","<b>כבוד אלקי' הסתר דבר</b>: משלי כה, ב."]]],[1900420032,"גם במל' דא\"ס (ומטעם הנ\"ל בבחי' התנשאו' העצמו' שעולה בפנימי' הכתר דעצמו', והוא ענין יו\"ד פסוקים דמלכיו' בר\"ה שנק' מלך הקדו\"ש שאינו אלא בתורה כמ\"ש בי מלכים ימלוכו<sup data-n=\"119\">119</sup> כו' שהוא ח\"ע העצמי' ולישראל שעלו במח' העצמי') שנק' מלך ישראל דוקא ע\"י קבלת עומ\"ש בתו\"מ דוקא [וכמ\"ש* אמרו לפני מלכיות שתמליכוני עליכם דוקא<sup data-n=\"120\">120</sup>] וכמו במ\"ת שקיבלו מלכותו העצמי' ברצון כו', וע\"ז א' בע\"ח דאין אנו כו' שנבדל בערך הוא מהיו' גם מקור למקור למלכו' כ\"ע, אבל רק בחי' החיצוניות שבה לבד הוא שמתצמצם בקו\"ח להיו' מל' כ\"ע שנק' מלך העולם כו', וזהו שאו' בברכו' המצו' בא\"י מלך העולם לפי שקדשנו כו' (וכמשי\"ת דבמי נמלך בנשמתן של צדיקים כו').\n[יא] <b>אך</b> עדיין יש להבין מה שא' אנת הוא עילא' על כל עילאי' סדכ\"ס דלית מחשבה תפיס' בך כו' הרי משמע מלשון זה דאין שום מחשבה תפיס' בי' כלל, כי יש כמה מיני מחשבות עליונו' בהעלם אחר העלם בריבוי מדרגות זו למעלה מזו כמו מאד עמקו מחשבותיך וכן נפלאותיך ומחשבותיך כו' כנ\"ל ולכולם אין תפיס' כלל במוה\"ע ית' ממש. והענין הוא דודאי יש כמה מדרגו' גם בבחי' מח' העצמי' דא\"ס כמו מח' האחרונה המצומצמת ביותר זהו מה שעלה במח' להיו' מל' כ\"ע בהתפשטו' והתנשאו' שחוץ מן העצמו' ע\"י ריבוי הצמצומי' ביותר להיו' מלך על עם נפרד כו' וכמ\"ש ה' מלך גאות לבש<sup data-n=\"121\">121</sup> שנתלבש בלבוש מל' זה בגיאו' להיות מתנשא מימות עולם לבד כו' כנ\"ל, ואין לדמות ערך כלל לבחי' מח' מצומצמ' זו שנמשכת בצמצום גדול אפי' למחשבו' העליונו' שבהעלם העצמות כמו מאד עמקו מחשבותיך שהן רבים ונובעי' מהעלם עצמותו ממש ומח' זו דמל' כ\"ע אינה רק מח' א' פרטי' שנתצמצם מכל המח' העמוקו' כערך טפה א' בים הגדול כו', והרי א' לית מח' תפיס' בך משמע דכל המח' גם היותר עליונו' ועמוקו' הנ\"ל מאחר שבאי' בבחי' אותיו' המח' שנק' מספר ובאמת לתבונת\"ו העצמי' שזהו כמו כח המח' באדם שכולל כל מיני מח' בעצם שלמעלה מבחי' הגבלת צרופי אותיו' במח' עדיין שאין שייך בזה לומר אפי' כערך ביטול טפה בים שהטפה בים ביטולה במנין וביטול כל המח' עליונו' העמוקו' בכח המח' העצמי' (שנק' מל' דתבונה והוא כח המח' הפנימי' שבחכ' דתוה\"ק שז\"ש לתבונת\"ו כו') שהוא למעלה מן המספר ומנין זהו ביטול המספר בלמעלה מן המספר כו' כי מעצם כח המח' הכללי' נובעי' כל המח' במספר זו למעלה מזו בעומק אחר עומק כמחשבת אדם שמשוטטת ונובעת [בעצמותו] תמיד בלי הפסק כו'.",[["119","119","<b>בי מלכים ימלוכו</b>: משלי ח, טו."],["120","120","<b>וכמ\"ש. . שתמליכוני עליכם דוקא</b>: שורה זו ניתוספה בכת\"י המעתיקים, וליתא בגוכי\"ק [ראה לעיל ס\"ט, הערה המתחלת: אך]."],["121","121","<b>ה' מלך גאות לבש</b>: תהלים צג, א."]]],[1900420033,"<b>והנה</b> מ\"ש לית מח' תפיס' בך משמע אפי' מה שבכח במח' טרם שיוצא לגילוי באותיו' גם מח' זו אין לה תפיס' בך והיינו גם מח' הקדומה שבהעלם העצמו' דא\"ס ממש והוא מה ששיער בעצמו בכח ובהעלם המח' והרצון מה שעתיד להיו' בגילוי בפועל (כמ\"ש בע\"ח בשם האריז\"ל שזהו ענין המא' דגליף גליפ\"ו<sup data-n=\"122\">122</sup> בטהירו עילאה שלמעלה הרבה מטה\"ת מקיף הכללי דאבי\"ע (כמשי\"ת), וזהו ענין שאמ\"ר והי' העולם שזהו במח' הקדומ' בכח והעלם וכמ\"כ כי אמרת\"י<sup data-n=\"123\">123</sup> עולם חסד יבנה (וטה\"ע זו שבא ברצון הפשוט שנק' מח' הפשוט' למעלה מאותיו' הנגלי' עכ\"ז יש בה אותיו' בהעלם שז\"ש גליף גליפ\"ו), וכמו עד\"מ כשעלה במח' ורצון הפשוט בכח והעלם באדם לבנות בנין בכלל שנק' רצון המוחלט שכולל הוא כל מה שעתיד לבא בגילוי בנפשו אח\"כ ברצון וחכ' ומדו' ומח' פרטי' באותיו' מיוחדי' וסוקר הכל כא' ממש כו', ונק' מחשבה אחת דוקא כי כלולה היא מכל הפרטי' יחד ע\"כ נק' מח' אח\"ת לבד, ומאחר שהוא ית' צופה ומביט בשיעור מח' זו האחת בכח ובהעלם עצמותו כל מה שיהי' בגילוי אח\"כ בכללות דסובב וממלא ובפרטות מראש לסוף כא' ממש שזהו עדיין כלול הכל בכח עצמותו ממש בבחי' אח\"פ, ה\"ז למעלה הרבה מבחי' גילוי מח' זו הפשוט' עצמה כאשר יבא ממנה מח' הכללי' דאנא אמלוך להיו' מל' כ\"ע בסקירה א' ג\"כ שזהו מקיף הכללי דקו\"ח כנ\"ל שאינו רק בחי' גילוי דהעלם המח' הקדומ' בעצמו מה ששיער בעצמו בכח עדיין כנ\"ל והיינו כגילוי מח' אחת לכללו' הבנין מראשו לסופו שנק' כלל לפרט מקיף לעלמי' (והוא בחי' טה\"ת שמקבל מטה\"ע הנ\"ל כמ\"ש במ\"א שז\"ש השמי\"ם [ושה\"ש מקיף למקיף זה שנק' כלל כו' שהוא כמו הרגשה כללי' מראש לרגל שאינו רק גילוי דמקיף דיחידה] כו'), ועל שניהם א' לית מח' תפיס' בך אפי' מח' הקדומ' בהעלם העצמו', וכמו מח' זו שנק' מקיף בגילוי שצופה ומביט ממש בסקירה א' לכל הדורו' כו', כי גם בחי' מח' זאת ששיער בעצמו ברצונו הפשוט שייך להיו' מקור להשתלשלו' עכ\"פ ואין לו ערך למוה\"ע אא\"ס ממש כנ\"ל וד\"ל (ואפי' מח' ורצון הקדום שלמעלה גם ממקור להשתלשלו' וכמ\"ש ומקד\"ם אשר לא נעשה עדיין כו' [אפי' בכח והעלם בעצמו כלל כמ\"ש] מאד עמקו מחשבותיך זו למעלה מזו [כולם כלא חשיבי לגבי מוה\"ע ית' ממש] כענין הנ\"ל במ\"ש נפלאותיך ומחשבותיך שלמעלה ממקור לע\"ס וכמ\"ש ולאו מכל אינון מדו' כלל, גם מח' כאלה לית מח' תפיס' ב\"ך ממש, ולכך נק' סדכ\"ס כו' דהיינו שהוא נעלם וסתום מכל מח' סתומי' (רק בחכ' ורצון ומח' דתו\"מ לישראל הוא נתפס ממש (כמשי\"ת).",[["122","122","<b>מה ששיער בעצמו. . בע\"ח בשם האריז\"ל. . דגליף גליפו</b>: ראה מק\"מ לזח\"א טו, א — הובא בשער היחוד לאדהאמ\"צ פ\"י. וראה גם ס' מאמרי אדהאמ\"צ בראשית ע' טו. במדבר ח\"ב ע' שצה [בשם כתבי האריז\"ל]. דברים ח\"א ע' כה וע' קלב. ח\"ב ע' תרלד. ח\"ג ע' תתיח [בשם הע\"ח]. וראה בהמ\"מ במקומות אלו."],["123","123","<b>כי אמרתי</b>: תהלים פט, ג."]]],[1900420034,"[יב] <b>אך</b> הנה אע\"פ שא' דלית מחשבה תפיסא בך אפי' מח' הקדומ' הנ\"ל ואפי' מה שלמעלה ממחה\"ק במה ששיער בעצמו בכח כו' שהוא בחי' מל' דא\"ס עצמו הנ\"ל שנמשך מזה להיו' מל' כ\"ע, מ\"מ יש בחי' מחשבה שהיא בבחי' עצמו' ופנימי' דא\"ס ב\"ה ממש שיש לה תפיס' במוה\"ע ית' והוא נתפס בה ממש, והן ב' דברי', הא' בחי' מחשב' דחכ' דתורה הקדומה שא' בה ואהי' אצלו אמון (אלפים שנה קודם שנברא העולם<sup data-n=\"124\">124</sup>) שעשועי' כו' בחי' שעשועי' העצמיי', כי כל מוה\"ע ית' נתפס בה להיותה בבחי' חכמתו הפנימי' ועצמיו' ממש, וע\"כ אין מח' וחכ' דתור' כשאר מחשב' שבאה בבחי' התפשטו' חיצוניו' לחוץ מן העצמו' שכלא חשיבא לגבי אור העצמו' כנ\"ל, ואפי' במח' דבחי' מל' בחי' התנשאו' העצמו' הנ\"ל ה\"ז ג\"כ נמשך רק ע\"י חכ' ומח' דתוה\"ק הנ\"ל כמ\"ש התורה בי מלכי\"ם ימלוכו<sup data-n=\"125\">125</sup>, והן יו\"ד פסוקים דמלכיות בר\"ה כנ\"ל, שכאשר נאמר בתור' ה' ימלו\"ך כו' נמשך בחי' גילוי אור דהתנשאו' העצמו' אף למטה בע' שרים דנוג' במל' דעשי', כמ\"ש תפול עליהם אימת\"ה<sup data-n=\"126\">126</sup> בה\"א שמרמז על מל' דא\"ס הנ\"ל שיורד עד מל' דמל' דעשי' כו' שעי\"ז מתבטלי' ממציאותם לגמרי לפרקי', כמו שהי' בנבוכדנצר ומחנה סנחרב<sup data-n=\"127\">127</sup> כו', וכן יהי' לע\"ל בגילוי פחד ה' על כל הברואי' כמו שאו' ושמך נור\"א<sup data-n=\"128\">128</sup> על כל כו', וזהו שמתחדש בכל ר\"ה ור\"ה דוקא כשיהי' נזכר יו\"ד פסוקים דמלכיו' בתנ\"ך ע\"י ישראל דוקא אז יאיר מחדש באור מל' דא\"ס הנ\"ל שיהי' נק' מלך הקדוש להיו' מל' כ\"ע מחדש כו', והיינו משום דג' קשרין<sup data-n=\"129\">129</sup> ישראל מתקשרא' באוריי' ואוריי' בקודב\"ה בב' מדרגו' דסתים וגליא, דאוריי' סתים וגליא היינו בחי' סתים דחכ' הקדומ' שנק' תורה של מעלה הנ\"ל שכלולה בסדכ\"ס דלמחת\"ב כלל כנ\"ל וגם ישראל שרשן במח' סתימא' העצמי' הנ\"ל (כמשי\"ת), וז\"ש בי מלכי' דבחי' מלכותך מל' כ\"ע הנ\"ל ימלוכו להיו' דמח' וחכ' דתוה\"ק הוא בחי' הפנימי' ועצמו' דא\"ס ב\"ה שממנו ימצא מקור להתגלו' בחי' המל' דא\"ס כמ\"ש לך הממלכ\"ה כנ\"ל וד\"ל. וזהו שאנו רואי' דאע\"ג דלמת\"ב כלל כנ\"ל דאפי' אור צח דחכמ\"ה ומח' הקדומ' שכולל כללות כל ההשתלשלו' דאבי\"ע אוכם הוא כו', עכ\"ז נתפס הוא אף בחכ' דתורה הנגלית לנו למטה בעוה\"ז, וכמארז\"ל דמשחרב בהמ\"ק<sup data-n=\"130\">130</sup> אין להקדב\"ה בעולמו רק ד\"א של הלכ\"ה בלבד שהן במקום היכל ק\"ק ממש וכמו שנתפס בהיכל ק\"ק אע\"פ שא' שהשמים ושה\"ש לא יכלכלוה\"ו",[["124","124","<b>אלפים שנה קודם שנברא העולם</b>: ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. ויק\"ר פי\"ט, א. תנחומא וישב ב. ועוד."],["125","125","<b>בי מלכים ימלוכו</b>: משלי ח, טו."],["126","126","<b>תפול עליהם אימתה</b>: בשלח טו, טז."],["127","127","<b>בנבוכדנצאר ומחנה סנחרב</b>: ראה סנהדרין צה, ב. ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' מט. ח\"ב ע' תז. ח\"ג ע' א'מא. ח\"ד ע' א'תקעח. ח\"ה ע' א'תרכט. וש\"נ."],["128","128","<b>ושמך נורא</b>: תפילת עמידה דימים נוראים."],["129","129","<b>דג' קשרין</b>: ע\"פ זח\"ג עג, א. וראה בס' מאמרי אדהאמ\"צ בראשית ע' כו. ויקרא ח\"א ע' צט. וש\"נ."],["130","130","<b>דמשחרב בהמ\"ק. . ד' אמות של הלכה</b>: ברכות ח, א."]]],[1900420035,"(שזהו בחי' טה\"ע וטה\"ת הנ\"ל) מ\"מ נתפס בד\"א של הלכה, וראי' ממה שא' אשר יקראוהו באמת דתורה שיקראו למוה\"ע ממש, וכמו שא' דכל הקורא בתורה קורא בשמותיו<sup data-n=\"131\">131</sup> ממש העצמיי' שלמעלה משם ומל' דמל' דא\"ס הנ\"ל מאחר שא' בי מלכי' כו', והיינו משום דאוריי' דבחי' סתים מתקשרא בקודב\"ה ממש שהוא סדכ\"ס כנ\"ל וד\"ל.\n<b>והנה</b> כמ\"כ יש מחשבה פנימי' ועצמיו' שהוא ית' ממש נתפס בה, והוא שרש נש\"י שעלו במח', שאין מחשבה זאת כשאר מח' הנ\"ל שהן בטילי' לגבי העצמו' שהן בהתפשטו' חיצוניו' במח' דאנא אמלוך הנ\"ל, אבל מח' זו שישראל עלו בה היא בבחי' פנימי' ועצמיו' ממש דהיינו עצמו' הרצון הפשוט כמו שהוא בעצמו ממש ולא בבחי' התפשטו' לבד להיותם בבחי' עצמיו' ממש כמ\"ש כי אתה אבינו את\"ה ממש כו', וכן א' הבן יקיר לי אפרים ילד שעשועי' עצמיי' כבן שנמשך מעצמו' האב ממש וכמ\"ש בנים אתם<sup data-n=\"132\">132</sup> כו' ע\"כ המו מעי לו ממש כמו בכל צרת\"ם לו צ\"ר ממש, ולכך א' לא הביט און ביעקב כו' ותרוע\"ת מלך בו כו' (כמ\"ש במ\"א<sup data-n=\"133\">133</sup>) (רק שעכ\"ז התקשרו' דנש\"י למעלה ג\"כ ע\"י אותיו' התוה\"ק (שזהו דגליף גליפו כו' בבחי' חקיקת אותיו' עצמיי' שנק' חוק\"ת התורה, והן ס\"ר נש\"י למטה שקשורי' בס\"ר אותיו' התו' בגליא, שזהו דישראל מתקשרא' באוריי') (וכמו שהי' במ\"ת שעל כל דיבור פרחה כו' עכ\"ד דוקא שהן ד\"ת, וגם עכשיו לא תעלה כל נשמה ליכלל ולהתקשר בעצמו' א\"ס ב\"ה הגם שכבר ישראל עלו במח' העצמי' כ\"א ע\"י קריא' באותיו' התורה דוקא כנ\"ל וד\"ל).\n[יג] <b>וראי'</b> לכל זה הוא מה שא' במדרש במי נמלך<sup data-n=\"134\">134</sup> בנשמתן של צדיקי' דוקא, וזהו פלא גדול לכאורה דהלא נשמו' הצדיקי' הן שנבראו אח\"כ מאין ליש בגופי' ואיך נמלך בהן קודם שברא את העולם אם יברא אם לאו כו'. אך הנה ידוע ומבואר במ\"א בפי' נמלך זה שזהו שנמלך בהן אם יהי' לו רצון ומח' לברוא ולהאציל כו', והיינו כמו שהי' הוא ושמו הגדול הנ\"ל בלבד קודם ההשתלשלו' דקו\"ח בכללות שזהו בחי' מל' דא\"ס כמו שהוא קודם הצמצום הראשון כנ\"ל, וענין נמלך היינו כמו שאדם נמלך עם אהובו וריעו הנאמן כנפשו אם יעשה דבר פ' ויהי' לו רצון וחשק לזה אם לא יחפוץ כלל בזה שזהו שלא יהי' לו רצון לרצון זה כו', ונמצא דריעו הנאמן בודאי גבוה ונכבד בעיניו",[["131","131","<b>דכל הקורא בתורה קורא בשמותיו</b>: ראה בפתיחת רמב\"ן עה\"ת. זח\"ב פז, א. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' קלט."],["132","132","<b>כי אתה אבינו. . הבן יקיר. . בנים אתם</b>: ישעי' סג, טז. ירמי' לא, יט. דברים יד, א."],["133","133","<b>בכל צרתם. . לא הביט. . כמ\"ש במ\"א</b>: ישעי' סג, ט [וראה מגילה כט, א]. בלק כג, כא. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' א'תקמח."],["134","134","<b>במי נמלך. . במ\"א בפי' במי נמלך</b>: ב\"ר פ\"ח, ז. ראה סידור עם דא\"ח עו, ב. אמרי בינה (מג, רע\"ב). שערי תשובה ח\"א מ, רע\"ב. ח\"ב מא, א. דרך חיים קו, א. עט\"ר נב, ג."]]],[1900420036,"הרבה יותר מכל ענין רצון זה שבדעתו לעשותו עד שבו תולה רצון אם יסכים הוא ירצה בו וא\"ל לא יחפוץ ברצון זה כלל. וכך יובן הנמשל מזה במה שא' נמלך בנשמתן של צדיקים, דודאי מוכרח לומר דנשמו' צדיקי' הללו כבר עלו במח' העצמי' ופנימי' שנבדל בערך לגמרי מכל עיקר ומקור של הרצון הזה להשתלשלו' העולמו' בכלל ובפרט וע\"כ בהן נמלך ומתיישב אם יהי' לו רצון ועונג בזה אם לאו, והיינו גם מה שמבחי' מל' דא\"ס שהוא התנשאו' שמצד עצם רוממותו יהי' לו רצון ועונג בעצמו' ממש כנ\"ל דגם בבחי' מל' דא\"ס עצמו הנ\"ל אינו רק בחי' גילוי אור בעלמא לגבי מוה\"ע ית' ממש, וע\"כ גם במח' ורצון זה נמלך בנשמתן ש\"צ, שמזה מוכרח ששרש נשמו' דצ\"ג למעלה הרבה גם מזה, והוא בעצמו' הרצון וח\"ע העצמי' דתוה\"ק הנ\"ל, וכמו שא' בתור' בי מלכי' ימלוכו כנ\"ל כך הוא גם בנש\"י בשרשם במח' העצמי' הנ\"ל שנמלך בהן, והן י\"פ דמלכיו' שאו' ישראל דוקא בי\"פ דתנ\"ך שאז מתעורר להיו' בחי' מלך הקדוש כנ\"ל וד\"ל, והוא מטעם הנ\"ל דג' קשרי' דישראל ואוריי' וקודב\"ה בבחי' סתים הכל א' ממש, וכ\"ש מה שמתצמצם מבחי' מל' דא\"ס עצמו להיו' מלך גיאו' לבש כנ\"ל שיהי' מלכותך מל' כ\"ע (שנק' מח' דאנא אמלוך כנ\"ל) בודאי רצון ומח' זו להיו' מלך על בחי' נפרד שיהי' ע\"י הצמצום אח\"כ ודאי נמלך בנשמתן ש\"צ דאם יסכימו גם הם כן יהי' כו', דהיינו בתנאי כאשר יומשך גילוי אור פנימי' דמל' דא\"ס בתומ\"צ בפו\"מ למטה ובנש\"י דוקא אז יהי' לו רצון ועונג במח' זו דאנא אמלוך כו' ויומשך אור חדש במל' דא\"ס עצמו כנ\"ל, ולהיו' שסוף מעשה דצדיקים גמורים בתורה ומצות למטה עלה במחשבה תחילה ע\"כ צדיקי' הללו גוזרי' בכל ר\"ה שיהי' לו רצון ועונג זה (כמשי\"ת).\n<b>והנה</b> מכל זה יובן עכ\"פ שבחי' ראשית הטיית מוה\"ע ית' ממש בבחי' האחדות פשוטה שלו להיו' בבחי' התנשאו' העצמו' במדה זו דמל' דא\"ס עצמו ושיהי' מתצמצם במח' דאנא אמלוך להיו' מל' כ\"ע בר\"ה כנ\"ל היינו לפי שנמלך בזה בנשמתן ש\"צ דוקא, וכמו שא' בראשית בשביל ישראל כו' ובשביל התור' שנק' ראשית כמ\"ש ה' קנני<sup data-n=\"135\">135</sup> ראשית דרכו פי' בראשית הטיית מוה\"ע להיו' לו רצון במלוכה העצמי' ובהתפשטו' שלה כנ\"ל, והיינו לפי ששרש נש\"י והתורה הוא בבחי' מח' הפנימי' ועצמיו' דא\"ס ב\"ה ממש ע\"כ בהן נמלך אם יהי' לו רצון לרצון ועונג זה אם לאו, וזהו שאמר שתנאי הי' כו' וכתי' אם לא בריתי<sup data-n=\"136\">136</sup> כו' חוקות שמים וארץ לא שמתי וד\"ל.\n<b>והנה</b> באמת זהו הטעם לענין מה שע\"י אתדל\"ת דישראל דוקא מעוררי' אתדל\"ע בעצמות א\"ס ב\"ה שיאיר מעצמותו ומהותו ברצון ותענוג מחדש בבחי' מדת המל' שבעצמו ולהיו' מלכותו מל' כ\"ע כמו בכל ר\"ה ור\"ה",[["135","135","<b>בראשית בשביל ישראל. . ה' קנני</b>: רש\"י ר\"פ בראשית. משלי ח, כב."],["136","136","<b>שתנאי הי'. . אם לא בריתי</b>: שבת פח, א. ירמי' לג, כה."]]],[1900420037,"שנמשך מחדש בחי' מל' דא\"ס באבי\"ע כנ\"ל (וכמ\"ש בע\"ח דמתחלת ההשתלשלו' הי' חפץ חסד מצד עצמו ואח\"כ תלוי במעשה התחתוני'<sup data-n=\"137\">137</sup> דוקא) (ולפי הנ\"ל דנמלך בנשמתן ש\"צ הי' בתחלה ג\"כ מצד העלא' דסוף מעשה הצדיקי' במח' הקדומ' שמפני זה נעשה לו רצון לרצון כו' כנ\"ל), וכך בכל יום ויום מחדש מע\"ב ממקורו הראשון (רק שבר\"ה הוא זכרון ליום ראשו\"ן בבחי' הכללו' יותר כמ\"ש במ\"א<sup data-n=\"138\">138</sup>), שחידוש זה בא באתדל\"ע מעצמות א\"ס ב\"ה ע\"י העלא' מ\"ן דישראל למטה בכל יום שמקבלי' עליהם עול מלכות שמים ברצון באהבה ויראה, כמו בק\"ש שאו' שמע ישראל כו' במס\"נ באחדות פשוטה בהמשכו' מלכו' שמים דוקא וכמא' תמליכהו בשמים וארץ וד' רוחות<sup data-n=\"139\">139</sup> כו', ואע\"פ שכבר נק' מלך העולם שנמשך מבחי' מל' דא\"ס עצמו כנ\"ל אבל צריך לחדש זה בכל יום כנ\"ל, ואע\"פ שבאמת הרי א' לך ה' הממלכה אפי' בחי' מקור כל מלוכה והתנשאו' האלקי' כלא חשי\"ב לגבי מוה\"ע ית' ממש וא\"כ מאיזה טעם יהי' לו צמצום ודילוג הערך כזה להיו' לו ית' חפץ ורצון במח' זו דמל' כו', אך ע\"י התעוררו' שלמטה ע\"י נש\"י דוקא הוא שבאה אתדל\"ע זאת במוה\"ע ית' ממש.\n[יד] <b>והנה</b> לכאורה יש בדבר זה פלא גדול, דמאחר שעיקר הטעם לזה שיש ביכולת נש\"י דוקא לעשו' אתדל\"ע זו הוא דוקא מצד שרש נשמתם למעלה מעלה שעלה במח' העצמי' והפנימי' דא\"ס ב\"ה בעצמו' ממש כנ\"ל, א\"כ מה צורך להעלא' זו באתדל\"ת ע\"י מעשיהם דוקא והוא כאשר נשמתם מלובשי' בגופי' גשמיים וחומריי' והן מוסרי' נפשם באחד בק\"ש אפי' בגופם ובממונם באמרם ואהבת כו' בכל לבבך<sup data-n=\"140\">140</sup> ובכל נפשך כו' וע\"י שמקבלי' וממשיכי' עול מ\"ש עליהם ועל כל העולם כמא' תמליכה\"ו בשמים כו' וכן ע\"י מעשה המצות בפ\"מ ולימוד התורה בקול ודיבור דוקא כידוע ולמה נצרך לכל זאת אם יש כח זה בנשמתם מצד שרשם בעצמו' א\"ס ב\"ה ממש כנ\"ל. אך הענין הוא כמבוא' למעלה בענין המאמר דבמי נמלך בנשמתן של צדיקים דגם זה פלא לכאורה, דהלא קודם הבריא' וההשתלשלו' לא היו נשמו' צדיקי' בגופי' רק בחי' שרשם העצמי' לבד והרי גם בנשמו' הללו כמו שהיו בשרשם לא נמלך רק מצד סוף מעשה שלהם שעבמ\"ת כנ\"ל, ולמה לא די בזכות צדקתם העצמי' כמו שהן דבוקי' בעצמו' א\"ס ב\"ה שעלו שם במח' שגדול ודאי יותר מנשמו' שבגופי' כו'. וכמ\"כ יש להפליא על ענין מ\"ש אם לא בריתי כו' דזהו",[["137","137","<b>וכמ\"ש בע\"ח דמתחלת. . חפץ חסד. . במעשה התחתונים</b>: שער דרושי הנקודות (ש\"ח) ספ\"ו."],["138","138","<b>שבר\"ה הוא זכרון ליום ראשון. . כמ\"ש במ\"א</b>: ראה סה\"מ תקס\"ז ע' שמ ואילך. לקו\"ת ר\"ה נג, ד."],["139","139","<b>תמליכהו בשמים וארץ וד' רוחות</b>: ראה ברכות יג, ב: כיון דאמליכתי' למעלה ולמטה ולד' רוחות כו'. ובזח\"ג רכג, ב ואילך: שתמליכהו על השמים ועל הארץ כו' ועד\"ז בזהר שם ערב, א. וראה גם ס' מאמרי אדהאמ\"צ בראשית ח\"א ע' לד, ובהמ\"מ שם שנסמן לכ\"מ בדא\"ח שהובא לשון זה."],["140","140","<b>ואהבת כו' בכל לבבך</b>: ואתחנן ו, ה."]]],[1900420038,"בשביל התורה כו', למה דוקא בברית דתור' שבאה למטה בקיום המצו' בפ\"מ הנגלו' לנו ולמה לא בעבור התוה\"ק עצמה שהיא בבחי' סתים בסדכ\"ס עצמו כנ\"ל. אך הענין הוא כמבואר למעלה דראשית סיבת הטיית מוה\"ע ית' ממש להיו' לו רצון גם במל' דא\"ס שהוא התנשאו' העצמו' ג\"כ נמלך בנש\"צ ובתורה הק' כמ\"ש בי מלכי' כו' והיינו בנש\"צ ותוה\"ק שבבחי' סתים דוקא כנ\"ל, וא\"כ מה צורך להתעוררו' די\"פ דמלכיו' בר\"ה באתדל\"ת דוקא בנש\"י שבגופי' ובי\"פ דתנ\"ך כו', אך צריך לומר שיש ב' מדרגו' במל' דא\"ס הנ\"ל, א' בחי' החיצוניו' דמדת ההתנשאו' אף שהוא בעצמו לבד ה\"ז למטה מן החכ' והמדו' דא\"ס (שזהו שרש החכ' דתור' בבחי' סתי\"ם ושרש נש\"י שעלו במח' במדו' דא\"ס שנק' ימ\"י קדם<sup data-n=\"141\">141</sup>, והוא בחי' יש\"ס<sup data-n=\"142\">142</sup> בכלל), ע\"כ ע\"י בחי' החכ' דתוה\"ק וישראל שעבמ\"ח נמשך להיו' מלך מלכי כו', וזהו בחי' ומדרג' דע\"ס דאו\"י בעצמו' א\"ס שנק' ע\"ס הגנוזו' בעצמו' המאציל כו', ואמנם מדרג' הב' בבחי' מל' דא\"ס כמו שהיא עולה בבחי' או\"ח דוקא כמו סוף מעשה כו' בבחי' הפנימי' ועצמו' ממש שנק' כבוד הד\"ר מלכות\"ו (שאינו מאיר בעולמו' ומלאכי' כלל (כמ\"ש במ\"א) זהו בפנימי' ועצמו' דא\"ס בפנימי' הכתר שהאיר במ\"ת (כמ\"ש במ\"א על מ\"ש יביאו לבוש מל'<sup data-n=\"143\">143</sup> כו' [ועמ\"ש* ויהי בישורון מלך שזהו שנק' הד\"ר מלכותו ע\"י עומ\"ש שבמצות דוקא ולכן נק' כנ\"י יפ\"ת ששרשה מבחי' יופי דלבוש מל' כו'<sup data-n=\"144\">144</sup>]), והוא בעצמו' התענוג הפשוט ורצון הפשוט שלמעלה מן החכ' לגמרי אפי' חכ' דא\"ס שנק' כת\"ר שבכת\"ר שהחכ' רק מאין תמצא כו' (והוא כמו העוה\"ב שלמעלה גם מרזי' דאוריי' שיתגלה במשיח (כמשי\"ת), שזהו למעלה מחכ' הקדומ' דתוה\"ק ומדו' במח' דנש\"י העצמי', וכמ\"ש בזוהר אוריי' קדישא וישראל קדישי' אבל אין קדוש<sup data-n=\"145\">145</sup> כה' עצמו שלמעלה מתו\"מ וישראל כו', וזהו שעולה במוה\"ע הא\"ס ממש שנק' מאור שלמעלה מבחי' אור אפי' אור דתור' הק' וישראל כו', שגם שהי' בבחי' שעשועי' העצמיי' כמ\"ש ואהי' אצלו ממש שעשועי' אין לזה ערך לשעשועי המלך בעצמו ממש וד\"ל.\n<b>וזהו</b> שא' כל הנק' בשמי<sup data-n=\"146\">146</sup> ממש ולכבוד\"י ממש שבבחי' מל' דא\"ס כמו שהוא בעצמו' התענוג הפשוט (כנ\"ל שזהו ענין מקיף דהתנשאו' לרומם לבחי'",[["141","141","<b>שנק' ימי קדם</b>: ראה ביאוה\"ז מח, א. סידור עם דא\"ח רכט, ג. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתנא. דברים ח\"א ע' נה וע' פט."],["142","142","<b>יש\"ס</b>: ישראל סבא."],["143","143","<b>במ\"א על מ\"ש יביאו לבוש מל'</b>: ראה ד\"ה יביאו לבוש מלכות — בשערי אורה ס, א ואילך."],["144","144","<b>ועמ\"ש ויהי בישורון. . דלבוש מל' כו'</b>: פיסקא זו ניתוספה בכת\"י מעתיקים, וליתא בגוכי\"ק אדהאמ\"צ [ראה לעיל ס\"ט, הערה המתחלת: אך]. וצ\"ב עדיין לאיזה מאמר (ע\"פ ויהי בישורון) כוונתו כאן. וראה סה\"מ תקס\"ו ע' שסח ואילך. ס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'תיז."],["145","145","<b>אוריי' קדישא. . אין קדוש</b>: ע\"פ זח\"ג מד, א. שמו\"א ב, ב. וכן מובא בכ\"מ — ראה ס' מאמרי אדהאמ\"צ שמות ע' תקטז. ויקרא ח\"א ע' שסד. ח\"ב ע' תקלג. במדבר ח\"א ע' פז. ח\"ב ע' תרפד. דברים ח\"ג ע' תתקג. לעיל ח\"א ע' מה. וראה עוד בהמ\"מ בספרים אלו."],["146","146","<b>כל הנק' בשמי</b>: ישעי' מג, ז."]]],[1900420039,"העצמו' ממש כו') בראתיו כו' אף עשיתי\"ו, ואף לרבותא דבמעשה המצו' דוקא באדם דעלי' נשמו' בגופי' הוא שנמשך בחי' פנימי' מל' דא\"ס ברוממו' העצמו' בבחי' שעשועי המל\"ך בעצמו ממש שמשם נמשך להיו' מלך הקדוש לגבי ההשתלשלו' דקו\"ח באבי\"ע לפי שסוף מעשה דוקא עבמ\"ת דהיינו תחלה וקודם לכל המח' ורצון אפי' למח' ורצון וחכ' דתו\"מ ונש\"צ הקדומי' הנ\"ל שהרי אין ביכולתם מצד שרש עצמותם לעורר לפנימי' הכת\"ר שבמל' בעצמו' א\"ס ב\"ה ממש, וע\"ז א' כבוד אלקי' הסתר דבר וכתי' ורוח אלקי'<sup data-n=\"147\">147</sup> כו' שזהו בבחי' קדושת העצמו' דא\"ס ממש שאין תו\"מ שלמעלה ונש\"צ שלמעלה מגיעי' לשם כלל רק ע\"י העלא' מ\"ן דנש\"י בגופי' בעסקם בתומ\"צ בגשמיו' דוקא וכמו במס\"נ בק\"ש אפי' בגופי' ובד\"ת המלובשי' בגשמיו' ובקבלת עמ\"ש במצות הנעשי' בגשמיות דוקא הוא שמעוררי' לבחי' פנימי' מל' דא\"ס בשעשועי המלך בעצמו ממש שנק' הד\"ר מלכות\"ו ממש (שלמעלה גם מהתנשאו' דמדת מל' דא\"ס מצד עצמו וגם מחכ' דתוה\"ק), כי נעוץ תחילתן בסופן וסופן בתחילתן דוקא לפי שנתאוה ה' להיו' לו ממש דירה בתחתוני' דוקא ולא בעליוני' אף לא בחכ' דתוה\"ק ונש\"צ כו' (כמ\"ש אל יתהלל<sup data-n=\"148\">148</sup> כו' השכל וידוע אותי ממש ע\"י חסד ומשפט וצדק' [דתו\"מ בארץ דוקא כי באלה חפצתי בעצמות התענוג ממש)].\n[טו] <b>וזהו</b> הטעם דע\"י יו\"ד פסוקים דמלכיו' בתנ\"ך ע\"י נש\"י בגופי' דוקא הוא שמתעורר להיו' מלך הקדוש מעצמו' השעשועי' בהד\"ר מלכותו העצמי' שזהו בקבלת עמ\"ש [בעול* מצות שא\"א<sup data-n=\"149\">149</sup> שיקבלו זה מלאכי' בעומ\"ש שלהם אף שנמשך] עליהם מבחי' כת\"ר מל' דאצי' ששרשו רק במל' דא\"ס בקו\"ח להיו' מל' כ\"ע כנ\"ל וד\"ל, אבל מ\"מ ע\"י נש\"י דוקא שמלובשי' בגופי' ונק' עבדי' בעמ\"ש להיו' [שרשם כלולי' בעצמו' המח' כנ\"ל ע\"כ כשיבאו בגופי' בעוה\"ז ויקיימו תו\"מ בפו\"מ] זהו שנעשה לו ממש דירה בתחתוני', והוא כמו ד\"א של הלכה בנגלה דוקא שנתפס בהן כנ\"ל וכן במעשה הצדק' והמצו' בפו\"מ, וז\"ש אם לא בריתי כו' [בפו\"מ דוקא וע\"י ישראל בעוה\"ז דוקא, וז\"ש בראשית בשביל התור' וישראל שלמעלה כו'] שיבאו לידי שלימות האמיתי כאשר יבאו למטה בגשמיו' [כמו<sup data-n=\"150\">150</sup> שאין חכם כבעל הנסיון כו' כמ\"ש במ\"א<sup data-n=\"151\">151</sup>] ויהיו לו דירה ממש שלא הי' זה ביכלתם תחלה כו' וד\"ל. [וזהו* אז ראה ויספרה בתוה\"ק<sup data-n=\"152\">152</sup> הבינה כו' עד ויאמר לאדם דעשי' בגוף הן יראת ה' היא",[["147","147","<b>כבוד אלקי' הסתר דבר. . ורוח אלקי'</b>: משלי כה, ב. בראשית א, ב."],["148","148","<b>אל יתהלל</b>: ירמי' ט, כב-כג."],["149","149","<b>בעול מצות שא\"א</b>: כמה תיבות קרועות בשולי הגליון של הגוכי\"ק, ונשלמו כאן ע\"פ כת\"י מעתיק [בתוך חצאי מרובע]."],["150","150","<b>כמו שאין חכם. . וזהו אז ראה. . בינה ש\"מ כו'</b>: פיסקאות אלו לא נרשמו בגוכי\"ק, כ\"א ניתוספו בכת\"י מעתיקים — ראה לעיל ס\"ט, הערה המתחלת: אך."],["151","151","<b>שאין חכם כבעל הנסיון כו' כמ\"ש במ\"א</b>: ראה לעיל ח\"א ע' פב, ובמ\"מ שם."],["152","152","<b>אז ראה ויספרה בתוה\"ק</b>: [ בתורה הקדומה]. איוב כח, כז ואילך. וראה תו\"ח לך פו, א. ס' מאמרי אדהאמ\"צ בראשית ע' לב. נד. תצה. שמות ח\"ב ע' שסט. שפג. במדבר ח\"ד ע' א'תנג. וש\"נ. דברים ח\"ג ס\"ע תשע\"ג. וש\"נ. נ\"ך ע' עו ואילך."]]],[1900420040,"שלימות חכמה של מעלה כו' וסור מרע היא שלימות בינה ש\"מ כו'] וזהו שנמלך בנש\"צ [שעלו במחה\"ק דהיינו ממה שיעבדו עבודה תמה בעוה\"ז בתו\"מ דוקא כנ\"ל] דסוף מעשה עבמ\"ת ולא שנמלך בהן מצד עצמן כי עיקר מה שנמלך הוא בשביל גילוי כבו\"ד הד\"ר מל' דא\"ס כמו מלך ביופיו כו' [שלמעלה מהם כנ\"ל (וזהו מי הוא זה מלך הכבוד שנסתר בעצמו' ממש] ה' עזוז וגבור במלחמת' של תו\"מ למטה דוקא, ולאחר שלימו' הבירור הוא שא' ה' צבאו' הוא מלך הכבו\"ד סלה וכמ\"ש וע\"י יתיב<sup data-n=\"153\">153</sup> כו' מלכותי'<sup data-n=\"154\">154</sup> כו'). [ונמצא מובן מכ\"ז דבחי' המעשה גשמי'] דישראל בתו\"מ גדולה יותר מכל העלא' מ\"ן אפי' ממס\"נ באוי\"ר בק\"ש כו' מצד שהמעשה סוף הכל שנעוץ בו מתחלת כל התחלות [יותר, שזהו ענין הנ\"ל] בסיבת התעוררו' הטיי' מוה\"ע ית' ממש להיו' לו רצון וחפץ במל' דא\"ס בעולמו' שאין זה בא רק מסיבת העלא' מ\"ן [דישראל במעשה המצות] שמעוררי' בזה דוקא לבחי' הארת פנימי' דמל' דא\"ס הנ\"ל (שיתגלה בעוה\"ב כמ\"ש היום לעשות\"ם דוקא [ולמחר<sup data-n=\"155\">155</sup> כו')] והרבה יותר ממה שמעוררי' בנשמתם באהבה ויראה כו' כנ\"ל).\n<b>והנה</b> עכ\"פ הרי מובן מכל הנ\"ל דאע\"ג דסדכ\"ס למת\"ב כלל אפי' מח' דתוה\"ק וישראל שעבמ\"ח רק ע\"י קיום התו\"מ למטה דוקא הוא שנעשה אתדל\"ע בעצמו' אא\"ס בבחי' פנימי' דמל' דא\"ס וגם בחיצוניו' דמל' דא\"ס בקו\"ח להיו' מל' כ\"ע כנ\"ל בענין י\"פ דמלכיו' בר\"ה כו' משום דנתב\"ס בסוף מעשה וע\"י ישראל ותו\"מ שלמטה דוקא. ואמנם זהו דוקא ע\"י בחי' שמחה ש\"מ בגשמיו' למטה דשמחה זו עולה למעלה בעצמו' התענוג והרצון הפשוט בבחי' שעשוע\"י המלך בעצמו ממש הנ\"ל, וזהו תחת אשר<sup data-n=\"156\">156</sup> כו' בשמחה וטוב לבב דוקא מרוב כל למעלה מחיי העוה\"ב שנק' כ\"ל, והטעם הוא לפי ששמחה של מצוה מגיע בעצמו' בעל הרצון העליון שלמעלה מעונג ורצה\"ע עצמו שבמצות לפי ששמח' זאת אינו רק לפי שעשה נח\"ר ליוצרו לעשו' רצונו כו' שמזה יש תענוג פשוט ושמחה עצמי' למעלה להיו' מתגלה מבחי' העלם העצמו' דא\"ס שנק' סדכ\"ס דלמת\"ב כלל שיבא לגילוי דוקא מן ההעלם כמו שהוא באמיתי' מוה\"ע ית' ממש (מטעם שית' בסמוך בענין טבע השמחה כו'), וזהו וישמחו בך ישראל מקדשי שמך על תו\"מ בשמחה ש\"מ מקדשי שמך במל' דא\"ס בבחי' הפנימי' דוקא, וכן א' שם נשמח\"ה בו<sup data-n=\"157\">157</sup> ב\"ו ממש שהוא בעוה\"ב דוקא כנ\"ל.",[["153","153","<b>ה' צבאות. . וע\"י יתיב</b>: תהלים כד, י. דניאל ז, ט."],["154","154","<b>מלכותי'</b>: דניאל ג, לג: מלכותי' מלכות עלם. ועד\"ז שם ז, כז."],["155","155","<b>היום לעשותם. . ולמחר</b>: ואתחנן ז, יא. ראה עירובין כב, א."],["156","156","<b>תחת אשר</b>: תבוא כח, מז."],["157","157","<b>שם נשמחה בו</b>: תהלים סו, ו."]]],[1900420041,"<b>אך</b> הנה<sup data-n=\"158\">158</sup> כל זה הנה יתעורר אתדל\"ע בעונג ושמח' בעצמו' א\"ס ממש ע\"י אתדל\"ת דוקא כמו במעשה המצו' בשמחה ובמס\"נ בק\"ש ובדיבור דד\"ת שהן ד\"א של הלכה וכה\"ג כנ\"ל, אבל הנה יש בחי' אתדל\"ע שבאה רק מצד עצמו ממש שלא ע\"י אתדל\"ת כלל וכלל אף לא ע\"י תו\"מ בשמח', כמו לפרקים בעת רצון למעלה אע\"פ שאין אתדל\"ת כלל מלמטה יוכל להיו' אתדל\"ע מעצמו ממילא ומאליו שיוכל להיו' גדול יותר הרבה במעלה ומדרגה מאתדל\"ע שע\"י אתדל\"ת הנ\"ל. ואמנם זהו ג\"כ ע\"י בחי' שמחה דוקא רק ששמחה זו היא באה ג\"כ מצד עצמו דוקא כו' וד\"ל.\n[טז] <b>והנה</b> תחלה יש להקדים בשרש ענין השמחה<sup data-n=\"159\">159</sup> מה זו עושה כו'. דהנה בדרך כלל הנה אנו רואי' במהות טבע השמחה שהיא פורץ גדר הטבעי הנהוג מכבר לשנותו מן הקצה לקצה, ושינוי הזה שנעשה ע\"י השמחה לפרקים הוא בין בהנהגה הגדורה מכבר עד שהוא כמו טבע שני שהוטבע בו בין גם בעצם הטבע שנטבע בנפשו מתולדתו בבטן יוכל להיות גם בזה שינוי הטבע לפרוץ הגדר של הטבעיו' לגמרי מכל וכל כו'. והנה לב' מיני שינויי' הללו יש ב' טעמי' וב' סיבות לזה במהו' השמחה, הא' מצד שטבע השמחה שבנפש לגלות מן ההעלם דוקא (כמשי\"ת) ומזה יהי' סיבת השינוי לפרוץ גדר ההנהגה של אדם בטבע השני שהורגל בו מנעוריו כנ\"ל, והב' במה שעיקר בחי' השמחה הוא רק ענין ובחי' רוממות עצמות הנפש למעלה מעלה מגדר כלי הגבלתה (כמשי\"ת) ומזה יבא סיבת שינוי הטבע גם בעצם מן הקצה לקצה מהיפוך להיפוך (באותה שעה עכ\"פ (כמשי\"ת). וכל זה הוא דוקא בשמחה שתשמח הנפש בעצמה דוקא דהיינו רק מצד עצם נקודת מהותה למעלה מן הרצון ושכל ומדו' (שזהו בחי' יחידה דוקא) שנק' שמחת הנפש בעצמה לבד כו' וד\"ל.\n<b>ולהבין</b> זה דרך פרט, הנה מעלה הראשונה בשמחה שמגלה את ההעלם שבנפש הנה אנו רואים זה בכל אדם שכאשר ישמח האדם בנפשו ביותר או בעת שמחת לבו בחתונת בנו וכמו ביין המשמח וכה\"ג אזי יגלה כל מצפוניו הצפוני' בלבו ונפשו, הן בעצם גופו ומהותו שאע\"פ שבטבעו הוא איש בושת ודק הטבע וגיא גדול ורב וחשוב בעיניו למאד יזלזל א\"ע להראות בגילוי לכל עיני אדם יהי' מי שיהי' גם פחותי הערך לרקוד בריקוד ותנועות שונות כמו בסיפוק ידים ולפזז ולכרכר בכל עוז בכל מיני גילוי תנועו' שונות כהגלו' נגלות אחד הריקי', שזהו רק מצד עוצם השמח' פורץ גדרו הטבעי שהוטבע והורגל בו מכבר להיו' בדקדוק ומתון כל תנועה והילוך כו' ולא יוכל להתאפק מלעשו' הריקוד והסיפוק בידי' והנעת ראש ולפזז כו', שזהו רק מפני שנפשו",[["158","158","<b>הנה כל זה הנה</b>: כן הוא בגוכי\"ק."],["159","159","<b>והנה תחלה ילה\"ק בשרש ענין השמחה</b>: ראה בסה\"מ תרנ\"ז ע' רכג ואילך, התוכן מכאן בתוס' ביאורים."]]],[1900420042,"יצאה מהעלמה לגילוי, כי טבע השמח' להביא את הנפש מן ההעלם לגילוי שגילוי זה פורץ גדר הקדום, וכמו בדוד מלך ישראל שהי' בהתנשאו' גדולה ומרוב שמחה בארון האלקי' יצא מגדר הטבע של המלכי' הגדולים וביזה א\"ע להגלות לכל אדם לפזז ולכרכר בכל עוז כו', וכמו שא' לו מיכל מה נכבד כו' בהגלו' נגלו' מ\"י כו' וא' לה ונקלותי עוד מזאת<sup data-n=\"160\">160</sup> והייתי שפל בעיני ושחקתי לפני ה', כי מרוב שמח' הנפש כו' בעצמה דוקא יצא' מן ההעלם לגילוי להיו' בבחי' שפלו' וענוה גדולה היפוך טבע הרוממו' דמלכי' ולעשו' שחוק וריקוד בפיזוז וכרכור כו' (וכמו שהיו שמחי' בשמח' בית השואבה וכן מרקדי' לפני הכלה גדולי הדור<sup data-n=\"161\">161</sup>), והרי אנו רואי' שהשמח' מביאה מן ההעלם לגילוי מרוממו' לשפלות ולעשות כשגעון בהוללו' ושחוק וקלו' ראש כאחד הריקי' שאין פרצה גדולה מזו בגדר הקדום (וכמו ר\"ב דסמיך גאולה לתפלה ולא פסיק חוכא<sup data-n=\"162\">162</sup> מפומי' בשחוק ממש רק שזהו הכל מצד שמח' ש\"מ האלקי' ביחוד זה דגאולה לתפלה, וכמו מצו' שמחת חו\"כ שעושין כל מיני שחוק לשמח החו\"כ שזהו דרשב\"י מרקד אתלת<sup data-n=\"163\">163</sup> וכה\"ג שהכל הוא בשמח' הנפש עצמה שעושה גילוי ההעלם לפרוץ גדר הנהגה הקדומה כנ\"ל). וכמ\"כ אנו רואי' גם במלכי' הגדולי' ברוממו' עצמותם שכאשר ישמח המלך בשמחת הנפש לפרקים כמו בעת משתה ושמחה שעושה לכל העם בעת קבלת כתר מלכותו או בשמחת חתונתו וחתונת בנו או שבא לו איזה בשורה טובה מכיבוש מלחמה וכה\"ג שתגדל השמחה בנפשו ביותר אז יצא המלך מגדרו הטבעי הקדום והוא במה שיוצא מהעלמו לגילוי לכל אדם, דהיינו היפוך טבעו הרגיל לפי רוממות גדולת מלכותו שהוסד מכבר שיושב המלך בהיכלו סגור באין יוצא ובא ע\"י שומרי הסף רק ע\"י קריאה שיקראוהו בדבר המלך ובלתי קריאה לא יוכל איש לבא בהיכלו כי כולו אומר כבוד וזהו כבודו דוקא, ואפי' שרי המלך הפרתמים לא יוכלו לראות פניו כ\"א לפרקי' רחוקי' בקריאה דוקא, אך בעת וזמן השמחה שישמח המלך במשתה וסעודה מאיזה דבר הנוגע לעצמו' נפשו ממש אזי יפרוץ גדרו הטבעי' הנהוג והוסד מכבר בהנהגה תמידית לפי רוממו' כבודו וגדלו ויוצא לחוץ מהיכלו בעצמו להתגלות בשער המלך לעין כל ויושב בשער המלך ומראה פנים צהובו' מאד וענוה יתירה עם כל אדם לדבר עם הכל ולכבד גם פחות ערך שלא הי' בערך שיוכלו לגשת אליו, ואם תגדל השמחה יותר יתראה גם ברחוב העיר ויצוה לשחוק לפניו בכל מיני שחוק והיתול ודברי שיר והוללו' וגם בעצמו ירבה לדבר דברי' כמו הדיוט ממש אע\"פ שלפי כבודו וגדלו של מלך טבעו הרגיל למעט מאד בדברי' וכ\"ש לדבר דברי' בטילי' ועם הפחותי' שבעבדיו, שכל זה מורה רק שענין השמחה הוא המביא מן ההעלם",[["160","160","<b>מה נכבד. . ונקלותי עוד מזאת</b>: ע\"פ שמו\"ב ו, כ ואילך."],["161","161","<b>בשמח' בית השואבה. . לפני הכלה גדולי הדור</b>: סוכה נא, סע\"א ואילך. נג, א. כתובות יז, א."],["162","162","<b>ר\"ב </b>[רב ברונא]<b> דסמיך. . ולא פסיק חוכא</b>: ברכות ט, ב."],["163","163","<b>דרשב\"י </b>[דרב שמואל בר יצחק]<b> מרקד אתלת</b>: כתובות יז, א. וראה לעיל ח\"א ע' רסד."]]],[1900420043,"לגילוי לפרוץ גדר הטבעי' הנהוג מקדם בתמידו' ולשנותו לגמרי מן הקצה לקצה עד שזהו כמו שינו ממהות למהו' אחר כמו מרוממו' המלך לשפלו' כאחד הפחותי' ולגלו' בדיבור כל מצפוניו כו'. וראי' לזה ממה שאנו רואי' גם בכל אדם אע\"פ שהוא חכם גדול ודעתן וחשוב גדול אשר סודותיו הצפוני' בדעתו ולבו לא יוכל לגלות לשום אדם אפי' לאוהבו כנפשו וגם לתלמידו ובנו היקרי', וכ\"ש דבר סתר אשר נוגע לנקוד' נפשו או שכל וחכ' עמוקה ביותר שיקרה בעיניו מכל הון והוא סוד סתום וחתום אצלו כל ימיו כו', אבל בעת שמחת לבו ונפשו ביותר לפי שטבע השמחה להביא כל העלם הנפש לגילוי כנ\"ל אזי כל רצון סתום ונעלם מאד בנפשו מכמה שני' או סוד דבר חכ' סתום ונעלם ביותר וגם דבר שנוגע לעצם הנפש (שהוא דבר מגונה ושפלו' עצמו ממעשיו ומדותיו כו' לבזות עצמו כו') (כמו החוטא שאינו עושה תשוב' שיגלה עונו וכל עומק שלו שלו בעת שמחתו ביין, ולהיפוך הצדיק יגלה כל עומק הטוב שבו כו'), הכל יגלה בדיבור ולא יוכל לה תאפק כלל לעמוד על נפשו, וזהו בחי' התגלו' הפנימי' ועצמיו' שמוסתר ונעלם בעצם נקוד' נפשו (כמו שמגלה בגופו בחיצוניו' בריקוד וכה\"ג כנ\"ל) (ויוכל להיו' להיפוך שברשע יתגלה בחי' ההעלם דטוב הגנוז בנפשו בעת שמחתו וטוב לבו ויהרהר בתשוב' שלימה עד שיבכה בעת שמחתו דוקא, ולהיפוך בצדיק יגלה עומק מעט הרע הגנוז בנפשו ויבא לידי חטא או להרהור חטא, וראי' מן המועדי' ששמחי' ביין שמתעני' בה\"ב, וכמו שמבוא' ברמב\"ם שיש להזהיר במועדי' שלא ינהגו קלו' ראש בנשים ואנשי' יחד, וכמו שעשה איוב לבניו כידוע<sup data-n=\"164\">164</sup>) (וזהו טבע השמחה לגלות ההיפוך מטבעו, כמו אם איש שמחה הוא יבכה בשמחתו ואם רחמני יתאכזר ויכה כל איש בפגעו, ולהיפוך איש אכזר בטבעו ירחם ויהי' רך כקנה וכן בקימוץ ופיזור (כמשי\"ת).\n[יז] <b>והנה</b> עכ\"פ<sup data-n=\"165\">165</sup> מובן מכל זה בטבע מהות השמחה לשנות ולפרוץ גדר הראשון הטבעי אף שהוא רק בהנהגותיו המורגלים מנעורים שנטבע בנפשו כטבע שני כנ\"ל, ושרש הסיבה לזה הוא לפי [ש]מגלה מבחי' ההעלם והצפון כנ\"ל דהיינו כל מה שבבחי' פנימי' ועצמו' הנפש ממש מוסתר ונעלם ממשיך מן ההעלם הזה לגילוי, והוא שממשיך בחי' אור חדש ונפלא בנפשו שלא הי' בא בגילוי מעולם להיותו בבחי' מקיף דחי' יחידה דנפש שנק' צל\"ם ומזל\"א ובחי' השמחה גורם שיבא ההעלם דמקיף הזה לגילוי, והוא אור מופלא וחדש שלמעלה בערך נבדל מאור וחיו' הקדום שבא בגילוי באו\"כ שהוא רק בחי' נר\"נ שבו כו', וע\"כ יכול לפרוץ גדרו הטבעי לשנותו לגמרי, ולא עוד",[["164","164","<b>שמבוא' ברמב\"ם שיש להזהיר במועדי'. . שעשה איוב לבניו כידוע</b>: רמב\"ם הל' יו\"ט פ\"ו, הכ\"א. שו\"ע אדה\"ז הל' פסח ר\"ס תצ\"ב וסו\"ס תקכ\"ט. איוב א, ה."],["165","165","<b>[יז] והנה עכ\"פ</b>: לפיסקא זו — ראה גם ד\"ה שמח תשמח בסה\"מ תרנ\"ז ע' רכה ואילך: וכן אנו רואים כו' סוד סתום וחתום בחכמה עמוקה כו'."]]],[1900420044,"אלא גם סוד סתום בחכמ' עמוקה שלא הי' ביכולתו בכח השכל להשכילו ולהבינו כלל, אבל ע\"י שמחת הנפש כמו כשישמח ביין יוכל לבא לגילוי ביותר מכפי מדתו בחכ' שבנפש, וכענין שא' אגברו חמרי אדרדקי כי היכי דלמרו מלתא וכן א' חמרא וריחא<sup data-n=\"166\">166</sup> פקחי', ואע\"פ שהיין משמח הלב מלמטה למעלה מזה יובן ג\"כ בדרך ק\"ו בשמח' הנפש עצמ' שפותחת כל מקור הנעלם בנפש כנ\"ל. שמכל זה יש הוראה גמורה ששרש השמחה מגיע בעצמו' ופנימי' הנפש ביותר עד שבכחה לגלו' כל העלם דפנימי' ועצמו' הנפש בכל דבר בין בפנימי' בין בחיצוניו' האברי' כנ\"ל הכל יוצא לחוץ בלי ישאר כלום בהעלם אם בדיבור או בתנועו' הגוף וכה\"ג כל מה שיש בסתימו' והעלם בעצמו' הנפש ממש הכל יוצא לחוץ בגילוי (וכמו ר\"ז דהוה בדיחא דעתי' א' דכל חלל\"י דעלמא<sup data-n=\"167\">167</sup> יגלה כו').\n<b>והנה</b> הטעם הב' בענין מהות ועצם השמחה גם בזה הדבר עצמו מה שמגלה כל העלם העצמו' שבנפש הנה זהו מצד בחי' הרוממו' וההתנשאו' של הנפש בעלותה מכל הגבלות גדרי כוחותי' הטבעיי' לבחי' מהו\"ע שלה ממש שזהו בחי' מקיף דיחידה שבה כו', שמטעם זה יש בכח שמחת הנפש מצד עצמה דוקא כנ\"ל להפוך גם מהות ועצם הטבע הראשונה שהוטבע בנפש מתולדתה בבטן, וכמו שאנו רואים בחוש בכל אדם שגם מי שהוא איש אכזרי וקשה הלב מאד וגובה רוח בטבעו מתולדתו, כאשר יהי' בשמחת לבו ונפשו בעת הטוב כמו שהצליח ועלה לגדולה יתירה מאד בהפלגה גדולה או שנתעשר בהון רב כו' או שעושה משתה ושמחה לחתונתו או חתונת בנו וכה\"ג מכל בשורה טובה שנוגעת בנקודת עצם נפשו ממש אזי יהפך לבו ונפשו בטבעו העצמי ממש מן הקצה לקצה, והוא שמאכזריו' שלו וקושי לבבו יהפך לרחמני וטוב ורך הלבב לרחם ולהתחסד גם עם שונאו שרדפו לחייו ממש לרוממו ולהטיב לו מטובו ביין ובשר וכל גדולה וכבוד עד שיאהבנו כנפשו באמת, וזהו לפי שעלה כל כחו' טבעיו' שלו ברוממו' עצם נפשו שמרומם ביותר (בל\"א זיער גיהיבין ביי זיך) וברוממו' והתנשאו' זו יהפך מטבעו מדין לחסד וטוב, כי טבע הרוממו' לקבל הכל בטוב אף לרעים כמו לטובי' (וכמו שא' דוד היום יומת<sup data-n=\"168\">168</sup> איש בישראל אני רך ומשוח מלך כו' אף ששמעי קללו קללה נמרצת וכו'), וכמ\"כ איש כילי שממונו חביב עליו מגופו ומפקיר נפשו על פרוטה אחת בעת שמחת נפשו יפקיר כל רכושו בתום לבב כמי שהוא פזרן בטבעו שיהנו הכל מטובו וישמחו מאד מזה כעל כל הון כידוע, וכה\"ג הוא בכל המדו'",[["166","166","<b>אגברו חמרי אדרדקי. . חמרא וריחא</b>: סנהדרין לח, א. יומא עו, ב. וראה תניא פ\"ז, ובס' ”תניא — מהדו\"ק\" שם ע' נא."],["167","167","<b>ר\"ז </b>[ר' זירא]<b>. . דכל חלל\"י דעלמא</b>: ע\"פ שבת עז, ב: ר' זירא אשכח לרב יהודה כו' דהוה בדיחא דעתי' ואי בעי מיני' כל חללי עלמא הוה אמר לי' (ורש\"י: פירוש דברים הנעשים בכל חלל העולם)."],["168","168","<b>היום יומת</b>: ע\"פ שמואל-ב יט, כג."]]],[1900420045,"הטבעיו' שבו מתולדה בבטן יהפכו בשמחתו מן הקצה לקצה, כמו מחדוה למרירו' ובכי' ומבכי' ומרירו' לשמחה ומרוממו' לשפלו' לבזות א\"ע כאחד השפלי' ומנצחון להכנעה לעשו' כרצון איש ואיש כו'. וכמ\"כ אנו רואים גם במלך שמרומם ומוגבה ביותר ומדותיו הן קשים ותקיפי' ביותר מצד עוצם הרוממו' שלו שנוקם ונוטר לכל מי שפגע ומרד בכבוד מלכותו, הנה בעת שמחתו וטוב לבבו במשתה וסעודה כמו בעת כתר מלכותו וכה\"ג במשתה חתונתו וחתונ' בנו וכה\"ג הנה אז יהופכו מדותיו העצמיי' שלפי ערך רוממו' גדולתו ותקפו מן הקצה לקצה (לבד שינוי ההנהגו' התמידו' מעולם הנ\"ל), והיינו מה שנשתנה מהות טבעו מן הרוממו' לתכלית השפלות לדבר עם כל פחותי הערך ולא יקפיד בכבודו כלל בכל מה שיאמרו לו אף שלנגד כבודו כו', וכמ\"כ יהפך בטבעו מן הדין והרוגז וכעס על אויביו לחסד וטוב, ואף למורד ועושה כל עון וחטא כי יצוה להוציא מבית הכלא אף למורדי' ופושעי' בו ולנשאם ולרוממם ולהושיבם לפניו ולהטיב להם כל טוב, וכן מקמצנות לפזרנו' לפזר כל הון לגמרי כו' כנ\"ל, וכל זה השינוי בעצם הטבע לפי שעה זו עכ\"פ בעת השמחה זהו רק מצד בחי' שמחת הנפש בעצמה שמתרוממת ביותר ומושללת אז מכל גדרי המדו' הטבעיי' ומן הרצון והשכל לגמרי [וע\"כ יכול להפוך אותם מן הקצה לקצה לשנות למהות אחר מן הקצה לקצה]. ונמצא ב' הטעמי' הללו הכל ענין וטעם א' הוא, דמפני שהשמחה היא ברוממות [העצמו' ובפנימי' הנפש יכולה לפרוץ גדר הטבע לגמרי, והוא עצמו הטעם מה] שהשמחה גורם גילוי ההעלם והסוד שבנפש בחיצוניו' [ובפנימי', דהכל טעם א' הוא לפי שהשמחה מגעת בפנימי' ועצמי' הנפש ממש דוקא] כנ\"ל וד\"ל.\n[יח] <b>ואחר</b> כל הנ\"ל יובן הנמשל מכל זה בדרך כלל ובדרך פרט למעלה מעלה גם בעצמות אא\"ס ב\"ה<sup data-n=\"169\">169</sup>, דאע\"פ שהוא בבחי' אחדות פשוטה בתכלית ונק' סדכ\"ס דלמת\"ב כלל אפי' מח' הקדומ' דמל' דא\"ס כו' כנ\"ל, והיינו שא\"א שיומשך מבחי' העלם אמיתת עצמותו כמו שהוא למטה אף להיו' מקור למקור לאבי\"ע כנ\"ל רק ע\"י צמצומי' רבים וגם זה בקו\"ח שנק' קו המדה כידוע, אך ע\"י בחי' השמחה שישמח ה' בעצמו דוקא (כמו שמחת הנפש באדם במוה\"ע דוקא כנ\"ל), וכמו ביום חתונתו<sup data-n=\"170\">170</sup> וביום שמחת לבו שזהו במ\"ת ובבנין בהמ\"ק וכה\"ג בכל מועדי' ורגלי' שנק' מועדים לשמחה כידוע (וכמו ויספו ענוים<sup data-n=\"171\">171</sup> בהוי' שמחה שמעוררי' למעלה שמחה גדולה בשם הוי' (כמשי\"ת) ע\"י שמחה של מצוה ושמחה דתורה ותפלה שהוא ע\"י אתדל\"ת כנ\"ל), וכמבואר למעלה בעת שהמלך בשמחה עושה משתה ושמחה ויתגלה מהעלמו בהיכלו",[["169","169","<b>[יח] ואחר כל הנ\"ל כו' בעצמות אא\"ס ב\"ה</b>: ראה ד\"ה שמח תשמח בסה\"מ תרנ\"ז ע' רכ ואילך. פיסקא זו בתוס' ביאורים."],["170","170","<b>ביום חתונתו</b>: שה\"ש ג, יא."],["171","171","<b>ויספו ענוים</b>: ישעי' כט, יט."]]],[1900420046,"ויצא לחוץ כו' ופורץ גדר הקדום בהנהגה מרוממו' לשפלו' וענוה וכה\"ג לפי שהשמח' מביא כל העלם לגילוי כו', וכך יובן למעלה שע\"י בחי' השמח' עליונה שבמוה\"ע ית' ממש יוצא מבחי' ההעלם אחר העלם שבפנימי' עצמותו שנק' סתימא דכל סתימין לידי גילוי דוקא שלא כפי גדר הקדום שהוא סתום ונעלם בהיכלו כולו אומר כבוד, וכמו שאו שערי' ראשיכם<sup data-n=\"172\">172</sup> ויבא מלך הכבוד כו' שזהו בחי' מל' דא\"ס בבחי' הפנימי' ועצמו' שלו ממש שמרומם לבדו (כמו ברוממו' העצמו' ביחידה שבנפש באדם), וכמו שא' בזוהר דבסוכו' בחמשה עשר יום כו' בי' מלכא בתרעא<sup data-n=\"173\">173</sup> יתיב כו' (שהוא זמן שמחה למעלה. ואע\"פ ששמחה זו רק בבחי' מוחי' דאימא ובחי' מקיפי' דחג הסוכו' ג\"כ במקיפי' דאימא לבד כידוע, עכ\"ז שמחה זו באה מלמעלה משם הוי' דמועדי' והוא בבחי' אתדל\"ע בעצמו' א\"ס ב\"ה ממש רק שנמשך משם הארה משמחה העצמי' גם בבינ\"ה ונקראי' מועדי' להוי' בכלל שאז נתגלה מהעלמו העצמי' מצד בחי' שמחה עצמי' דוקא, ולכך בג' רגלי' א' יראה כל זכורך<sup data-n=\"174\">174</sup> את פני הוי' כו' שכל ישראל יכולי' לראות את פני הוי' בעזרה לפי שמתגלה לכל כקטן כגדול כמבוא' למעלה במלך ששמח ביותר שמתגלה בשער המלך לעין כל ומדבר עם כל אדם כו').\n<b>וענין</b> פרצת הגדר הזה שע\"י השמחה שבמוה\"ע ית' היינו שפורץ גדר של מא' קו המדה שהוא הקו\"ח שנמדד במדה ושיעור אחר הצמצום הראשון הנק' מק\"פ דישת חוש\"ך סתר\"ו<sup data-n=\"175\">175</sup> וכל מה שנגלה מאור א\"ס הכל הוא רק אפס קצהו בגדר ומדה מצומצמת מאד בקו\"ח זה, וגם הקו\"ח הזה נק' קו המדה שמודד שיעור ומדה לכל אור ושפע באבי\"ע במקיף ופנימי ואו\"כ (כמ\"ש במ\"א בענין וי\"ו דוהנורא<sup data-n=\"176\">176</sup>) כפי סדר ההשתלשלו' התמידי' (אף בשבתו' ויו\"ט שבהן גילוי תוס' אורות מקיפי' בחו\"ב שנק' קד\"ש ומקראי קדש כנ\"ל וכן בר\"ה ויו\"כ שמתגלה גם מפנימי' המל' דא\"ס להיו' מקור למלכו' כ\"ע כנ\"ל וביו\"כ נתגלה מבחי' רעוא דכ\"ר בי\"ג מדה\"ר כמ\"ש כי בענן אראה<sup data-n=\"177\">177</sup> כו', הכל הוא בא במדה ושיעור דוקא, והיינו לפי ערך אתדל\"ת בהמתקו' הגבו' בחסדי' כמו בכל יו\"ט בקרבנו' ועולי רגל, וכן בשבת וחדש אע\"פ שא' סגור יהי' כו' ביום השבת וחדש יפת\"ח<sup data-n=\"178\">178</sup> מעצמו שזהו גילוי כבוד אלקי ישראל בבחי' מל' דא\"ס עצמו ממש, וכן בנשמו' בג\"ע עולי' מדי חדש ושבת כו' שזהו יציאתו מהיכלו לחוץ",[["172","172","<b>שאו שערי' ראשיכם</b>: תהלים כד, ז-ט."],["173","173","<b>בזוהר. . מלכא בתרעא</b>: זח\"ג קב, ב."],["174","174","<b>יראה כל זכורך</b>: דברים טז, טז."],["175","175","<b>דישת חושך סתרו</b>: תהלים יח, יב."],["176","176","<b>במ\"א בענין וי\"ו דוהנורא</b>: ראה ס' מאמרי אדה\"ז ענינים ע' נח, ובהמ\"מ שם."],["177","177","<b>כי בענן אראה</b>: אחרי טז, ב."],["178","178","<b>סגור יהי'. . וחדש יפתח</b>: יחזקאל מו, א. וראה שם מד, א-ב."]]],[1900420047,"כמו ה' יוצא ממקומו<sup data-n=\"179\">179</sup> כו', מ\"מ אין כל זה בחי' התגלו' לחוץ ממש רק כמו בשער הפונה קדים לבד שיפתח מהעלמו שהי' סגור כו', וגם כל זה עפ\"י אתדל\"ת, כמו בבהמ\"ק ע\"י קטרת וקרבנו' והדלקו' המנורה כמ\"ש שמן וקטרת ישמח לב<sup data-n=\"180\">180</sup> האדם העליון ששמחה זו עולה מלמטה למעלה, כמו מריח הקטרת שישמח לב וריח הקרבנות שנק' ריח ניחוחי וכן ע\"י יין לנסכי' שמשמח אלקי' כו' וכהעלא' נרו' המנור' בשמן למאו\"ר להאיר כל אור, ואין כל זה גורם רק בחי' שמחה למעלה שיוצא ממקומו הנעלם בשערי' דחו\"ב ובכת\"ר שהוא הרצון ותענוג הנעלם שיבא לגילוי, כמו בר\"ה ויו\"כ מרעוא דכל רעוין ובשבת בעונג העליון בחכ' וביו\"ט בבינה ומדו' דחג\"ת דאצי' כידוע, שכל זה הכל עפ\"י סדר ההשתלשלו' דקו המדה הנ\"ל, רק שבא בתוס' אור מעצמו' המאציל לגילוי בלבד, וגם זה העיקר הוא למעלה כמו שהוא רק שבא בהתלבשו' במעשה המצו' בדברי' גשמיי' כקרבנו' וקטרת והלל ומוסף ביו\"ט וכה\"ג שהוא לפ\"ע הגבלת הכלים לגילוי אור הנעלם הזה בכלל כו', וראי' לזה שהרי לא נתגלה כל סוד ה' הנעלם שבח\"ע העצמי' ולא נגלה כל עצמו' התענוג הפשוט ורצה\"ע הפנימי' כמו שהוא במוה\"ע ית' ממש וגם לא בחי' פנימי' המל' דא\"ס כמו שהוא ברוממו' העצמו' ממש עד ימו' המשיח והעוה\"ב דוקא שאז נא' ולא יכנף עוד מוריך כו' וכתי' הנה אלקינו זה<sup data-n=\"181\">181</sup> ממש כמו שהוא למעלה במוה\"ע והוא לפי שזה יהי' מצד בחי' השמח' העצמי' שמוה\"ע ית' ממש (כמשי\"ת). ועכ\"ז יש גם עכשיו הארה בעלמא מבחי' שמח' עצמי' דלע\"ל גם בכל מועד ורגל וכמ\"כ בשבת (כמו בפסח מצד שנגלה בכבודו לנש\"י ביצי\"מ, ובשבועו' בירידתו על ה\"ס שזהו כמו אירוסי' ונישואי' כמ\"ש ביום חתונת\"ו שבעת חתונתו יתגלה בשמח' עצמי', וראי' לזה ממה שא' וירד ה' על ה\"ס שירד ממקומו שנק' סדכ\"ס לחוץ ממש בהיכלו' דנוג' בע' שרים וא' אנכ\"י<sup data-n=\"182\">182</sup> ממש הוי' אלקיך כו', וכן ביצי\"מ א' ועברת\"י כו', וכן בסוכו' בענני כבו\"ד שנתלבש בהן ממקיפי' עליונים שבעצמותו ממש כמו כנשר יעיר קנו<sup data-n=\"183\">183</sup> על גוזליו כו' וכן ישאהו על אברתו כאם שרובצת על האפרוחי' כו', ואע\"פ שג' אלה הן רק בחכ' ומדו' כמו בחג השבועו' בכת\"ר תור\"ה שירד להשתעשע בחכ' דתורה לנש\"י שנק' בנים ובפסח להגן על בניו בחסדו וכן בסוכו', עכ\"ז ה\"ז נמשך מבחי' פנימי' מוה\"ע ממש ויש בזה ענין יציא' וגילוי לחוץ ממקומו ממש כנ\"ל וד\"ל).\n<b>(ואע\"פ</b> שכל שמחו' הללו שבשבת ומועדי' ור\"ה ויו\"כ וגם מה שהי' במ\"ת ובנין בהמ\"ק וכן ביצ\"מ בפסח מורכב בדבר מה מאיזה סיבה",[["179","179","<b>ה' יוצא ממקומו</b>: ישעי' כו, כא."],["180","180","<b>שמן וקטרת ישמח לב</b>: משלי כז, ט."],["181","181","<b>ולא יכנף עוד מוריך. . הנה אלקינו זה</b>: ישעי' ל, כ. שם כה, ט."],["182","182","<b>ביום חתונתו. . וירד ה' על ה\"ס. . אנכ\"י</b>: שה\"ש ג, יא. יתרו יט, כ. שם כ, ב."],["183","183","<b>ועברתי. . כנשר יעיר קנו</b>: בא יב, יב. האזינו לב, יא."]]],[1900420048,"והתחדשות, כמו בשבת כי בו שבת וביו\"ט בפסח בחסד כו' ובשבועו' בת\"ת דתורה ובעונג שבחו\"ב ורצון כו' וכן בסוכו' במקיפי' דבינה וגם בבנין בהמ\"ק ביחוד דזו\"נ הוי' ואלקי' בהיכל ק\"ק ע\"י הקרבנו' וקטרת כו', ואין כל זה נקרא שמחה פשוטה העצמי' ממש שבלתי מורכב בדבר מה כלל וכלל אלא הוא שמחה המגעת בעצמו' דאא\"ס מצד עצמו ממש (כשמחת הנפש מצד עצמה לבד שבלתי מורכב אף בעונג ורצון וחכ' ומדו' כלל), עכ\"ז הרי מבוא' למעלה במשל השמח' של המלך בעצמו ממש שפורץ גדר לצאת מהיכלו גם במה שמורכב באיזה דבר סיבה כמו בעת חתונתו וחתונת בנו או שכבש מלחמה או שיש עיתי' מיוחדי' בשנה ששמח בשמחה העצמי' רק שמתלבשי' בדבר מה\n[יט] <b>ושרש</b> הענין הוא<sup data-n=\"184\">184</sup> כמבואר למעלה שיש בשמחה ב' דברים, הא' מה שהשמחה מביאה מן ההעלם לגילוי לבד להיותה מגעת בפנימי' ועצמו' ע\"כ יצהבו פניו בשמחה כו', וזהו אינו אלא גורם השינוי בהנהגה הגדור מקדם כטבע השני כנ\"ל, וזהו ג\"כ כל ענין הנ\"ל בשינוי טבע סדר ההשלשלו' בע\"ס או\"כ מקיף ופנימי' בקו המדה דקו\"ח שבסיבת השמח' עליונ' באתדל\"ע בעת רצון מיוחד כמו במועדי' להוי' ובשבת שיוצא מבחי' ההעלם דחכ' ועונג העליון לגילוי ביתר מכפי המדה דקו\"ח מסדכ\"ס כו' כמו וקראת לשבת עונג העליון וכה\"ג בר\"ה ממל' דא\"ס מהתנשאו' שמצד עצמו שנק' מלך הקדוש וביו\"כ מעצמו' התענוג הפשוט שנק' רעוא דכ\"ר כו', והכל בא בגילוי בהארת פנים העליוני' שזהו כמו בחי' הארת תרין תפוחין<sup data-n=\"185\">185</sup> בתיקון ואמ\"ת דאנפהא דמלכא נהירי' וכל דינין מתעברי' כו' אז נמתקו כל הדינין ביותר מכפי קו המדה אף במשפט החכ' דתור' כידוע, וזהו נק' פרצת גדר בטבע הנהוג מכבר, וכמו שבשמח' מגלה כל העלם בפנימי' וחיצוניו' וכמ\"ש מלכא בתרעא יתיב כו', וכל זה אינו רק תוס' גילוי אור מן ההעלם מלמעלה מן ההשתלשלו' דקו\"ח להאיר בהוי' ואלקי' שנק' סובב וממלא כו', ששרש כל זה אינו מגיע רק במל' דא\"ס שלפני צמצום דמק\"פ שיאיר בר\"ה מסדכ\"ס דלמת\"ב להיו' מאיר בקו\"ח עד שמתגלה במצחא דע\"י ביו\"כ כו', והיינו לפי שע\"י השמחה שמגיע בעצמות מביא לידי גילוי מבחי' ההעלם להאיר הארת פני' לעשו' שינוי בגדר הקדום, והוא מה שנק' קדוש הוי' יתגלה מלמעלה למטה בדילוג הערך כמו מדלג על ההרים ומקפץ כו' ולשנו' מאור החסד בכלי הגבו' וממקיף פנימי וכה\"ג (כמו בענני כבוד). אבל מדרג' הב' בשמחה זהו שהיא מצד עצם עוצם הרוממו' שמתנשא בנפשו כמו שהוא למעלה מנר\"נ כו' אלא כמו שהוא במקיף דעצמות",[["184","184","<b>[יט] ושרש הענין הוא כו' בשמחה ב' דברים כו'</b>: להבא להלן, ראה גם ד\"ה שמח תשמח בסה\"מ תרנ\"ז ע' רלב ואילך."],["185","185","<b>הארת תרין תפוחין. . דאנפהא. . וכל דינין מתעברין</b>: ראה ע\"ח שער א\"א (שי\"ג) פ\"ט. זח\"ג קלג, ב [וצויין ע\"ז יותר במ\"מ לעיל ח\"א ע' קצז]."]]],[1900420049,"דיחיד' כו' שלמעלה מנר\"נ דאד\"ם שבזה ישתנה ויתבטלו כל כוחו' דנר\"נ בכלים להתהפך מן הקצה גם בטבע ראשון כנ\"ל.\n<b>והדוגמא</b> מזו יובן למעלה בבחי' השמח' העצמי' דמקיף העצמי' דאור א\"ס שהוא בגילוי פנימי' ועצמו' דמל' דא\"ס כמו שהוא בעצם פנימי' הרוממו' דעצמו' שלמעלה גם ממקיף דרצון ותענוג וחכ' כו' שאז יהי' שינוי גם בעצם המדו' דא\"ס מדין לחסד וטוב מן הקצה כו', והיינו לפי שיתגלה מעצם הרוממו' שלו למטה מטה כמו שהוא למעלה מעלה ממש בשוה ולא בדרך גילוי ההעלם לבד הנ\"ל, ואז מה שהי' נק' סדכ\"ס דלמת\"ב אפי' מח' דמל' דא\"ס העצמי' ומח' שלמעלה ממנה כנ\"ל לפי שאין ערוך כלל אל עצמותו ממש, אך ע\"י שמחה העצמי' הזאת הנה יוצא ממקומו מעצם הרוממו' ממש להיו' למטה ממש ולא יהי' הפרש כלל בין מעלה ומטה, ומה שלא הי' שום א' בעולם תפיס' בי' יהי' הכל בא בגילוי לכל, וכ\"ש בחי' רצון ועונג וחכ' הנעלמי' שלא יהיו בבחי' העלם ולא יהיו נק' סוד ה' מאחר שהוא עצמו ית' יתגלה עד שישונה גם בכל הטבעי' דאדם במדו' דרצון העצמי' כנ\"ל וד\"ל.\n<b>ונמצא</b> דשרש השמחה הוא רק במה שהיא בפנימי' ועצמו' דא\"ס ב\"ה ממש ומזה יבא ענין גילוי ההעלם שלו אף ברצון וחכ' ומדו' בע\"ס דאצי' במקיף ופנימי כמו שבת ויו\"ט ור\"ה ויו\"כ, רק שיש בזה שני אופני', הא' מה ששמח' זו העצמי' באה למטה בהשתלשלו' דסובב וממלא בהוי' ואלקי' דחו\"ב ומדו' להיו' גם בהם השמח' לגילוי ההעלם בכת\"ר ובחכ' ובינה מעילה לעילה כו', וע\"י העלא' מ\"ן מלמטה כמו במצות השייכי' לג' רגלי' ולשבת וכה\"ג בכל מצוה שעושה יח\"ע דקודב\"ה ושכינתי' שיש בזה שמחה למעלה כו', ובכלל העולה על הכל הי' בחי' השמח' שמצד עצמו בלי אתדל\"ת כלל ביצ\"מ ובמ\"ת וגם בבנין בהמ\"ק כנ\"ל וד\"ל. והאופן הב' זהו מה שיהי' בבנין בהמ\"ק דמשיח שיתגלה מהעלמו דבחי' סדכ\"ס עצמו למטה כמו למעלה ממש, וזהו באור א\"ס שבח\"ע העצמי' ופנימי' כמו שהי' במ\"ת בי' הדברו' בנגלה בפב\"פ כו', והעיקר בעוה\"ב בגילוי מוה\"ע ית' מעצמו' התענוג הפשוט שנק' שעשועי המלך בעצמו ממש למטה כמו למעלה ממש בלי אמצעי כלל, והוא שלא ע\"י בחי' ההשתלשלו' דסובב וממלא כלל (כמשי\"ת).\n[כ] <b>ובכל</b> הנ\"ל יובן בדרך כלל מה שא' שמח תשמח ריעים האהובים, פי' שע\"י בחי' שמחה העצמי' שישמח ה' בעצמו מצד בחי' שעשועי' העצמיי' שבעצמו' אא\"ס ב\"ה ממש שאין אתדל\"ת בכלל מגיע לשם אפי' בשמחה ש\"מ ותור' הקדומ' משום דלמת\"ב כלל אפי' מח' דמל' דא\"ס עצמו כנ\"ל, ומשמחה זאת העצמי' שמח תשמח גם לריעים האהובים שהן בחי' משפיע ומקבל שבא בסדר ההשתלשלות מבחי' הקו\"ח בבחי' סובב וממלא בכלל כנ\"ל שנק' בשם חתן וכלה, והיינו כדי שיוכלו להתייחד ב' שמו' דהוי'"],[1900420050,"ואלקי' ביח\"ע שנקרא' ריע\"י' האהוב\"י' כאהבת המשפיע למקבל והמקבל למשפיע כנ\"ל שע\"י בחי' שמחה דוקא יתחברו יחד, והוא בבחי' מקיף דחופה כמו שא' דאין שמחה אלא בחופה דוקא, וכמ\"ש כי על כל כבו\"ד חופ\"ה ב' מיני כבוד כבוד העליון דמשפיע שנק' חת\"ן וכבוד התחתון שנק' כל\"ה, וכמ\"ש והוא כחתן יוצא מחופת\"ו דקאי במ\"ת שא' ביום חתונת\"ו וכן כחת\"ן יכהן פא\"ר בעטר\"ה שעטר\"ה<sup data-n=\"186\">186</sup> לו אמ\"ו וכו', ושמחה זו שעל בחי' החתן בחופת\"ו נמשך מבחי' שמחה שלמעלה בעצמו' א\"ס ב\"ה. וזהו שמח תשמח שמח לדכורא בחי' סובב כו' שיהי' לו רצון להשפיע כו', והיינו כאשר אין אתדל\"ת כלל לעורר אתדל\"ע במשפיע ומקבל שהוא הוי' ואלקי' להיו' בבחי' סובב וממלא כמו להיו' רצון במל' דא\"ס להיו' מאיר בקו\"ח בכלל כו' כנ\"ל, אזי מתעורר באתדל\"ע מצד עצמו בעצמו' אא\"ס שלמעלה גם ממל' דא\"ס ע\"י בחי' השמחה הזאת שהיא בבחי' מוה\"ע ממש ביתר שאת ויתר עז להאיר מאור העצמו' ממש למטה גם בהשתלשלו' דסובב וממלא בגילוי מן ההעלם דעצמו' הרבה יותר מכפי המדה דקו המדה שבקו\"ח ע\"פ גדר הקדום כנ\"ל, מטעם הנ\"ל שהשמחה בעצמו' פורץ גדר ומביא כל סתום והעלם לגילוי אף בעונג ורצה\"ע הקדומה להאיר למטה עד ע\"ס דאצי' הכלולי' בשם הוי' שנק' סובב כ\"ע לגבי בי\"ע שכלולי' במל' דאצי' הנק' ממלא, וכמו בשבתו' ויו\"ט שנק' מועדי' לשמחה ועונג בחו\"ב ומדו' ביתר מכפי המדה הראשונה כנ\"ל, וכענין ג' רגלי' שירא' כל זכורך כנ\"ל, שזהו ענין תשמח לנוק' (שזהו זמן שמחתינ\"ו וישמחו בך כו' ממש), דכמו שמביא כל העלם דעונג ורצה\"ע וחכ' במדו' דז\"א ע\"י שמחה העצמי' שמאיר גם למטה לשמח לדכורא (כמשי\"ת בסמוך), כך משמחה זו עצמה נמשך גם לבחי' המקבל שהוא שנק' שכינה גם בשרש נש\"י למטה שיוכלו ע\"י שמחה זו לעלו' וליראו' בעזרה לקבל פני הוי' בשמחה כו', וכה\"ג בכל שמחה של מצוה כמו העלאו' דמצות כקרבנו' וקטר\"ת וכל העלא' מ\"ן במ\"ע ול\"ת כו' ותפילי' שיהי' יח\"ע דהוי' ואלקי' הרי עוזר ומושיע למקבל בשמח' זו כדי שתחפוץ להתייחד ולהיו' אל אישה תשוקת', וכמו שאו' משמח חתן וכלה כמו שמצוה לשמח לכלה כמו לחתן כענין כיצד מרקדי'<sup data-n=\"187\">187</sup> לפני הכל\"ה כו' (אך כל זה בשמחה העצמי' שישמח גם לחו\"כ שנק' ריעי' האהובי' כמו במ\"ת ובהמ\"ק, אבל לע\"ל יהי' גילוי אור העצמו' דא\"ס ב\"ה ממש למטה כמו שהוא למעלה ממש בשוה ע\"י שמחה דעצמו' שמגלה עצם הרוממו' כנ\"ל אזי לא יהי' [ע\"י שמחה לשמח ריעים] האהובי' כמו חו\"כ משפיע ומקבל כלל, וכמו ועמדו רגליו ביום ההוא על הר הזיתי' כו' (כמ\"ש במ\"א<sup data-n=\"188\">188</sup>).",[["186","186","<b>דאין שמחה אלא בחופה. . כי על כבוד. . והוא כחתן. . כחתן יכהן. . בעטרה שעטרה</b>: סוכה כה, ב. ישעי' ד, ה. תהלים יט, ו. ישעי' סא, י. שה\"ש ג, יא."],["187","187","<b>כיצד מרקדין</b>: כתובות יז, א."],["188","188","<b>ועמדו רגליו. . (כמ\"ש במ\"א)</b>: זכרי' יד, ד. וראה להלן ד\"ה להבין שבברכה ראשונה אות ל\"ג."]]],[1900420051,"<b>וזהו</b> שא' עוד כשמחך יצירך בג\"ע מקדם כו', פי' בא במא' זה לחזק דבריו הראשוני' שא' שמח תשמח שמדבר באתדל\"ע שמצד עצמו בבחי' שמחה העצמי' דוקא שישמח גם לריעי' האהובי' ע\"י שמח' זו כדי שירצו להתייחד כו' כנ\"ל, ואע\"פ שאין אתדל\"ת כלל לעורר שמחה בהוי' ואלקי' שנק' ריעי' האהובי' (כמו בשמחה ש\"מ ובהעלא' מ\"ן דתפלה וק\"ש ואהבה ויראה ומס\"נ כו') (וכידוע דא\"א להשפעת משפיע בלא שמחה שהיא מביא' ההעלם לגילוי וירידת העצמו' שלא כפי גדרו הקדום וכן במקבל א\"א לעלו' ולחפוץ ביחוד כ\"א בשמח' שזהו ענין מצות שמחת חו\"כ), אבל או' לראי' ולדוגמא ששמחה כזאת מעצמו ומאליו דוקא שלא ע\"י אתדל\"ת כבר הי' לעולמי' כן שגם שמחה זו היתה בשביל לשמח למשפיע ומקבל כמו שעכשיו נק' ריעי' האהובי' חו\"כ כנ\"ל, והוא מ\"ש כשמחך יצירך בג\"ע כו' שזהו יצירת אדה\"ר בג\"ע בחומר וצורה (כמשי\"ת) שהי' משמח לאדה\"ר וחוה אשתו (כמשי\"ת), שבודאי שמחה זו היתה מצד עצמו שלא ע\"י אתדל\"ת כלל רק מעצמו כדי לשמח אדם ואשתו (שזהו כמו שמצוה לשמח חו\"כ שזהו דוקא בגדולי הדור כידוע), ואמנם שמחה זו הוא שעושי' בנפשו רק כדי לשמח חו\"כ לבד כו' ואין זו כמו שמחה העצמי' ממש שמצד עצמו ממש כמו שיהי' לע\"ל דכתי' שם נשמחה בו<sup data-n=\"189\">189</sup> כו', ואמנם לפי ששמחה זו לשמח חו\"כ גדולה וכוללת כל שמח' ש\"מ בכללו' דציור אד\"ם אדמ\"ה לעליון ממש כמשי\"ת ע\"כ ודאי הרי היא שמחה זו מצד עצמותו ממש שמזה דוקא שמח תשמח גם ריעי' האהובי' כשמח\"ך יצירך כו' ג\"כ משמח' דעצמו' ממש (וזהו שמח תשמ\"ח ל' עתיד לע\"ל דוקא). וזהו המשך הדברי' שמח תשמח גם עכשיו לריעי' האהובי' כמו אותה השמחה שכבר הי' כשמחך יצירך כו' שהוא לאחר שנוצר אדה\"ר בג\"ע, ופי' מקד\"ם מקדמונו של עולם<sup data-n=\"190\">190</sup> דוקא (כמשי\"ת).\n[כא] <b>ובאמת</b> יש להבין בזה מה זה שתולה שמחה זאת ששמח תשמח לריעי' האהובי' שהיא כשמח' ששמחך יצירך בג\"ע מקדם דוקא דמה שייך ענין אדה\"ר לענין לריעי' האהובי' הנ\"ל. אך הנה ידוע שעיקר תכלית המכוון שהי' בבריא' והשתלשלו' העולמו' בכלל גם בראשית הצמצום דעצמו' אא\"ס בקו\"ח להיו' בבחי' סובב וממלא כנ\"ל לא הי' רק בשביל בריאת האדם לבד, וכמ\"ש בבריא' אדם כל הנק' בשמי<sup data-n=\"191\">191</sup> דוקא ולכבוד\"י בראתיו יצרתיו כו', פי' ולכבוד\"י ממש כמ\"ש בזוהר בגין דישתמודע\"י' לי' דהיינו שע\"י האדם דוקא שנברא ונוצר בצלם האלקי' וע\"י תו\"מ שיעשה האדם בראתי\"ו יצרתי\"ו כו' (בג' מדרגו' דנר\"נ בי\"ע, ובחי' אדם דעשי' ברמ\"ח מ\"ע עולה על הכל, וז\"ש אף עשיתיו לרבותא משום דנתב\"ס דוקא לפי שנתאוה ה' להיות לו ממש דירה",[["189","189","<b>שם נשמחה בו</b>: תהלים סו, ו."],["190","190","<b>מקדמונו של עולם</b>: ראה ב\"ר פל\"ח, ז. וראה לעיל ח\"א ע' צז וע' רלב. וש\"נ. ולהלן קרוב לסוף המאמר."],["191","191","<b>כל הנק' בשמי</b>: ישעי' מג, ז."]]],[1900420052,"בתחתוני'<sup data-n=\"192\">192</sup> כו'). ואע\"פ שהשתלשלו' העולמו' מבחי' הקו\"ח באבי\"ע גם בהם נמשך שם הוי' ואלקי' והיינו ע\"י בחי' הרצון וחו\"ב ומדו' שנמשך מעצמו' א\"ס ב\"ה בקו\"ח עד ע\"ס דאצי' הכלולי' בשם הוי' שנק' סובב כו', אבל מ\"ש באדם לכבוד\"י בראתיו זהו כבודי דמל' דא\"ס בבחי' הפנימי' ועצמיו' דא\"ס ב\"ה ממש כמא' ישראל עלו במח' שמח' זו למעלה גם ממח' ורצון להאציל כו' (וגם למעלה ממל' דא\"ס העצמי' הנ\"ל ולמעלה גם ממח' דח\"ע דתוה\"ק שהיתה שעשועי' אצלו כו', וראי' לזה ממה שא' במדרש דז' דברי' קדמו לעולם<sup data-n=\"193\">193</sup> תורה ותשובה ובנין בהמ\"ק ושמו של משיח כו' ומחשבתן של ישראל קדמ' לכולן כו' וכמו שא' במי נמלך בנש\"צ כנ\"ל, לפי שגם אור הח\"ע בפנימי' דתוה\"ק נשלמה ע\"י ישראל למטה דוקא כמ\"ש אז ראה ויספרה כו' עד ויא' לאדם דעשי' דוקא הן ירא' ה' היא חכמה של מעלה וסומ\"ר בינה ש\"מ כו'), ואפי' חכמ' דמע\"ב שנמשך מח\"ע דתוה\"ק כמ\"ש בראשית בחוכ' כו' ג\"כ ע\"י ישראל שנק' ראשית כמ\"ש תנאי הי' כו' שיקיימו התו\"מ כי על ידם דוקא יהי' אתדל\"ע בפנימי' ועצמו' דא\"ס בתו\"מ ויהי' יח\"ע דהוי' ואלקי' בבחי' המשכה הפנימי' דא\"ס בקו\"ח באבי\"ע כו' להיו' סובב וממלא ברצון וחכ' ומדו' בבחי' חיצוניו', וכמ\"ש אם לא בריתי<sup data-n=\"194\">194</sup> כו' וכן ואשים דברי בפי\"ך דוקא לנטוע שמי\"ם כו' שאין העולם מתקיים כו', וכמו ביח\"ע דהוי' אחד בק\"ש ע\"י מס\"נ דישראל דוקא שממליכי' אותו בשמי' וארץ שהן בחי' סובב וממלא, וכמ\"ש אתה הראית<sup data-n=\"195\">195</sup> לדעת כי הוי' כו' את\"ה דוקא מיחד יחוד פנימי דהוי' ואלק\"י' בתו\"מ כנ\"ל וד\"ל.\n<b>ושרש</b> הענין הוא לפי שהאדם נברא ונוצר בחומר וצורה בצלם דאד\"ם העליון ושרשו בבחי' הפנימי' ועצמו' דא\"ס ב\"ה ממש וכמ\"ש ויפח באפיו נ\"ח דמאן דנפח<sup data-n=\"196\">196</sup> מתוכ\"י' כו' והוא נשמת' דפרחא<sup data-n=\"197\">197</sup> מחי העולמים עצמו שהיתה כלולה במוה\"ע ית' ממש (ככח המוליד שבנפש האדם שמוליד בדמותו כצלמו ממש בחי' נפש שלימה בשכל ומדו' כמוהו ממש וכך נש\"צ שעלו במח' כנשמ' אדה\"ר כו', ומטעם זה מח' דנש\"צ קדמ' לכולן אף לתוה\"ק וד\"ל). וזהו ויצר הוי' אלקי'<sup data-n=\"198\">198</sup> שזהו בחי' פנימי' דהוי' ואלקי' כמו שהוא בשרש דצלם האד\"ם העליון דנק' אד\"ם אדמ\"ה לעליו\"ן ממש, ולכך נברא אדה\"ר בסוף הכל דוקא",[["192","192","<b>שנתאוה. . דירה בתחתונים</b>: תנחומא נשא טז. ועוד."],["193","193","<b>דז' דברי' קדמו לעולם</b>: ראה ב\"ר פ\"א, ד. מדרש תהלים (באבער) צ, יב. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ב ע' שע."],["194","194","<b>אם לא בריתי. . ואשים דברי. . שאין העולם</b>: ירמי' לג, כה. ישעי' נא, טז. שבת קיט, ב: אין העולם מתקיים אלא בשביל הבל תינוקות כו'."],["195","195","<b>אתה הראית</b>: ואתחנן ד, לה."],["196","196","<b>ויפח באפיו. . דמאן דנפח</b>: בראשית ב, ז. זוהר — מובא בתניא רפ\"ב ובאגה\"ק סט\"ו. [ובסה\"מ ”אתהלך לאזניא\" ע' קה: שאמחז\"ל ע\"פ ויפח באפיו כו']. וראה בהנסמן בלקוטי הגהות לתניא ע' ט."],["197","197","<b>נשמת' דפרחא</b>: ראה זח\"ב קלח, א."],["198","198","<b>ויצר ה' אלקי'</b>: בראשית ב, ז."]]],[1900420053,"לפי שבו דוקא נשלם הכל, כי כל מה שנברא בוי\"מ בצומח וחי וגם למעלה כמלאכי' דמרכב' כמו פני ארי' ושור כו' וגם כל מה שנמשך מסובב כ\"ע דשם הוי' דאצי' בי\"מ מבחי' הרצון וחכ' הקדומ' (ששיער בעצמו בכח במח' הכללי' כנ\"ל) הכל הי' רק בשביל האד\"ם שנברא ביום הוי\"ו שהוא סוף הכל והוא שלימו' שמשלים לכל ההשתלשלו' לפי שבשבילו הי' עיקר המכוון כמ\"ש בו לכבוד\"י ממש בגין דישתמודע\"י' לי' ע\"י נש\"צ בתו\"מ למוה\"ע ית' ממש כנ\"ל וד\"ל.\n[כב] <b>והנה</b> מטעם זה שמח הקדב\"ה בעצמו ביצירת אדה\"ר בשמחה יתירה בבחי' העצמו' ממש יותר משמחה ועונג שהי' לו בכל מע\"ב אע\"פ שא' וירא אלקי' את כל אשר עשה והנה טוב מאד<sup data-n=\"199\">199</sup>, אבל ביצירה דאדם לפי שזה הי' עיקר המכוון בכל מע\"ב מתחלת הרצון והמח' (כענין במי נמלך כו' כנ\"ל) הי' לו שמחה עצמי' ביותר להיותו בצלם אלקי' ממש ועל ידיו יושלם הכל כמ\"ש אשר ברא אלקי' לעשו' לתקן ע\"י האדם (כמ\"ש אחור וקדם צרתני אחור למע\"ב<sup data-n=\"200\">200</sup> וקדם למע\"ב מטעם הנ\"ל). וזהו שא' כשמח\"ך יצירך בג\"ע דהיינו בבחי' השמחה העצמי' שהי' להקדב\"ה ביציר' האדם בג\"ע, שאדה\"ר הי' יציר כפיו ממש בצור' וחומר כמ\"ש ותשת עלי כפכה וכמא' שעה ראשונה צבר עפרו ועשאו גולם כמ\"ש גלמ\"י ראו<sup data-n=\"201\">201</sup> כו' וכתי' ויצר ה' אלקי' כו' עפר כו', שזהו יחוד והתכללו' דנשמה בגוף דוקא כמ\"ש יצרתיו אף עשיתיו, והי' עדיין בחי' הנוקב' כלול בדכר באחת מצלעותיו עד שלקח הצלע ובנה בנין הנוק' בפרצוף בפ\"ע כמ\"ש ויבן ה' אלקי' את הצלע כו' ויביאה<sup data-n=\"202\">202</sup> אל האדם כו' ואז נשלם יותר פנימי' הרצון והעונג שביציר' אד\"ם במה שהתקין לו ממנו בנין הנוק' שבלעדה אין שלימו' לאדם, והיינו ביחוד משפיע ומקבל להוליד תולדו' נשמו' ולעשו' יח\"ע באצי' כו' שאינו אלא ביחוד מ\"ה וב\"ן דכר ונוק' כא', שזהו שנק' למעלה ריעי' האהוב\"י' דהוי' ואלקי' כנ\"ל, וכנ\"ל דזהו ענין שמח תשמח שמח לדכורא תשמח לנוק', ולאחר שא' והתקין לו ממנו בנין עדי עד ושוש תשיש כו' שזהו שלימו' התולד\"ה דמשי\"ח בקיבוץ גליו' ע\"כ שמח תשמח ריעי' האהובי' (שהן חו\"ב), וכמו אם הבנים שמחה<sup data-n=\"203\">203</sup> כו' שהוא שלימו' דאדה\"ר ביצירתו (כידוע בענין אדם אד\"ם דוד משיח<sup data-n=\"204\">204</sup>). ונמצא דשמחה זו הי' בשלימו' הבריא' דאדם ואשתו, ולא",[["199","199","<b>וירא. . והנה טוב מאד</b>: בראשית א, לא."],["200","200","<b>אחור וקדם. . אחור למע\"ב</b>: תהלים קלט, ה. ב\"ר רפ\"ח. [וראה בהנסמן עוד בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'שסד]."],["201","201","<b>ותשת עלי כפכה. . שעה ראשונה. . גלמי ראו</b>: תהלים קלט, ה. טז. ראה סנהדרין לח, ב."],["202","202","<b>ויבן ה' אלקים. . ויביאה</b>: בראשית ב, כב."],["203","203","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["204","204","<b>כידוע בענין אדם דוד משיח</b>: ראה ס' הגלגולים ספ\"א. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קצז, ובהמ\"מ שם."]]],[1900420054,"בשעת יצירה לבד הי' שמחה זו אלא בשעה ששימח לאדה\"ר בחופתו דוקא, וכידוע שהקדב\"ה נעשה שושבין לאדה\"ר ואשתו ועשה להם חופה אחת על שניהם שהוא המשכת או\"מ על החו\"כ שמכח מקיף זה הוא שיצליחו ביחודם אח\"כ להוליד נשמו' כו', וזהו כשמחך יצירך בג\"ע בשמחה שבחופה שעשה להם (ומ\"ש כשמחך ל' יחיד ולא נז' שמח' לנוק' שהיא חוה, לפי ששמח' כלה נכלל בשמח' חתן כמ\"ש משמח חו\"כ כו' (כמשי\"ת).\n<b>והנה</b> ודאי ששמח' הזאת ששמח לאדה\"ר בחופתו הי' מצד עצמו שלא ע\"י אתדל\"ת כלל רק מצד עצמו דוקא, והוא מבחי' השמח' שבעצמו שהוא מה שהי' עיקר המכוון בתחלת הרצון להשתלשלו' דהוי' ואלקי' במע\"ב שנק' סובב וממלא כי הי' רק בשביל האד\"ם מטעם הנ\"ל, ועיקר שלימו' דאדם הוא ביחוד בחופה שע\"י יהי' כל יח\"ע בפנימי' האור דא\"ס שיהי' לו קשר וחיבור באבי\"ע ע\"י האדם דוקא, ע\"כ משמחה זו שמח לאדה\"ר שיוכל להיו' כח ביחודו להוליד נשמו' ולעשו' יח\"ע, והיינו בשמחתו העצמי' ששמח בו ביותר הוא שנמשך שמחה לאדה\"ר, כענין משמח חתן שצ\"ל בעצמו בשמח' וא\"ל לא יוכל לשמח לחתן ושמח', ושמח' עצמו גדולה כ\"כ עד שמשמחה זו יכול לשמח גם חו\"כ. וזהו שמסיים כשמחך יצירך דקאי על דבריו הראשוני' שא' שמח תשמח בשמחה העצמי' גם הריעי' האהובי' בפרט בכל יחוד עליון כמו ששמחך יצירך בכללות בשמח' דעצמו' דוקא וד\"ל.\n[כג] <b>ומעתה</b> יש להבין מה שא' כשמחך יצירך בג\"ע מקד\"ם דוקא. כי הנה פי' מקד\"ם זה היינו מבחי' קדמונו של עולם שנק' קדמון לכל הקדומי' והוא שנק' תחלת כל התחלו', דכמו שנק' אין סוף להתפשטו' בעולמות כך הוא למעלה בעצמו נק' קדמון לכל קדם, כי הרי מבוא' למעלה דכל מח' ורצון הקדום אפי' מל' דא\"ס זהו בכלל מקור ותחלה לסוף להיו' מל' כ\"ע, אבל עצמו' א\"ס ממש נק' קדמון הוא מקדם לכל בחי' מקור לשפע דהשתלשלו' אלא כמו שהוא יחיד לבדו ממש דלמת\"ב כלל כנ\"ל, ונק' יחיד חי העולמי' כו' שלמעלה ממל' דא\"ס בקו\"ח, ואז לא הי' ענין העלא' מלמט' לעורר הרצון ותענוג אף במל' דא\"ס עצמו (רק בחי' העונג ושעשועי המלך בעצמו ממש כנ\"ל ובמי נמלך בנשמתן של צדיקים שהיו כלולי' בו ממש כנ\"ל שהוא האדם שנפח באפיו נ\"ח), עד שנברא האדם ויניחהו בג\"ע לעבדה שאז הי' העלא' מ\"ן מאדה\"ר במ\"ע ברוחניו' שנק' אתדל\"ת לעורר אתדל\"ע משא\"כ קודם לכן (הגם שהי' נש\"צ במח' העצמי' הרי היו כלולי' בתכלית). ולזאת ודאי שמחה זו ששמח לאדה\"ר בחופתו כנ\"ל זה הי' משמחה שמצד עצמו ממש (אע\"פ שזה הי' מצד ששמח ביציר\"ה דאדה\"ר ביותר כנ\"ל, גם זה אינו רק לפי שהוא בצלמו כדמותו בבחי' פנימי' ועצמיו' ממש וכאב שמשמח לבנו שנמשך משמחת הנפש מצד עצמו ממש) מאחר שהי' משמח לאדה\"ר שבודאי הי' זה משמח' עצמותו ממש שאין כל העלא' מ\"ן מלמטה בשמח' מגיע לשם כלל לפי שאין"],[1900420055,"ערך לשמח' שישמח ה' במעשיו או גם בהעלא' דקטרת ושמן שישמח לב ואפי' לא שמח' שבח\"ע כו' כנ\"ל (רק שמחה ש\"מ בלבד (כמשי\"ת) שזהו מצד בחי' ההשתלשלו' כנ\"ל, דמקור הראשון לכל ההשתלשלו' דקו\"ח זהו רק מל' דא\"ס שגם מח' זו אין ערוך לו כלל כמ\"ש לך ה' הממלכ\"ה<sup data-n=\"205\">205</sup> כו' (אבל בשמח' חופה דאדה\"ר זהו בשעשועי המלך בעצמו ממש שהיא בבחי' עצמו' א\"ס ממש כמו שהוא מטעם הנ\"ל).\n<b>וזהו</b> שאנו מבקשי' שמח תשמח ריעי' האהובי' דעכשיו הגם שריעי' האהובי' הללו באי' בבחי' ההשתלשלו' דסובב וממלא כו' שיהי' שמחה זו כשמחה ששמחך יצירך בג\"ע מקד\"ם דוקא דהיינו מקדמונו ש\"ע כנ\"ל. והענין הוא כידוע דעכשיו אע\"פ שיש יח\"ע למעלה באצי' כמו ביחוד דזו\"נ ואו\"א שנק' ריעי' האהובי' בכלל, ה\"ז תלוי לפי ערך אופן אתדל\"ת במעשה התחתוני' דוקא שכמים הפא\"פ כו' מעוררי' שמחה בשם הוי' ואלקי' שיתייחדו, כמו ויספו ענוי' בהוי' שמחה<sup data-n=\"206\">206</sup> והוא מה שישמח הוי' במעשיו כנ\"ל, וכמו ע\"י הקרבנו' בבהמ\"ק הי' יח\"ע להמתיק הגבו' בחסדי' העליוני', אבל הי' זה רק במדה ושיעור עפ\"י מא' קו המדה שמודד כל העלא' מ\"ן והמשכו' מ\"ד כו' כמה יהי' גילוי ההעלם בתוס' אורו' ומוחי' חדשי' (וגם הי' יניקה מיח\"ע הזה אף לנוג\"ה דבי\"ע בחיצוניו' ותמצית כמו העשן דמערכה<sup data-n=\"207\">207</sup> כו', ובזמן הגלו' מקבלי' ע\"ש מהפנימי' ג\"כ בסוד גלו' השכינ', והוא כמו ענין מיעוט הירח בפגימ' הלבנה שנק' מאור הקטן כו', משא\"כ לע\"ל א' והי' אור הלבנה כאור החמה ממש שזהו כמו שהי' שני מאורו' הגדולי' בשוה כמו קודם שמיעט' הירח א\"ע כו', ולמעלה היינו כשזו\"נ שוין בקומתן, והוא כמו ענין אדם וחוה קודם החטא שהיו שניהם ערומי'<sup data-n=\"208\">208</sup> כו' בלי לבוש דנוג\"ה שאין מסתיר על הוי' ואלקי' כלל כו'.\n<b>וזהו</b> ענין שמח תשמח לריעי' האהובי' שמדבר לע\"ל בתשלום הברורי' דרפ\"ח כו' (וכתנות עו\"ר יהי' בא'<sup data-n=\"209\">209</sup>) (שהרי ברכה זו דשמח תשמח הוא אחר קיבוץ גליו' שמשמח ציון בבני' כנ\"ל), וע\"כ מבקשי' שיהי' גם עכשיו עלי' דריעי' האהובי' ביח\"ע ויח\"ת דהוי' ואלקי' כמו שתשמח אותם לע\"ל שיהי' אז כמו שהי' באדם וחוה קודם החטא ששמח לאדה\"ר בחופת\"ו בשמחה העצמי' בג\"ע מקד\"ם דוקא, שזהו בעצמו' א\"ס ממש כנ\"ל שאין אתדל\"ת דהוי' ואלקי' בסובב וממלא אף בתו\"מ ואוי\"ר במס\"נ מגיע לשם כלל וכמ\"ש אם צדק\"ת<sup data-n=\"210\">210</sup> כו',",[["205","205","<b>לך ה' הממלכה</b>: דהי\"א כט, יא."],["206","206","<b>ויספו ענוי' בה' שמחה</b>: ישעי' כט, יט."],["207","207","<b>העשן דמערכה</b>: ראה זח\"ב קמא, א. רמב, ב. ע\"ח שער קליפת נוגה (שמ\"ט) פ\"ג. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'קפח. דברים ח\"א ע' מב. נ\"ך ע' תקיג. ובהמ\"מ שם."],["208","208","<b>והי' אור הלבנה. . שניהם ערומים</b>: ישעי' ל, כו. בראשית ב, כה."],["209","209","<b>וכתנות עור יהי' בא'</b>: ראה לעיל ח\"א ריש ע' סו. וש\"נ."],["210","210","<b>אם צדק\"ת</b>: איוב לה, ז."]]],[1900420056,"כי גם המצו' שהן פנימי' רצה\"ע למעלה בעצמו' א\"ס שא' רחבה מצותך מא\"ד ה\"ז מקור להמשכו' רצונו וחכ' ומדו' בעולמו' עכ\"פ משום דסוף מעש' עבמ\"ת (רק שמח' ש\"מ הוא למעלה גם מן המצו' עצמן (כמשי\"ת), אבל בחי' השמח' ושעשועי' שבעצמותו ממש ה\"ז מבחי' הפנימי' ועצמו' שלו באתדל\"ע העצמי' ממש (וכנ\"ל במדרג' הב' שבשמחה שהוא ברוממו' הנפש בעצמ' ממש) שפורץ גדר גם בטבע העצמי' כנ\"ל ע\"כ בכח שמח' כזו להיו' התגלו' פנימי' ועצמו' דא\"ס למטה ממש כמו למעלה שהוא למעלה מכל עיקר ומקור ההשתלשלו' (למעלה גם מעוה\"ב שהוא בשכר המצו' עכ\"פ כו'). וזהו מקד\"ם לכל ההשתלשלו', וכמו ומקד\"ם אשר לא נעשה שאינו בא בבחי' תחלה וסוף כלל כנ\"ל וד\"ל. וזהו ענין הבקשה הזאת שמח תשמח כו' כשמחך יצירך בג\"ע קודם החטא מקדם דקדמון לכל כו' בשמח\"ה שבעצמותו ממש כנ\"ל, כך תשמח גם עכשיו לריעי' האהובי' דעכשיו שהן נק' חו\"כ למעלה אע\"פ שבאי' בבחי' ההשתלשלו' דסובב וממלא שיהי' כח היחוד שלהם תמיד רק מבחי' השמחה שאתה תשמחם מבחי' שמחה העליונה שבעצמותו ממש שלא ע\"י שמח' שבא מאתדל\"ת כלל אלא תשמח בעצמך לריעי' האהובי' כמו בכל מועד ושבת וכל יום בק\"ש ותפלה כמו ששמחת לאדה\"ר בג\"ע מקד\"ם דוקא, והוא כמו שיהי' לע\"ל שיהי' הוי' אחד ושמו אחד כו', וכמו שהי' באדם וחוה בג\"ע קודם החטא (כנ\"ל שזהו אד\"ם אדמ' לעליון ממש כמו שהוא בעצמו' א\"ס בכח החכ' דמ\"ה העצמי' כך מ\"ה שם בנ\"ו<sup data-n=\"211\">211</sup> בנשמת אדה\"ר דכח המוליד יוליד בדומה לו ממש כנ\"ל וד\"ל).\n[כד] <b>והנה</b><sup data-n=\"212\">212</sup>* עדיין יש להבין בענין שמח תשמח ריעי' האהובים שהוא לשמח אותם בשמחה העליונה דעצמו' א\"ס ב\"ה ממש איך יכול להיות שיומשך ויתקבל אור שמחה העליונה העצמי' דעצמות א\"ס ב\"ה בריעי' האהובי' שהן בבחי' ההשתשלו' אחר הצמצום בקו\"ח כו', שודאי א\"א להיות בהם בחי' השמחה רק כפי ערכם בצמצום דהשתל' בקו המדה כנ\"ל (ובאמת כבר הי' לעולמי' כן והוא במ\"ת שהאיר ה' פניו בשמחה שבעצמותו כמ\"ש ביום חתונתו וביום שמחת לבו וכמו והוא כחתן<sup data-n=\"213\">213</sup> כו' ששמח בעצמו, אף שיריד' זו לצורך השפעה לחוץ שהוא להשפיע אור דתו' לכנ\"י, אבל זהו בבחי' עצמי' ופנימית ובבחי' מקיף דחופה כמו מקדש עמו ישראל בחופה וקידושי', וכמו\"כ מאחר שפב\"פ דיבר ה' כו' הרי קבלו כנ\"י אור שמחה זו בעצמותם עד שעכ\"ד פרחה נשמתן כו', וגם עכשיו יש שמחה כזאת בכל מי שקורא ושונה או עושה מצוה, וכמו שאו' וישמחו בך ישראל מקדשי שמך ב\"ך ממש אף שאין ערך כלל",[["211","211","<b>מה שם בנו</b>: משלי ל, ד."],["212","212","<b>[כד] והנה</b>: עד כאן נדפס מגוכי\"ק אדהאמ\"צ, ומכאן ואילך חסר לפנינו. ונדפס ע\"פ כתבי-יד מעתיקים."],["213","213","<b>ביום חתונתו. . והוא כחתן</b>: שה\"ש ג, יא. תהלים יט, ו."]]],[1900420057,"בע\"ג לבלתי בע\"ג כלל). הענין הוא לפי שג' קשר'<sup data-n=\"214\">214</sup> הן בבחי' עצמיו' ופנימיות ישראל ואורייתא וקוב\"ה, שנש\"י מתקשראן באורייתא בעצמי' ואורייתא בקוב\"ה בסדכ\"ס דלית מחשבה תפיסא בי' כלל וכנ\"ל במ\"ש במי נמלך בנש\"צ לכך יוכלו נש\"י ע\"י תו\"מ לשמוח בשמחה העצמי' דא\"ס ממש משום דכולא חד (וכמ\"ש מ\"ה שמ\"ו ומ\"ה שם בנ\"ו דקאי בב' דברים בנש\"י ובתו' אור דהיינו בחי' מ\"ה דח\"ע שנמשך מעצמיו' דח\"ע דא\"ס הכלולה במהו\"ע ית' (שהוא כמו כח של השכל שנק' משכיל ההיולי שמתאחד בעצם הנפש ממש שנק' מפני זה נפש השכלי' דוקא להוליד בדמותו נפש שכלי' ולהשכיל כל חכ', שבודאי מה שיוליד בדומה לו גבוה יותר ממה שישכיל כל שכל ומדות דאדם. וא\"כ שרש נש\"י שבעצמו' כבן במוח האב בבחי' אדם כאור נשמת אדה\"ר שהי' כלולה בעצמותו כנ\"ל זהו מ\"ה שם בנ\"ו שגבוה ממ\"ה דחכ' דתו' אור שיצא מכח עצמות החכ' דא\"ס, ולכך לפעמים ישראל נק' חתן והתו' נק' כלה מאורשה כמ\"ש במ\"א<sup data-n=\"215\">215</sup>.\n<b>אך</b> הנה מבואר למעלה בשרש ענין השמחה שבטבעה לפרוץ גדר להביא מן ההעלם לגילוי ביותר מכפי המדה הגדורה מכבר, וכמו המלך בשמחתו העצמי' יצא חוץ להיכלו ולדבר עם כל אדם כו', ומזה יובן ג\"כ למעלה שמחמת שמח' העצמי' דעצמו' א\"ס ממש דוקא הוא שעושה פרצת הגדר כו', שזהו מה שנתגלה אור שמחה העליונה ונמשך ג\"כ למטה מטה להיות גם בהם בגילוי אור ובתוס' גדול מרובה על העיקר, והוא לפרוץ גדר דקו המדה הקבוע בכל עולם ועולם להאיר בהם יותר מכפי המדה המצומצמת בהן מפני גילוי אור שמח' זו דוקא שבעצמות א\"ס כו' (וכמו שאנו רואי' בשמחת מלך שיתגלה שמחתו העצמי' כו' לעין כל ומחמתו יצא כל איש ממקומו וגדרו גם השרים הגדולים ישמחו בשמחתו ביותר מכפי עצם מדתן עד גם פחותי הערך גם הן ישמחו בשמח' יתירה ביותר מכפי מדתן (וכל זה בשמחה שמצד העצמו', וכן בשמחת חו\"כ שהן בצל\"ם אד\"ם כנ\"ל, וע\"כ לריעי' האהובים דוקא שמח תשמח בשמחה העצמי' (כמשי\"ת), ולפי שזהו מצד שמחה העצמיי' דוקא יתגלה לכולם בשוה מגדול עד קטן (כמו בשירת הים שא' זה אלי לנוכח וכולם שמחו בשמחה אחת ואפי' שפחה ראתה<sup data-n=\"216\">216</sup> כו', וכך יהי' לע\"ל שא' שם נשמחה בו ממש כנ\"ל, וכן במ\"ת עכ\"ד כו' הכל היו שווין בזה מצד גילוי אור העצמו' דא\"ס כמ\"ש וירד ה' על ה\"ס כו', וירידה זו היתה מצד שמחה העצמי' שפורץ גדר כנ\"ל, וכמ\"ש בהגלותך מלכנו על ה\"ס<sup data-n=\"217\">217</sup> כו' (וכמו\"כ בש\"ת שהתו' עצמה שמחה",[["214","214","<b>שג' קשר'</b>: ראה זח\"ג עג, א."],["215","215","<b>ולכך לפעמים ישראל נק' חתן. . והתו' נק' כלה מאורשה כמ\"ש במ\"א</b>: ראה להלן ריש ד\"ה להבין מה שבברכה ראשונה, ובהמ\"מ שם."],["216","216","<b>זה אלי. . ואפי' שפחה ראתה</b>: בשלח טו, ב ומכילתא שם."],["217","217","<b>וירד ה'. . בהגלותך מלכנו על ה\"ס</b>: יתרו יט, כ. נוסח מוסף לר\"ה (בברכת שופרות)."]]],[1900420058,"כו' מוציאי' ס\"ת מהיכל לרקוד לפני', וכן הוא לפני חו\"כ הכל שמחי' בשוה גדולי הדור וע\"ה כו', וכך הי' בארון האלקי' שיצא בחוץ הי' דוד וכ\"י שמחים כאחד, וכך הוא בשמחת כתר מל' בגלוי שהכל שמחין כקטן כגדול מטעם הנ\"ל) וד\"ל.\n[כה] <b>והנה</b> להבין ביאור הדבר, הנה תחילה יש להקדים בענין ההשתל' שהוא בא בדרך ירידה וצמצום גדול מעליון לתחתון מראשית הצמצום בקו\"ח עד סוף עוה\"ז השפל שלנו. דהנה ידוע בפי' ולשון השתלשלות שזהו כמו השלשלת שאחוז טבעת התחתונה בסוף העליונה, והוא מלשון משלשלין פירות<sup data-n=\"218\">218</sup> כו', שכל דבר היורד מגבוה לנמוך נק' שלשול בלה\"ק, וע\"כ נק' החבל שלשלת שבו מורידי' מגבוה לנמוך כו'. וכך הוא בענין השתלשלות העולמות מעליון לתחתון שזהו בבחי' עילה ועלול, שכל עולם העליון משפיע לתחתון הימנו בדילוג וצמצום גדול והוא רק מבחי' האחרונה שבו שהוא בחי' האותיות שבו לבד ומבחי' אחרונה שבעליון הוא שנעשה מקור וראש לתחתון (וכמ\"ש בע\"ח דמבחי' מל' שבעליון<sup data-n=\"219\">219</sup> נעשה כתר לתחתון כו'), ועד\"ז הוא ענין ובחי' ירידת אור האלקי בצמצום אחר צמצום והעלם אחר העלם מעולם העליון הימנו לעולם התחתון ממנו, כמו מן הרצון שהוא למעלה מן השכל לגמרי מתצמצם עצם הרצון שנק' כתר ואינו מאיר רק מבחי' אותיו', כמו מזל ונוצ\"ר שנק' מזל מחכים וכמו הכל תלוי במזל אפי' ס\"ת בהיכל<sup data-n=\"220\">220</sup> כו', וכידוע במ\"ש והחכ' מאין תמצא<sup data-n=\"221\">221</sup> כו', וכן מחכ' לבינה רק מבחי' נה\"י דאב\"א מאיר ומלובש באימא, וכן מבינה למדות שבלב ומן המדות למח' ומן המח' לדיבור ומן הדיבור למעשה עד שהמעשה הוא מיעוט וצמצום האחרון יותר, וכך הי' במע\"ב שבחי' אא\"ס שמתצמצם ברצון זהו מ\"ש בקדמי' ומכתר לחכ' כמ\"ש בחוכ'<sup data-n=\"222\">222</sup> כו' ומחכ' לבינה כמ\"ש בראשית ברא אלקי' ומבינה למדות עד בחי' מחדו\"מ שבי\"מ שבא למעשה בפ\"מ כמ\"ש כי הוא אמר ויהי<sup data-n=\"223\">223</sup> כו'), וכך הוא בדרך כללות כל ההשתל' שצמצום הראשון הי' לצמצם כל העצמות דאא\"ס ולא נשאר רק כנקודה ומנקודה זו נמשך בקו\"ח, וגם קו\"ח זה מתצמצם בכלל ובפרט ממקור הרצון והתענוג וחכ' ומדות דבחי' א\"ק עד גילוי דע\"ס דאצי', ובע\"ס דאצי' מתצמצם",[["218","218","<b>משלשלין פירות</b>: ע\"פ ביצה לו, א. וראה גם ס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תרלה. ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' לד. קס [ובהמ\"מ שם]. ח\"ג ע' א'קנח. דברים ח\"א ע' קכז."],["219","219","<b>בע\"ח דמבחי' מל' שבעליון</b>: שער כסא הכבוד (שמ\"ו) פ\"ב ופ\"ה. וראה ס' מאמרי אדהאמ\"צ בראשית ע' לז. במדבר ח\"א ע' לד. דברים ח\"ג ע' תשפ."],["220","220","<b>הכל תלוי במזל אפי' ס\"ת בהיכל</b>: זח\"א קלד, א. וראה לעיל ח\"א ע' לג. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קלח. דברים ח\"א ע' רכט. ח\"ב ע' שעז. ובהמ\"מ שם."],["221","221","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["222","222","<b>בקדמי'. . בחוכ'</b>: ת\"א ות\"י לבראשית א, א."],["223","223","<b>כי הוא אמר ויהי</b>: תהלים לג, ט."]]],[1900420059,"מכתר לחכ' ומחכ' לבינה עד מל' דאצי' בבריאה, ומל' דבריאה נעשה כתר ליצי' ומל' דיצי' נעשה כתר לעשי' עד בחי' מל' דמל' דעשי' בגלגלים וד\"י גשמיים דעוה\"ז כו'), והיינו כאשר צריך להיות התהוות שפע מעליון לתחתון מעילה לעלול הוצרך להיות בחי' צמצום והעלם בעליון (כמו הרצון שמתצמצם בשביל להיות שכל וטעם לרצון וכן משכל למדות ומן המדות למו\"ד במעשה), וכ\"א מתצמצם בשביל שלמטה הימנו, והן ריבוי הצמצומים מאצי' לבריאה ומבריאה ליצי' ועשי' (כמו ג' מיני אותיות דמוד\"מ שכל א' כלול מג', דמח' כלול מדו\"מ, ועשי' שבמח' מקור למח' שבדיבור, וכן עשי' שכלול בדיבור מקור למעשה כמו עקימת שפתיו הוי מעשה<sup data-n=\"224\">224</sup> שבדיבור או שיצוה לעשות נעשה מקור לעשי', עד שבמעשה עצמה נתמעט אור הרצון והחכ' ומדות לגמרי רק שכל ומדות שמצומצמים במו\"ד שבמעשה שנק' עשי' דעשי' כו'), שזהו התהוות עולם השפל דארמ\"ע גשמיי' מרוחניות דמזלות וגלגלים שהוא מט' כלים החיצונים דמל' דמל' דעשי'. וא\"כ אחר ריבוי רבבות מדריגות השתלשלות שישתלשל אור האלקי באבי\"ע מראשית הקו\"ח בריבוי צמצומי' והעלמות בהעלם אחר העלם ומיעוט אחר מיעוט מעולם העליון לעולם התחתון עד שבהגיע הארה והשפע למטה מטה ביותר כמו בהתהוות זה העולם החומרי מאותיות וצמצומים דמל' דמל' דעשי' הרי כבר נתמעט האור אלקי דמל' דא\"ס שבקו\"ח הנ\"ל בתכלית המיעוט והצמצום היותר אחרון, כמובן מכל הנ\"ל דעוה\"ז השפל הוא היותר אחרון בהשתלשלות מעילה לעלול מרוחניות לגשמיות בריבוי צמצומים כ\"כ עד שלא הגיע לעוה\"ז השפל רק צמצום ומיעוט אור ושפע האלקי שמלובש בעשי' דעשי' שהוא היותר אחרון בהשתלשלות מכל העולמות מעט מזעיר מאד, ואף גם זאת בריבוי מסכים ולבושים שמעלים ומפסיק בין כל עולם לעולם כמו המסך שמפסיק בין אצי' לבריאה ומבריאה ליצי' ומיצי' לעשי' שכ\"ז עושה שינוי המהות באור האלקי כמו שינוי מהות השכל במדות והמדות במו\"ד כו' עד המעשה (וכמו ג' מסכים שבאדם מיצר הגרון והקרום שבמוח וחצר הכבד כו'). ואמנם עכ\"ז אני ראשון ואני אחרון וכן ראו כי אני<sup data-n=\"225\">225</sup> אני הוא כו', דאני לשון ידוע במציאות שזהו בחי' מל' דא\"ס שבכתר שנק' אין שנגלה מציאותו עד למטה מטה ממש מאני ראשון דכו\"ח דמל' דא\"ס עד מל' דעשי' בכלל שנק' אני אחרון ממש, לפי שאין כל ריבוי המסכים הנ\"ל וכל ריבוי הצמצומים בהשתל' דעו\"ע מרום המעלות עד עוה\"ז השפל אינו תופס מקום כלל וכמ\"ש אני הוי' לא שניתי<sup data-n=\"226\">226</sup> כלל, וראי' ממה שא' אתה הוא משנברא כו' ואתה הוא כו' כידוע וד\"ל.",[["224","224","<b>עקימת שפתיו הוי מעשה</b>: ב\"מ צ, ב. ועוד."],["225","225","<b>אני ראשון. . ראו כי אני</b>: ישעי' מד, ו. האזינו לב, ט."],["226","226","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."]]],[1900420060,"[כו] <b>והנה</b> לפי כל הנ\"ל יובן ג\"כ שבענין אתדל\"ת בהעלאת מ\"ן גורם אתדל\"ע למעלה בבחי' המשכת מ\"ד כמ\"ש כמים הפנים אל פנים כו' משום דרוח אייתי רוח<sup data-n=\"227\">227</sup> כו', ג\"כ לא יגיע ויומשך מלמעלה למטה בבחי' גילוי אור אלקי רק בבחי' מיעוט וצמצום אור האלקי היותר אחרון שהוא במל' דעשי' באותיות וצירופים היותר אחרוני' דשם אלקי' המהוה לרוחניות דד' יסודות הגשמיי' כנ\"ל, דודאי לפ\"ע ההעלאה מלמט' כך יהי' ערך בחי' ההמשכה העליונה האלקי'<sup data-n=\"228\">228</sup> מלמעלה שתלוי במעשה התחתוני' אם טוב או רע כפי ערך מעשה הטוב בגשמיות כמו במעשה החסד וטוב עם בנ\"א בצדקה וגמ\"ח ובהילוך במעשה המצות בפ\"מ כך יומשך גילוי אור אלקי בחסד גשמי כמו בפרנסה וחיי' גשמיי' וכמ\"ש לך ה' החסד כי אתה תשלם כו' שזהו הולך בהשתל' מרוחניות לגשמיות ממש. וכך בכל העלא' בדברי' גשמיי' שעולה מעוה\"ז הגשמי ומגוף גשמי אף בכל מעשה המצות כציצית ותפילין בצמר וקלף גשמי ות\"ת בדיבור בפה גשמי, שכל התו\"מ הן מלובשים בדברים גשמיי' דדצ\"ח דנוגה דעשי', וגם העלא' דאוי\"ר בשכל והתבוננות האלקי גם הוא עולה מד\"י גשמי' מוטבע בטבע הנפש החיוני בגוף ואין לזה ערך כלל לבחי' ההעלאו' דעולמות הרוחניו' כמלאכי' דמרכב' דפני ארי' ופני שור כו', ואפי' צבא השמי' דעשי' וכש\"כ במלאכים ונשמות דבריאה כמו בגעה\"ע כו' שהעלא' שלהם ודאי גורם המשכה עליונה ביותר כמו מאצי' לבריאה ומע\"ס דבריאה ביצי' וכן לפ\"ע העלאות הרוחניות דרוח אייתי רוח כו', אבל בהעלאו' הגשמיי' דעוה\"ז שהן בבחי' קטנות הערך ביותר ודאי גם מה שראוי להיות עי\"ז המשכות רוחניו' האלקי' באתדל\"ע ע\"י אתדל\"ת זו אינו רק לפ\"ע העלא' זו הגשמיי' ג\"כ ודאי אינו בא ונמשך מלמעלה למטה רק בבחי' צמצום ומיעוט האור בתכלית ההסתר וההעלם, כי מצד ריחוק ערך מדריגת עולם שלנו השפל ביותר בסדר ההשתל' עד שהוא היותר רחוק ומצומצם ביותר שאין אור פני אלקי' חיים מאיר רק ע\"י כמה רבבות צמצומים ומסכים ע\"כ גם הארה זאת דאתדל\"ע האלקי'* במדות וחכ' ורצון וכה\"ג אינו נמשך כ\"א<sup data-n=\"229\">229</sup> ע\"י אתדל\"ת בהעלא' גשמי' רק ע\"י צמצומים והעלמות ולבושים ומסכים רבים מאד כמו שראוי להיות עפ\"י סדר ההשתל' דקו המדה לפי ערך ריחוק שפלות עוה\"ז שנתרחק כ\"כ מאור פני מלך חיים שבא בגילוי למעלה באצי' וכה\"ג (ואעפ\"י שהאור והשפע הזאת הולך ויורד מעילה לעילה מעצמות א\"ס ב\"ה שבקו\"ח המאיר בע\"ס דאצי' ומאצי' לבריאה כו' עד עוה\"ז ממש (כמו גם חסד הגשמי בפרנסה ולרפאות החולי וכה\"ג הולך ויורד מחסד דעצמות א\"ס ב\"ה ברצון",[["227","227","<b>כמים הפנים אל פנים. . דרוח אייתי רוח</b>: ע\"פ משלי כז, יט. ראה זח\"ב קסב, רע\"ב. זח\"א צט, רע\"ב. אוה\"ת חנוכה רפו, א."],["228","228","<b>האלקי'. . רק ע\"י צמצומים</b>: בכת\"י ב: האלקי' ע\"י אתעדל\"ת שלנו בהעלאות גשמיות במדות וחכ' ורצון וכה\"ג אינו נמשך כ\"א רק ע\"י צמצומים."],["229","229","<b>כ\"א</b>: בכת\"י ג: כאן."]]],[1900420061,"הפשוט שלפני האצי' ויורד ומשתלשל בבחי' עו\"ע בריבוי מדריגות מעליון לתחתון כ\"כ עד שנמשך חסד וברכה גשמי' או רפואה גשמי' בעוה\"ז השפל, וכך הוא בכל המשכות דח\"י ברכות דש\"ע כידוע), אבל ע\"י ריבוי השתלשלות בצמצומים רבים הרי בא בירידה ובמיעוט אחר מיעוט כנ\"ל מעולם לעולם שלמטה הימנו עד שבהגיע האור ושפע לעוה\"ז רק במיעוט וצמצום האחרון יותר בתכלית ההסתר והעלם כנ\"ל) (ועכ\"ז הרי אנו מוצאים בכמה ענינים שיוכל להיות גילוי אא\"ס עצמו ממש גם למטה בעוה\"ז השפל כמו בעולם העליון ביותר כעולם האצי' ולמעלה מעלה גם כמו שלפני הקו\"ח כו', וכמו גילוי שכינה בהיכל ק\"ק במקום גשמי וכגילוי הנבואה בנבראים בגוף גשמי בעוה\"ז וכניסים ונפלאות במקום גשמי מלמעלה מכל ההשתל' כידוע, והוא משום דאין כל ההשתל' דסובב וממלא וגם כל האור ושפע בכללות דקו\"ח תופס מקום כלל עד ששוין לפניו מעלה ומטה ממש, וכמ\"ש השמי' ושמי השמי'<sup data-n=\"230\">230</sup> לא יכלכלוהו כו' איזה בית<sup data-n=\"231\">231</sup> כו' ועכ\"ז צמצום שכינתו שהוא גילוי אור עצמותו ממש בהיכל ק\"ק, וכן בגילוי הנבואה מלפני שם הוי' דאצי' גם בגוף גשמי ואין מסתיר לאור זה כלל כי גם חושך לא כו' (וכמ\"ש בשמים ממעל<sup data-n=\"232\">232</sup> ועל הארץ מתחת אין עוד בשניהם בשוה ממש משום דעומק רום ועומק תחת שוין לפניו ממש כמ\"ש המגביהי לשבת המשפילי לראות<sup data-n=\"233\">233</sup> (וראי' לזה ממה שדיבר ה' עם הנחש הקדמוני ועם בלעם וכה\"ג, וגם לנב\"נ וסנחריב נתגלה מאור המל' דא\"ס שמרומם לבדו גם בצמצום האחרון דמל' דעשי' שמלך אלקי' על גוים ונתבטלו ממציאותם כו', וגם הפרות שנשאו הארון<sup data-n=\"234\">234</sup> אלקי' הי' בבחי' ביטול כמו פני שור דמרכבה וכה\"ג. וזהו ראו כי אני אני הוא כו' בלי שינוי והפרש כלל בין מל' דא\"ס שלפני הקו\"ח למל' דעשי' מבלי שימצא ראש וסוף מאחר שעצמותו ית' למעלה מבחי' תחילה וסוף בכלל דאין בחי' תחילה וסוף ומעלה ומטה שייך רק בבחי' ההשתל' והשפעה דוקא שבא ע\"י צמצומים רבים כנ\"ל, וגם אחר ריבוי הצמצומים בבחי' ראש וסוף כנ\"ל אינו תופס מקום כלל, וראי' מן ההשגחה פרטי' גם בארץ מתחת כמו בשמים ממעל בשוה ממש, כמו שהאדם מרגיש א\"ע בידיעה כללי' מראש לסוף כא' ממש בשוה, וכך הוא למעלה בכלל שבידיעת עצמו יודע את כל ההשתל' דקו\"ח מתחילה לסוף כא', וע\"כ גם לאחר ההשתלשלות דע\"ס הוא בחי' אח\"פ כמו לפני ההשתל' ממש. ובזה יתורץ מה שמקשי' הפילוסופי' איך ימצא הריבוי<sup data-n=\"235\">235</sup> מן האח\"פ וכו', וכמ\"ש",[["230","230","<b>השמי' ושמי השמי'</b>: ע\"פ מלכים-א ח, כז."],["231","231","<b>איזה בית</b>: ישעי' סו, א."],["232","232","<b>גם חושך. . בשמים ממעל</b>: תהלים קלט, יב. ואתחנן ד, לט."],["233","233","<b>המגביהי לשבת המשפילי לראות</b>: תהלים קיג, ה-ו."],["234","234","<b>הפרות שנשאו הארון</b>: שמו\"א ו, יב."],["235","235","<b>מה שמקשי' הפילוסופי' איך ימצא הריבוי</b>: ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתקיח. לעיל ח\"א ע' קצב. ובהמ\"מ שם."]]],[1900420062,"במ\"א דמ\"ש הרמב\"ם דבידיעת עצמו<sup data-n=\"236\">236</sup> יודע את הכל בידיעה כללית זהו בחי' סובב הכללי וידיעת עצמו למעלה מזה הרבה, דמ\"ש את השמים כו' אני מלא בשוה זהו בידיעה כללי' וידיעה פרטי' וכמשל שמרגיש בנפשו כל פרט ג\"כ, אבל הרי א' דהוא מקומו<sup data-n=\"237\">237</sup> של עולם ואין העולם מקומו כלל וכן א' דאיהו תפיס בכולהו עלמין ולמחת\"ב כלל וכלל וכנ\"ל גם במחה\"ק כו').\n[כז] <b>ובכל</b> זה יובן ג\"כ בענין העלא' דמעשה המצות בכלל אעפ\"י שמלובשים בדברים גשמיי' דד' יסודות גשמי' דדצ\"ח כו' וכמו בצמר וקלף דטלית ותפילין יוכל להיות שישכון בהן קדושה העליונה העצמי' דעצמות א\"ס ב\"ה בשם הוי' דאצי' ולמעלה מעלה כו', כמו בד\"פ בקלף דתפילין שורה ד' מקיפים דד' מוחין דחו\"ב כו' ואו\"מ דמל'<sup data-n=\"238\">238</sup>* כי שם הוי' נק' עליך אלו תפילין שבראש שהוא שם הוי' ממש, ואין לבוש גשמי זה דקלף דתפילין מסתיר כלל וכלל, וכן בצמר גשמי דטלית על הגוף ממשיך או\"מ הכללי דמל' שמים בחי' מל' דא\"ס ממש כו', וכה\"ג במצות צדקה בכסף גשמי ישכון שם הוי' דחסד דז\"א במל' שנק' צדק ה\"א, וכן בת\"ת בפה שורה מאא\"ס שבח\"ע דתוה\"ק כו', וכן באוי\"ר ומס\"נ בק\"ש מאיר מעצמות א\"ס ב\"ה בו\"ק דאצי' כענין תמליכוהו<sup data-n=\"239\">239</sup> שלמעלה מכל ההשתלשלות דקו\"ח מטעם הנ\"ל, ומה גם כידוע שבמצות הרי שורה מפנימי' ועצמיות דא\"ס ממש וכמו שא' במי נמלך<sup data-n=\"240\">240</sup> כו' דודאי אין כל ההשתל' תופס מקום כלל כו' וד\"ל.\n<b>אך</b> הנה הגם שכפי סדר ההשתל' מעילה לעילה בריבוי הצמצומים כנ\"ל הרי בכל עולם ועולם אינו מאיר רק במדה ושיעור מצומצם מאור האלקי שבתחלת ההמשכה וההשפעה מעצמות אא\"ס בקו\"ח שנק' קו המדה (וראי' לזה שגם במלאכים אם יאיר אור האלקי במעט ביותר מכפי המדה יתבטלו ממציאותם לגמרי, כענין הושיט אצבעו קטנה<sup data-n=\"241\">241</sup> ביניהן ושרפן כו', וכן ביצ\"מ שעשה שפטים באלקי מצרים שנתבטלו ממציאותם לגמרי לפי שהי' התגלות אא\"ס עצמו ביותר מכפי המדה שניתן ליניקת ע' שרים וכמ\"ש וידעו מצרים כי אני הוי'<sup data-n=\"242\">242</sup>, וכמו שיהי' לע\"ל שיגלה כבוד הוי' וראו כ\"ב כנ\"ל), עכ\"ז יוכל להיות הארה יתירה מעצמות אא\"ס בעולמות עד למטה מטה גם בעוה\"ז השפל שהוא צמצום היותר אחרון כנ\"ל, והוא ע\"י שנפרץ גדר המצומצם עפ\"י מאמר קו המדה להיות נמשך שלא ע\"פ סדר ההשתל' הניתן בצמצומים רבים כנ\"ל,",[["236","236","<b>במ\"א דמ\"ש הרמב\"ם דבידיעת עצמו</b>: רמב\"ם הל' יסוה\"ת פ\"ב ה\"י. ראה תו\"ח וירא צז, ב."],["237","237","<b>דהוא מקומו. . דאיהו תפיס. . ולית מח'</b>: ב\"ר פס\"ח, ט. זח\"ג רכה, א. ת\"ז בהקדמה ד\"ה פתח אליהו."],["238","238","<b>ואו\"מ דמל'</b>: בכת\"י ב: וא\"מ דמ\"ש. ובכת\"י ג: וא' דמ\"ש. וניכר שיש כאן טעות מעתיק."],["239","239","<b>תמליכוהו</b>: ברכות יג, ב. או\"ח סי' ס\"א."],["240","240","<b>במי נמלך</b>: ראה ב\"ר פח, ז. רות רבה פ\"ב, ג."],["241","241","<b>הושיט אצבעו קטנה</b>: סנהדרין לח, ב."],["242","242","<b>וידעו מצרים כי אני ה'</b>: וארא ז, ב. בשלח יד, ד. יח."]]],[1900420063,"והיינו ע\"י בחי' שמחה העליונה שבעצמו' א\"ס ב\"ה ממש דוקא שעי\"ז נתגלה מן ההעלם שבעצמות שנק' סתימא דכל סתימין שלא יומשך בבחי' שפע כמו בחי' משפיע ומקבל כמו שהוא עכשיו שצ\"ל בצמצומים רבים כנ\"ל, אלא מאחר שהשמחה העצמי' פורץ גדר אפי' ברוממו' העצמו' (כמו בדוד מלך ישראל שהי' מתגלה בשמחתו בארון כו' כנ\"ל) הרי מאיר מן בחי' האור העצמו' דא\"ס ממש כמו שהוא למעלה מגדר שפע למקבלים ואז יאיר אורו העצמי בשוה גם למטה ממש כמו שהוא למעלה במהו\"ע ית' בלי שום שינוי והפרש כלל וכלל (כמבואר למעלה דבשמחה העצמי' הכל שמחים בשוה כמו בהגלות נגלות שמחת המלך בכבודו ובעצמו ירקדו לפניו כקטן כגדול בשוה כנ\"ל), (וכמו ביצ\"מ שא' ההרים רקדו כאלים כו' לפי שקול דודי מדלג<sup data-n=\"243\">243</sup> על ההרים כו' וכן במ\"ת שירד ה' על ה\"ס כו' שהי' זה מחמת שמחה שבעצמותו ע\"כ נגלה למטה כמו למעלה בבחי' דילוג גדול שלא כפי סדר ההשתל' כנ\"ל). כי הנה האור הנמשך בדרך שפע למקבל כפי ערך המקבל צ\"ל בצמצום בעצמות המשפיע שלא יומשך רק כפי ערך המקבל לבד כדי שיוכל לקבל (וזהו ענין הצמצום הראשון דיו\"ד שנק' רושם שנשאר מהעלם העצמות ואח\"כ בקו\"ח שנק' קו המדה שמודד כל שפע כו'), וכך הוא ענין השתלשלות האור ושפע דא\"ס בקו\"ח בכל עולם מעליון לתחתון הכל מבחי' האחרונה שבעליון לבד כנ\"ל בכ\"א לפי צמצום שלו מעולם לעולם שלמטה הימנו עד צמצום האחרון יותר מכולם שהוא במל' דמל' דעשי' בעוה\"ז השפל כנ\"ל, אבל אור העליון הנפלא ומרומם נבדל בערך לגמרי מכל השפעה והמשכה לעולמות, והוא אור העצמות דא\"ס ממש דלמתב\"כ כנ\"ל רק שמאיר ובא מצד גילוי אור העצמות ממש ע\"י בחי' השמחה שבמהו\"ע ית' שפורץ גדר כנ\"ל, ואינו בא בגדר שפע למקבלים כלל מאחר שנק' סדכ\"ס דלמחת\"ב גם בעולם היותר עליון (אפי' במל' דא\"ס שבקו\"ח כנ\"ל) רק שנגלה אור עצמותו כמו שהוא מצד השמחה בלבד. הרי א\"כ אין הפרש כלל בבחי' גילוי אור זה בין כמו שהוא מאיר למעלה מעלה או למטה מטה ממש בשניהם הארתו בשוה ממש, שגם היותר עליון במדריגה אין לו ערוך כלל וכלל כמו עולם התחתון ממש לפי שנבדל ומרומם לבדו מכל בחי' האור ושפע שבא בהשתל' דקו\"ח א\"כ בחי' מעלה ומטה שבהן שוין לפניו ממש (וכנ\"ל בענין המגביהי לשבת המשפילי כו' דעמ\"ר ועמ\"ת<sup data-n=\"244\">244</sup> שוין כו').\n[כח] <b>וא\"כ</b> הרי יובן ממילא לפי\"ז דגם בענין אתדל\"ת שגורם אתדל\"ע לפ\"ע דוקא כנ\"ל בהפרש שבין העלאת מ\"ן דעוה\"ז השפל להעלאת מ\"ן דמלאכים דבריאה וכה\"ג, אמנם אין זה שייך לומר רק במה שבא לכלל השפעת אור למקבלים כפי ערך המקבל שאז העלא' דמקבל הוא שגורם ירידת",[["243","243","<b>ההרים רקדו. . שקול דודי מדלג</b>: תהלים קיד, ד. שה\"ש ב, ח."],["244","244","<b>דעמ\"ר ועמ\"ת</b>: דעומק רום ועומק תחת. ע\"פ ס' יצירה פ\"א מ\"ה."]]],[1900420064,"השפע דמשפיע לפ\"ע כנ\"ל (והוא ע\"י ביטול היש לאין בכל עולם ועולם לפ\"ע גורם המשכה חדשה מאין ליש כידוע), אבל בעצמות אא\"ס ב\"ה שהוא למעלה מגדר שפע למקבלים כלל כנ\"ל הרי לא שייך לומר שיגיע שם כל אתדל\"ת כלל וכמ\"ש אם צדקת<sup data-n=\"245\">245</sup> כו' דגם רצה\"ע שבמצוות אין מגיע לשם כלל (וכמ\"ש קדושים תהיו ע\"י המצות יכול כמוני כו' קדושתי למעלה מקדושתכם כמ\"ש במ\"א<sup data-n=\"246\">246</sup>). וא\"כ ודאי מובן שאין הפרש כלל בהעלאה וביטול לגבי עצמות אא\"ס ממש שמעלה ומטה שוין ממש כנ\"ל בין אתדל\"ת שבעולם היותר עליון בהשתל' דקו\"ח הנ\"ל ובין אתדל\"ת דעוה\"ז השפל כמו מדברים גשמי' שנעשה בהן המצות כנ\"ל, מאחר שזה האור שנמשך מבחי' מהו\"ע ע\"י השמחה העצמי' כנ\"ל אין אתדל\"ת מגיע לשם כלל להיותו בבחי' העצמו' ממש שלמעלה מבחי' אור הנשפע למקבלים א\"כ העליון והתחתון שוין ממש בענין הביטול וההתכללות (ואפי' מקיף ופנימי דסובב וממלא שניהן שוין ממש דאין מקיף ופנימי שייך רק במה שבא לכלל השפע למקבל שאין ערוך כלל אליו כנ\"ל) (אבל בחי' מקיף דסוכ\"ע שהוא שם הוי' בכלל יגיע שם אתדל\"ת בהעלאה וביטול היש לאין בכל עולם לפ\"ע, וכמו במעשה המצות שמוסיפים או' בשם הוי' דאצי' וכן ע\"י הזדככות החומר בנביאי' וכה\"ג שורה עליהם שם הוי' וכיוצא בזה. ואעפ\"י שמבואר בע\"ח דגם בחי' המקיף הכללי שמקיף לד' עולמות דאבי\"ע הרי מאיר הוא בשוה למעלה ולמטה כי גם הוא למעלה מבחי' מעלה ומטה שבקו\"ח בכלל (וכנ\"ל במ\"ש את השמים כו' אני מלא בשוה דלית אתר פנוי מיני' בשוה וכמ\"ש בשמים ממעל ועל הארץ כו' גם אחר כל הצמצומים מראש לסוף הכל שאינו תופס מקום כלל כו' וז\"ש אני ראשון<sup data-n=\"247\">247</sup> ואני אחרון כו' וד\"ל), הרי ידוע שיש הפרש גדול בזה, דודאי אעפ\"י שנק' מקיף הכללי שסובל כל ההשתל' מראש לסוף כא' ממש בשוה, מ\"מ ה\"ז גם הוא בגדר וסוג דבחי' ההשפע' וההמשכה למקבלים דוקא רק שהוא בא בבחי' אור מקיף וסובב לכולם בשוה, וענין מקיף וסובב זה הרי הוא עיקר ומקור הראשון שכולל כל ההשפעה בכלל שממנו נמצא מציא' האור ושפע שבא אח\"כ בבחי' ממכ\"ע בקו\"ח בכלל (כידוע במ\"ש כי עמך מקור חיים<sup data-n=\"248\">248</sup> כו' שזהו כמו הכלל אל הפרט כמח' הכללי' שצופה כו' כל מה שבא בי\"מ בו' אלפי שנין כו', והוא מקיף הכללי שנק' טה\"ת, (והוא כמו שמרגיש אדם א\"ע בכלל וגם בפרט כנ\"ל, וז\"ש דלית אתר כו', (ולמעלה גם מזה נק' טה\"ע שזהו מה ששיער בעצמו בכח<sup data-n=\"249\">249</sup> כו', וגם זה נק' ידיעא שיודע את הכל, וע\"ז א' דאין העולם מקומו כלל כנ\"ל, והוא לגבי ידיעת",[["245","245","<b>אם צדקת</b>: איוב לה, ז."],["246","246","<b>קדושים תהיו. . למעלה מקדושתכם כמ\"ש במ\"א</b>: קדושים יט, ב. ויק\"ר פכ\"ד, ט. ראה לעיל ח\"א ע' רכא. וש\"נ."],["247","247","<b>את השמים. . בשמים ממעל. . אני ראשון</b>: ירמי' כג, כד. ואתחנן ד, לט. ישעי' מד, ו."],["248","248","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["249","249","<b>מה ששיער בעצמו בכח</b>: ראה לעיל אות י\"א וש\"נ."]]],[1900420065,"עצמו ממש שנתגלה ע\"י השמחה שבעצמות דוקא (כמשי\"ת). והגם שנק' סובב ומקיף הכללי להקיף לכל העולמות בשוה בערך נבדל מהם כמו המתנשא מימו\"ע (וגם מלובש בהעלם בתוך כ\"ע בפרט כנ\"ל), מ\"מ ה\"ז גם הוא בא לפ\"ע המקבלים בבחי' ממלא דוקא שזהו בא בהכרח ע\"י צמצומים במשפיע כנ\"ל, וא\"כ גם בחי' מקיף זה נק' השפעה מאור א\"ס בצמצום והבדלת הערך שאין ערוך לו כלל לגבי מהו\"ע ממש, ולזה הטעם יוכל להגיע לשם אתדל\"ת להוסיף אור הוי' שיבא בגילוי מן ההעלם יותר כנ\"ל, אבל בבחי' האור דא\"ס שמצד עצמו ממש מחמת שמחה שבעצמו' הרי גם בחי' מקיף למקיף לא שייך לומר בו כי הרי הוא למעלה מגדר שפע לעלמין כלל אף לא להיות בבחי' סובב ומקיף למקיף (שנק' שמי השמים שהוא טה\"ע הנ\"ל) מאחר שהוא גילוי אור העצמות ממש שבא רק מצד עצמו שמושלל לגמרי מבחי' השפעה והמשכה ע\"כ הוא למעלה לגמרי מבחי' תחילה וסוף שנק' עומק רום ועומק תחת כנ\"ל, עד שגם זה שמחבר ומקשר מעלה ומטה כא' לא שייך לומר בו, שאין ענין חיבור כולל לראש וסוף שייך רק בבחי' מקיף הכללי הנ\"ל שהוא סובל הכל כא' ונק' מקומו של עולם רק שאין העולם מקומו כו', אבל בבחי' מהו\"ע ית' גם זה לא יתכן לומר כי יחיד לבדו הוא באח\"פ ממש שמושלל מבחי' תחילה וסוף דעמ\"ר ועמ\"ת לגמרי (ומ\"ש כי הוי' הוא האלקי'<sup data-n=\"250\">250</sup> בשמים ממעל כו' זהו שיורד להאיר בסובב וממלא בפנימי' ועצמיות ע\"י המצות דוקא וד\"ל).\n[כט] <b>ואמנם</b> עדיין יש להבין בזה, דהלא מבואר למעלה דגם מצד עצמו' אא\"ס שהוא אח\"פ בתכלית כנ\"ל גם אחר ההשתל' דקו\"ח באבי\"ע כמו קודם ההשתל' בלי שינוי כלל לפי שאין זה תופס מקום כלל, וע\"כ יוכל להיות גילוי אור העצמו' דא\"ס ממש אף בדברים גשמיי' דמעשה המצות כמו קלף וצמר דטו\"ת וכסף דצדק' וכה\"ג, וכן מה שהי' גילוי עצמותו בהיכל ק\"ק ונבואה בנביאים וכן בניסי' וכה\"ג, וא\"כ למה דוקא באמצעות דשמחה העליונה העצמי' הנ\"ל דוקא הוא שפורץ גדר דקו המדה הנ\"ל להאיר בתוס' אור בכל ההשתל' דאבי\"ע, דלפי הנ\"ל גם בלא שמחה זו יוכל להיות כן מטעם הנ\"ל ומה יתרון מעלה יש בשמחה זו דוקא. ועוד דודאי גם בבחי' תוס' אור שע\"י המצות הגם שנק' אתדל\"ת שאינו מגיע למעלה רק במה שנמשך בבחי' השפעה מאא\"ס בבחי' סובב וממלא שזהו הוי' ואלקי' לבד, עכ\"ז הרי אנו אומרי' וישמחו בך ישראל מקדשי שמך ב\"ך ממש, והיינו ע\"י שמחה של מצוה, וכמו גם בשמחה להוי' במועדים דאעפ\"י שאינו אלא בשם הוי' דחו\"ב שבמדות דאצילות כנ\"ל מ\"מ יש בשמחה זו מבחי' שמחה העצמי' ממש כמ\"ש ב\"ך ממש, והוא לפי שקדשנו במצותיו ממש שנק' מצות הוי' למעלה שע\"ז א' רחבה מצותך מאד<sup data-n=\"251\">251</sup> בבחי' א\"ס ממש שיש בזה משמחה שבעצמו' אעפ\"י שאין אתדל\"ת מגיע לשם",[["250","250","<b>כי ה' הוא האלקי'</b>: ואתחנן ד, לט."],["251","251","<b>רחבה מצותך מאד</b>: תהלים קיט, צו."]]],[1900420066,"כלל כנ\"ל להיותו למעלה מבחי' השפעה לגמרי כנ\"ל מ\"מ במצות שורה מקדושת עצמותו ממש אע\"פ שא' יכול כמוני כו' כמו אם צדקת כו', וכמו בתפילין שבראש שא' כי שם הוי' נק' עליך ממש, וכן בטלית ממל' דא\"ס עצמו שא' לבושי' כתלג חיוור<sup data-n=\"252\">252</sup> כו', וכה\"ג ובחסד דצדקה נמשך מחסד דא\"ס עצמו בשם הוי' דחסד דאצי' כו', ובדיבור דד\"ת שלנו מפנימי' דח\"ע הקדומה וכנ\"ל, ואעפ\"י שאין אתדל\"ת מגיע לשם כלל מ\"מ שורה במצות מלמעלה מכללות ההשתל' להאיר בשם הוי' דאצי' בבחי' תוס' אור מן ההעלם לגילוי, וכמ\"ש ויספו ענוים בהוי' שמחה<sup data-n=\"253\">253</sup> משמחה העצמי' דוקא, וכן מ\"ש בע\"ח דכל המצות הוא להוסיף אור באצי'<sup data-n=\"254\">254</sup> הוספה זו בתוס' מרובה על העיקר דקו המדה מעצמות א\"ס ב\"ה ממש שנק' סתימא דכל סתימין דלית מחתב\"כ מן ההעלם לגילוי אור באצי'. ובאמת אין זה מובן כלל, דאם אתדל\"ת גם מן המצות אינו מגיע רק במה שנמשך בבחי' השפעה כמו בגילוי רצה\"ע דמצות אבל במהו\"ע ית' א' אם צדקת כו', וכמו לע\"ל שא' לחפשי חינם בלא מצות<sup data-n=\"255\">255</sup> כו', א\"כ איך ע\"י שמחה של מצוה יומשך גילוי שם הוי' מפנימי' דאור א\"ס עצמו שזהו משמחה העצמי' כמו שאו' וישמחו ב\"ך ממש מקדשי שמך ע\"י המצות שאין ערוך אליו כלל כנ\"ל. אך הענין הוא, דודאי ע\"י המצות גם עכשיו נמשך בחי' תוס' אור מן ההעלם דסדכ\"ס לגילוי לפרוץ גדר דקו המדה הנ\"ל לפי שאור א\"ס הוא אח\"פ למעלה מכל ההשתל' גם עכשיו כמו קודם לכן כנ\"ל, אבל עכ\"ז לא יומשך ע\"י המצוה רק הארה פרטי', כמו בגילוי רצון וחכ' בדבר פרט כמצות תפילין וצדקה אעפ\"י שזהו ג\"כ מבחי' הפנימית דרצון וחכ' וחסד דא\"ס וכה\"ג אין זה רק אתדל\"ת לעורר בעצמות א\"ס, ובאמת הרי אין אתדל\"ת מגיע בעצם הרוממות דא\"ס שלמעלה גם מרצון וחכ' ומדות דא\"ס דלאו מכל אינון מדות כלל אפי' בבחי' ההעלם שהרי לית מח' כו', וגם זאת ההארה דשם הוי' בפרט ע\"י מצות אינו מאיר בגילוי ממש למקבלים רק בהעלם למטה באצי' לבד, אבל ע\"י בחי' השמחה שבעצמו' ממש כנ\"ל שפורץ גדר זהו שמגלה מכל העלם העצמות ממש כמו שהוא למעלה גם מן שרש התו\"מ להיות בגילוי למטה ממש כמו למעלה בשוה כנ\"ל שאין כל אתדל\"ת מעורר זה כי אינו מגיע שם כלל. ואעפ\"י שהוא ית' אח\"פ גם עתה כי אין הריבוי והתחלקות דע\"ס מן הקו\"ח תופס מקום כלל, אבל שיהי' בגילוי גמור זהו ע\"י שמחה העצמי' לפי שפורץ גדר דקו המדה כו' גם במדה דמצות שהוא ברצון וחכ' ומדות שבהעלם עצמותו (וכמבואר למעלה בשרש השמחה במדריגה הב' שהיא בעצם הנפש",[["252","252","<b>לבושי' כתלג חוור</b>: דניאל ז, ט."],["253","253","<b>ויספו ענוים בה' שמחה</b>: ישעי' כט, יט."],["254","254","<b>בע\"ח דכל המצות הוא להוסיף אור באצי'</b>: שער מ\"ן ומ\"ד (של\"ט) דרוש י\"א (כלל ט\"ז). וראה בהנסמן עוד ע\"ז בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתיט וע' תתק-א. במדבר ח\"ב ע' שעג. ח\"ג ע' א'כג. דברים ח\"ד ע' א'תסז. וראה להלן אות ט\"ל."],["255","255","<b>לחפשי חנם בלא מצות</b>: משפטים כא, ב. ראה להלן ד\"ה להבין שבברכה ראשונה, ס\"ז, וש\"נ."]]],[1900420067,"ממש ברוממות שנבדל מהגבלת המדות העצמיו' ג\"כ להפוך אותם כו'). והנה עכ\"ז אעפ\"י שהשמחה העצמי' אין אתדל\"ת אף במצות מגיע לעורר רק מאליו דוקא מטעם הנ\"ל, מ\"מ ע\"י שמחה ש\"מ דוקא אף שהוא בדבר פרט ובא בבחי' השפעה בגילוי רצון כו' מביא ומעורר לשמח' העצמי' שיפרוץ גדר כו' (ואעפ\"י שא' יכול כמוני כו' קדושתי למעלה כו', וא' בזוהר אוריי' קדישא כו' אבל אין קדוש כה' עצמו כו', (ולפי שכל התו\"מ הן ברצון וחכ' ומדות ואא\"ס עצמו למעלה מבחי' אדם אפי' בהעלם דחכ' דא\"ס עצמו כו'), זהו מצד עצם התו\"מ שנק' רצון וחכ' וחסד שהוא בא בבחי' גילוי אור ושפע במציאות דבר מה, אבל בבחי' שמחה ש\"מ דוקא מגיע בעצמו' א\"ס ממש שהוא למעלה מן המצות כמ\"ש וישמחו בך ממש כנ\"ל (וכמשי\"ת).\n[ל] <b>והנה</b> עם כל הנ\"ל יובן יותר ענין שמח תשמח ריעים האהובים, ויתורץ הקושי' דלעיל דאיך יוכלו ריעים האהובים שהן בבחי' ההשתל' דסובב וממלא לקבל מבחי' שמחה העצמי' דא\"ס ממש, דאדרבא הוא עצמו הטעם דמשום דאור א\"ס עצמו הוא למעלה מכל ההשתל' בערך נבדל לגמרי כנ\"ל ואין כל אתדל\"ת מגיע לשם כלל מטעם הנ\"ל רק ע\"י בחי' השמחה שבעצמותו פורץ גדר כנ\"ל ואז ודאי מעלה ומטה שוין ממש אף בענין אתדל\"ת שאין הפרש בין עולם היותר עליון ויותר תחתון להיותו למעלה מבחי' השפעה דסובב ג\"כ כנ\"ל, א\"כ כל יכול הוא שגם בחי' ריעים האהובים שהוא בחי' סובב וממלא בשם הוי' ואלקי' יוכלו לקבל מאור שמחה זו העצמיי' למטה כמו למעלה מאחר שמושלל לגמרי מבחי' מעלה ומטה כנ\"ל (וראי' לזה מכל המצות ומועדים לשמחה וכה\"ג שישמחו ב\"ך ממש), ואעפ\"י שזהו אתדל\"ת בשמחה שלמטה כי מטה ומעלה שוין ולא מצד אתדל\"ת מתעורר בשמחה העצמי' כי גם אתדל\"ת דעולם היותר עליון אין מגיע אליו (דאפי' אור צח<sup data-n=\"256\">256</sup> כו' ולית מח' כו') רק מעצמו ומאליו דוקא שמח תשמח גם לריעים האהובים שלא ע\"י אתדל\"ת אף במצות (כדי שיוכלו להתייחד יחו\"ע דהוי' ואלקי' בשמחה ש\"מ גם בכל פרט ע\"י שמחה עליונה זו שתשמחם בחופ' שהוא הכולל לכל המצות בפרט (כמשי\"ת).\n<b>וזהו</b> שמפרש כשמחך יצירך בג\"ע מקדם מקדמונו ש\"ע דוקא. דהנה בחי' שמחה זו שבעצמות א\"ס ב\"ה ששמח באדה\"ר בחופתו בג\"ע הי' זה בגילוי גמור למטה מטה ביותר שזהו ג\"ע דעשי' שנק' ג\"ע הארץ, ואעפ\"י ששמחה זו היא בבחי' מהו\"ע ית' שנק' קדמונו של עולם קדמון לכל הקדומים דהיינו למעלה גם ממח' ורצון הקדום דתו\"מ הקדומים כו' כנ\"ל, ואמנם האיר משמחה העצמי' שברוממות העצמי' ממש למטה בג\"ע הארץ לשמח לאדה\"ר ואשתו בחופתו כמו שהוא למעלה ממש בלי הפרש כלל, מטעם הנ\"ל דאין",[["256","256","<b>דאפי' אור צח</b>: תקוני זהר תקון ע' (קלה, ב)."]]],[1900420068,"בבחי' גילוי אור דשמחה זו הפרש בין היותר עליון ליותר תחתון מאחר שאין אתדל\"ת מגיע לשם כלל. וזהו שמבקשים שמח תשמח לריעים האהובים גם ביחוד כל פרט בהוי' ואלקי' עתה כשמחך יצירך לאדה\"ר משמחה העצמי' שלא ע\"י אתדל\"ת כלל (כמשי\"ת).\n[לא] <b>והנה</b> הגם שמבואר למעלה שאין כל אתדל\"ת מגיע למעלה לעורר לשמח' העליונה בעצמות אא\"ס כ\"א מאליו ומעצמו דוקא באתדל\"ע מצד עצמו לבד כי אין אתדל\"ת מגיע לשם כלל (אפי' מן המצות כנ\"ל), אך הנה עכ\"ז יש דרך אחרת שיהי' בחי' אתדל\"ע בבחי' שמחה העליונה בעצמו' ממש ע\"י אתדל\"ת דוקא ויהי' באותה המדריגה דשמחה העליונה הנ\"ל שמצד עצמו לבד, ואמנם לא ע\"י העלא' מ\"ן ממעשה המצות מצד עצם המעשה והוא רצה\"ע שמלובש בהן שהרי הוא ית' עצמו למעלה גם מקדושת המצות (כנ\"ל במ\"ש יכול כמוני כו'), אלא רק מצד שמחה ש\"מ דוקא שמגיע למעלה מגוף מעשה המצוה וע\"כ ביכולתם לעורר לשמחה עליונה הנ\"ל שמצד עצמותו לבד הגם שהוא נבדל בערך גם מן המצות כנ\"ל להיות ירידת בחי' אור העצמו' מן ההעלם ממש כמו שהוא למטה כמו למעלה ממש בשוה באור פני מלך חיי' בשמח' רבה ויתירה (כמו בהארת פני הוי' בירידתו על ה\"ס כמו שהוא למעלה ממש בא' אנכי הוי' כו', ואעפ\"י שזה הי' מצד שמחה העצמי' שפורץ גדר כו' וכמ\"ש ביום שמחת לבו, עכ\"ז ה\"ז הי' הסיבה לזה ממה שא' בתחילה כל אשר דיבר ה'<sup data-n=\"257\">257</sup> נעשה כו' באהבה ורצון ושמחה כידוע). והנה להבין זה דלכאו' זהו פלא גדול מאד, דאם מצד עצם המצוה שהוא פנימי' רצה\"ע ממש (שע\"ז א' רחב\"ה מצות\"ך מא\"ד כנ\"ל) לא יוכל לעורר שמחה העליונה שבעצמו' ממש, וע\"י שמח' ש\"מ דוקא יכול לעורר שמחה העליונה, (דהלא ודאי כמו שהמצוה עצמ' שרשה בפרט רצון וחכ' כו' שבא בבחי' השפעה מאח\"פ כו' כך הוא גם השמחה ש\"מ ששמח במעשה שלה שעשה נח\"ר ליוצרו שעשה רצונו כו'), (לפי שבאמת עיקר ענין השמחה העצמי' בעצמו' דא\"ס ממש זהו כמו שמחת הנפש באדם מצד עצמ' שלמעלה מכל שמחה מורכבת ברצון ועונג בדבר מה אף בפנימי' שלו רק שמחה פשוטה לגמרי כנ\"ל).\n[לב] <b>אך</b> הנה תחילה יש להבין בשרש ענין שמחה של מצוה מה היא, להיות שלכאו' לא נזהרנו על מצוה זו להיות מעשה המצוה בשמח' דוקא בתושב\"כ רק בכתובים כמו שא' עבדו את ה' בשמח'<sup data-n=\"258\">258</sup> דוקא כו', כי עיקר האזהר' והציווי בכלל אינו אלא על קיום המצות במעשה בפ\"מ לבד יהי' איך שיהי' ואף בלא כוונה למ\"ד שמצוות א\"צ כוונה כו' (רק מ\"מ הרי ידוע דמי שעושה",[["257","257","<b>אנכי ה'. . ביום שמחת לבו. . כל אשר דיבר ה'</b>: יתרו כ, ב. שה\"ש ג, יא. יתרו יט, ח ומשפטים כד, ז."],["258","258","<b>עבדו את ה' בשמח'</b>: תהלים ק, ב."]]],[1900420069,"המצוה בכוונה ורעותא דליבא שכרו בגעה\"ע ושלא בכוונ' בגעה\"ת כמ\"ש בפע\"ח<sup data-n=\"259\">259</sup>), ויוכל להיות שהמעשה בלא כוונה וטעם רק לצאת י\"ח לבד בקבלת עומ\"ש פשוטה למעלה יותר כמ\"ש סוף דבר כו' דסוף מעשה דוקא הוא שעלה במחשבה תחילה ונעוץ תחילתן<sup data-n=\"260\">260</sup> בסופן דוקא (וכמ\"ש במ\"א שזהו בחי' כתר שם טוב דמשיח שא' הקים על עולה של תו\"מ<sup data-n=\"261\">261</sup> שמגיע למעלה מן החכ' וטעם דמצות שהוא בבחי' כתר שבכתר כו'), וכמו שא' היום לעשותם ולא המדרש עיקר<sup data-n=\"262\">262</sup> אלא המעשה ועל בחי' המעשה דוקא הוסד יסוד כל השכר דעוה\"ב, וגם בעוה\"ז אע\"ג דשכר מצוה בהאי עלמא ליכא<sup data-n=\"263\">263</sup> הרי האדם אוכל פירותיהן בעוה\"ז כו', וכמבואר בתו' כמה פעמים כמפורש ע\"ד הפשוט שהברכה והקללה תלוי' רק במעשה לבד, כמו והי' אם שמוע תשמעו כו' ונתתי מטר כו' אם בחוקותי כו' וכתי' ראה נתתי<sup data-n=\"264\">264</sup> לפניכם היום ברכה וקללה את הברכה אשר תשמעון כו', שנמצא העיקר הוא המעשה דמצות מצד עצם המעשה דוקא אף בלא שמחה, ומה שא' עבדו את ה' בשמחה<sup data-n=\"265\">265</sup> זהו להוסיף אור גדול כשעובד ה' בשמחה אבל מפני מניעת השמחה לא יגרע אור הברכה והשפע אלקי' שהוא תלוי ועומד רק במעשה המצוה מצד עצמן דוקא כנ\"ל וד\"ל.\n<b>אך</b> הנה אנו מוצאים מפורש בתו' שהשמחה שבמעשה המצות הוא עיקר גדול הרבה יותר מגוף המעשה דמצות עד שבמניעת השמחה במצות אעפ\"י שעובד עבודת מעשה המצות בפ\"מ אבד כל הברכה שניתנה לעושי רצונו ית' במצות ונהפך ח\"ו לקללה דוקא, וזהו באמת פלא גדול, והוא מה שמצינו שבקללות חמורות שבפ' תבוא בסיום כל הקללות שנזכר מקודם א' תחת אשר לא עבדת<sup data-n=\"266\">266</sup> את ה' אלקיך בשמחה וטוב לבב מרוב כל ועבדת את אויביך כו' ברעב ובצמא (וקללות האלה שמזכיר עבור מניעת השמחה מטוב לבב לבד הן יותר קשים מכל הקללות שהזכיר קודם על מניעת המעשה דמצות לגמרי, והוא במ\"ש ובאו עליך כל הקללות כו' כי לא שמעת בקול ה' אלקיך לשמור מצותיו כו', וגם יותר מקללות שאו' ע\"ד מיעוט היראה במ\"ש אם לא תשמור לעשות את כל דברי כו' ליראה את ה' כו' והפלא<sup data-n=\"267\">267</sup> ה' כו', וגם שהשמחה עם היראה במעשה המצות מעיקר העבודה, וכמו שא' עבדו את ה' בשמחה וכן",[["259","259","<b>דמי שעושה המצוה. . בגעה\"ע. . בגעה\"ת כמ\"ש בפע\"ח</b>: מובא בכ\"מ — ראה ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתקצ [ובהמ\"מ שם]. עטרת ראש נט, א. וראה זח\"ב רי, א-ב. רכט, ב. אגה\"ק סכ\"ט (קנ, ב)."],["260","260","<b>סוף דבר. . ונעוץ תחילתן</b>: קהלת יב, יג. ס' יצירה פ\"א מ\"ז."],["261","261","<b>הקים על עולה של תו\"מ</b>: שמו\"ב כג, א. ראה במדב\"ר פי\"ח, כא. מדרש שמואל פכ\"ט. תדא\"ר רפ\"ב."],["262","262","<b>היום לעשותם ולא המדרש עיקר</b>: ואתחנן ז, יא. אבות פ\"א מי\"ז."],["263","263","<b>דשכר מצוה בהאי עלמא ליכא</b>: קדושין לט, ב."],["264","264","<b>והי' אם. . ונתתי מטר. . אם בחוקותי. . ראה נתתי</b>: עקב יא, יג. יד. בחוקותי כו, ג. ע\"פ פ' ראה\nיא, כו. כז."],["265","265","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב."],["266","266","<b>תחת אשר לא עבדת</b>: תבוא כח, מז-מח."],["267","267","<b>ובאו עליך. . אם לא תשמע. . והפלא</b>: תבוא שם, כה. נה-נו."]]],[1900420070,"עבדו את ה' בירא' וגם בתו' א' ועתה ישראל<sup data-n=\"268\">268</sup> מה כו' כ\"א ליראה כו', אבל השמחה וטוב לבב לא נזכר בשום מקום רק במ\"ש תחת כו'). והנה משמעות הפשוט במ\"ש תחת אשר לא עבדת כו' היינו הגם שיש בכם עבודה במעשה המצות בשלימות בכשרון בתכלית ככל אשר ציוה ה' לעשותם בכל רמ\"ח מ\"ע בדינן והלכותיהן כמבואר היטיב הדק בתושבע\"פ בלי נטי' ימין ושמאל בכלל המון ישראל וגם רובם ככולם עובדים ה' במצות באוי\"ר ובתמימות בקבלת עומ\"ש פשוטה השייך למעשה עכ\"פ לקיום גזירות המלך ברצון ואעפ\"י שיש ריבוי מאד שעובדים בכוונה ורעותא דליבא הרצויות לה' בעבודה תמה שבלב כידוע, אך עכ\"ז כאשר אינם עובדים במצות בשמחה וטוב לבב דוקא אז לא די שלא יומשך עליהם הברכה כמ\"ש את הברכה אשר תשמעון כו' אלא שיהופך מברכה לקללה והוא במ\"ש תחת אשר כו' ועבדת את אויביך ברעב כו' בקללו' חמורות כ\"כ, שזהו באמת דבר פלא גדול מאד אשר תסמר שערות ראש כל איש אשר עובד ה' בתמימו' בכל ליבו בכונה גדולה שאם אינו עובד ה' בשמחה וטוב לבב דוקא יחולו כל הקללות האלה הנוראות על ראשו תחת אשר הוא ראוי לתכלית הברכות ע\"ד עבודתו התמה כמ\"ש את הברכה אשר תשמעון כו' תשמעון היינו לעשות אותם בכוונה ולא אשר תשמחון במעשה המצות כי אין השמחה עיקר רק העבודה והמעשה לבד כמבואר בכל המקומות בתו', רק זה שא' תחת כו' פלא גדול הוא כנ\"ל.\n[לג] <b>אך</b> הענין הוא דודאי מוכרח לומר מפסוק הנ\"ל דתחת אשר לא כו' שהשמחה בעבודה האלקי' הוא עיקר גדול יותר אף מגוף העבודה והמעשה עד שעבודה בלא שמחה לא ישכון בה הברכ' האלקי' ומלבד העדר הטוב יוכל להתהפך מברכה לקללה וכמ\"ש תחת אשר לא עבדת כו' כנ\"ל. ויובן הטעם בזה עפ\"י כל הנ\"ל בביאור ענין דשמח תשמח כו' שיש ב' מיני בא' ע\"י אתעדל\"ת שמלמטה למעלה כמו בבחי' אתעדל\"ת במעשה המצות באוי\"ר ורעותא דליבא בכשרון המעשה בכי טוב דכ\"ז אינו גורם אתדל\"ע להיות ישמח הוי' במעשיו, רק לפ\"ע ההעל' דאתדל\"ת לבד שהוא כפי צמצום כלי המקבלים ובפרט בעוה\"ז שלנו כו' שהוא צמצום האחרון יותר, ואעפ\"י שגורם אתדל\"ע באהב' וחסד אלקי' אבל הארה זאת באה מלמעלה למטה בצמצומים ולבושים רבים מאא\"ס בע\"ס דאצי' בסובב וממלא רק עפ\"י מאמר דקו המדה לבד כנ\"ל (ואעפ\"י שא' בפע\"ח שהמצות עושים תוס' אורות באצי' שזהו למעלה מכפי המדה הקצובה במא' דקו המדה כנ\"ל, אמנם גם זה עצמו באה במדה ושיעור לפ\"ע ההעלא' שמלמטה למעלה שהן כל חילוקי עניני המצות כידוע), וא\"כ בחי' הארה הזאת שנמשכת באתדל\"ע מלמעלה מועטת היא ביותר מב' טעמים, הא' מצד שאופן המשכה זאת שבאה רק כפי אופן ההעלאה דמקבלים לבד כנ\"ל שאין זה ערך כלל לגבי מהו\"ע דא\"ס ב\"ה כלל",[["268","268","<b>עבדו את ה' ביראה. . ועתה ישראל</b>: תהלים ב, יא. עקב י, יב."]]],[1900420071,"(וכמבואר למעלה דאפי' מח' הקדומה דמל' דא\"ס אינו רק הארה אחת מעצמו' א\"ס ב\"ה ממש והמח' הזאת הוא מקור הראשון לכל ההשתל', וא\"כ גם כל בחי' תוס' אור באצילות מן ההעלם ע\"י המצות אינו רק מבחי' מח' זו דמל' דא\"ס כו'), והטעם הב' מצד בחי' המשכה זאת שגם שבאה ממקור היותר ראשון בהשתל' (שהוא מל' דא\"ס בקו\"ח כנ\"ל) הרי היא מתעלמת ומסתתרת בכמה ריבוי מיני צמצומים מאד עפ\"י סדר של ההשתל' שנמשך ע\"י מאמר קו המדה מעילה לעילה במיעוט אחר מיעוט לפ\"ע מדריג' כל עילה שנבדלת בערך לגבי עלול שמקבל ממנו (וכנ\"ל בירידות הרצון בשכל ושכל במדות כו' עד בחי' המעשה), והיינו שנתמעט האור האלקי בכל עולם ועולם לפי מה שהוא מקבל מעליון הימנו והיינו לפ\"ע מספר ריבוי העולמות דבי\"ע שמשתלשל ויורד במיעוט האור מאחד לזולתו כנ\"ל, עד שבהגיע האור הזה למטה מטה ביותר שהוא עוה\"ז השפל שלנו ואחרון מכולם לא יגיע הארה זו רק בתכלית הצמצום וההסתר במיעוט היותר אחרון כנ\"ל, (והוא ע\"י ריבוי המסכים והעלמות בהתלבשות שונות בכמה צירופים שונים באותיות דשם אלקי' כמו בלבושים דמ\"ח צירופים האחרונים שיש שם יניקה גם לע\"ש דנוגה דעשי' ונק' אדמת בני חם<sup data-n=\"269\">269</sup> כידוע), ואז ודאי יוכל להיות שגם הקליפות דנוגה דעשי' יכולי' גם הם לקבל יניקה בתוס' אור וחיות ביתר מכפי המדה הקצובה להם במאמ' דקו המדה דקץ שם לחושך כו', להיות כי אור זה בא במיעוט וצמצום והסתר גדול ביותר וזהו סיבת ענין יניקות ודיני' קשים שמתאחזים גם ביחוד זה שנמשך מלמעלה (והוא לפי שיש כמה אלקי' אחרים שרוצי' גם הם לקבל יניקה מהקדושה האלקי' שבכל יחודים עליונים כמ\"ש בזוהר בענין הכרוז<sup data-n=\"270\">270</sup>* כו') (וזהו כשעושין המצוה בלא כוונה כלל גם לא לצאת י\"ח רק מצות אנשים מלומדה בלבד, וכש\"כ כשעושה רק להתייהר ולקנות לו שם כו' וכשעוסק בתו\"מ שלא לש\"ש שמוסיפין כח ועוז לק\"נ, וגם זה מצד ריבוי העוונות שגוברים על המצות וכידוע דכל עבירה מכבה מצוה<sup data-n=\"271\">271</sup> כו' ובכיבוי והסתלקות האו' דקדושה מן המצוה אז יהי' תוס' יניקה בק\"נ עד שיהופך מן הברכה לקללה, והוא מצד ריבוי הדינין והקטרוגין שימצאו על בנ\"י מצד קרבתם של הקליפות להקדושה יותר מאחר שניתוסף להם כח ועוז מן הקדושה עליונה עי\"ז שגם לה יש מקום לקבל בקדוש' מחמת חלק הרע המעורב בטוב ביותר, שזהו היפוך עיקר ענין התו\"מ שהוא רק לברר ולהבדיל בין הטו\"ר דוקא, וע\"כ ממילא מסתעף מזה ריבוי הדינין והקטרוגים הקשי' אעפ\"י שהעבודה במצות בפ\"מ הכל בשלימות",[["269","269","<b>דמ\"ח צירופים. . אדמת בני חם</b>: ראה ס' הליקוטים להאריז\"ל ר\"פ בא. פע\"ח שער חהמ\"צ (שכ\"א) פ\"ה. שער הכוונות ענין פסח דרוש א. תו\"א קט, ד. לעיל ח\"א ע' סד."],["270","270","<b>בזוהר בענין הכרוז</b>: בכת\"י א נרשם כאן בשולי הגליון: שמכריזים מאן בעי למחזי ולאסתכלא ביקרא דמלכא. ראה זח\"ב קלד, א: והכי מכריזי דיזדמנון למחמי ביקרא דמלכא כד\"א צאינה וראינה בנות ציון במלך שלמה פוקו למחמי ביקרא דמלכא כו'."],["271","271","<b>עבירה מכבה מצוה</b>: סוטה כא, א."]]],[1900420072,"(וכמו שאנו רואים בחוש בדורות האחרוני' האלה שנראה לעין כל ברוב ההמון ככולם ממש מלאים מצות<sup data-n=\"272\">272</sup> כמעט לא נחסר מצוה א' מכל המצות שמוחזקי' בהם כלל ההמון מגדול עד קטן ממש, ואפי' בנשים וטף באמונה חזקה ביותר ורחוקים מכל רע גמור כע\"ז וג\"ע וש\"ד וחילול שבת וכה\"ג (לבד מלשינות שנחשב כש\"ד ומועטין הן לגבי רוב ההמון, רק עון שנאת חינם מצוי' ברוב המקומות ממש כידוע), ועכ\"ז ריבוי המקטרגי' עליהם למעלה ולמטה בתכלית שנאה כו' ונלחצים ברוב צרות כו', אך כ\"ז מטעם הנ\"ל שהמעשה בדרך טבע שני רגילות ומלומדה (כמ\"ש יען ניגש העם הזה בפיו ושפתיו כבדוני ולבו רחוק כו' ותהי יראתם אותי מצות כו' ואבדה חכמת חכמיו כו' כמ\"ש במ\"א<sup data-n=\"273\">273</sup>), וכש\"כ להתייהר כמו למען שמי יכבד ה'<sup data-n=\"274\">274</sup> עוונות רבים שמכבים המצות, ובהסתלקו' אור הקדושה מן המצות הרי יש יניקה יותר לס\"א כנ\"ל וד\"ל) (וקרוב להאמין מה שנשמע בשם הבעש\"ט ז\"ל שנודע אליו למעלה שמשך זמן רב כמה שנים לא נתקבל למעלה כל המצות<sup data-n=\"275\">275</sup> שעשו בנ\"י למטה ונשאר הכל בעולם הפירוד כו' עד שמאיזה סיבה מהתאמצות צ\"ג ויח\"ס שפעלו בעת רצון למעלה שיקובלו כו', ואין זה פלא כ\"כ כמו עוסק בתו' בלא דו\"ר כלל דלא פרחא לעילא כלל כו' כמ\"ש בזוהר<sup data-n=\"276\">276</sup>). ויהי' איך שיהי' עכ\"פ יכול להיות שעובד הוי' במצות אף בכשרון המעשה אם העבודה בלא שמחה כלל רק בקרירו' ורק לצאת י\"ח (כפי רגילותו לבד כו') מלבד העדר הטוב והברכה שצריך להיו' ע\"י מעשה המצות הנה מסתעף מזה קללות רבות מצד ריבוי המקטרגי' ביותר כנ\"ל. והוא מ\"ש תחת אשר לא עבדת במצות בשמחה כו' ועבדת את אויביך כו' כנ\"ל וד\"ל.",[["272","272","<b>ברוב ההמון ככולם ממש מלאים מצות</b>: ראה גם לעיל ח\"א ע' קפא. ובס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תשעז: ורוב ההמון ככולו לא יצאו מעיקר תומ\"צ כו'. דברים ח\"א ע' נב: רוב ההמון תמימים ושלמים מאד כו'. ובתו\"ח שמות ע' תצז: בעת צרתו כו' מקבל עליו עול תומ\"צ כו' אין איש מישראל שלא יקיים בלב שלם כו' ע\"ש בארוכה. ובדרך חיים יב, א-ב: מעשה המצות בפו\"מ כמעט כולן שוין בכלל ההמון כו'. ובקונטרס פוקח עורים ע' 53."],["273","273","<b>יען ניגש. . חכמת חכמיו כו' כמ\"ש במ\"א</b>: ישעי' כט, יג. יד. וראה ס' מאמרי אדהאמ\"צ בראשית ע' תקנז. שמות ח\"א ע' נג וע' רמט. ח\"ב ע' תסא. ויקרא ח\"א ע' פג. במדבר ח\"ב ע' תקסג. דברים ח\"ב ע' עתר ובהמ\"מ שם."],["274","274","<b>למען שמי יכבד ה'</b>: ישעי' סו, ה."],["275","275","<b>בשם הבעש\"ט ז\"ל שנודע אליו. . לא נתקבל למעלה כל המצות</b>: הובא ג\"כ בד\"ה לה\"ע ההשתטחות [בס' מאמרי אדהאמ\"צ — קונטרסים]. ובס' שבחי הבעש\"ט מביא: ”בעמדי בתפלות נעילה כו' הלכתי מעולם לעולם כו' עד שבאתי אל היכל אחד כו' ובאותו היכל מצאתי תפילות של חמשים שנה שלא היתה להן עלי' ועכשיו מפני שהתפללו בזה יוה\"כ בכונה עלו כל התפילות (ראה ס' שבחי הבעש\"ט — כת\"י (ירושלים תשמ\"ב) ע' 86-84, 255, 270)."],["276","276","<b>עוסק בתו' בלא דו\"ר. . כמ\"ש בזוהר</b>: תקוני זהר תיקון י' (כה, ב). תניא פל\"ט."]]],[1900420073,"[לד] <b>אך</b> הנה ע\"י השמחה אלקי' בעבוד' דמצות ה\"ז היפך כ\"ז, דודאי הגם שאור ושפע אלקי בקדושת המצות הולך כפי סדר ההשתלשלות בריבוי צמצומי' מאד עפ\"י מאמ' קו המדה (ואעפ\"י שמוסיף אור באצי' כנ\"ל), אבל ע\"י השמחה ש\"מ דוקא הרי נמשך ממקור הברכות ממקורא דכולא למעלה מכפי המדה הקצוב' במאמר דקו המדה כנ\"ל. והטעם הוא לפי שע\"י שמחה ש\"מ למטה מעוררים אתדל\"ע בבחי' שמחה עליונה, כי ודאי באתדל\"ת נעשה אדתל\"ע כפי ערך ואופן ההעלאה דרוח אייתי רוח כו' כידוע, ואמנם אעפ\"י שאתדל\"ת בשמחה שלמטה אינו רק כפי ערך המקבלי' שהוא בבחי' קטנות הערך מאד עכ\"ז ודאי עי\"ז מתעורר בחי' שמחה גם בשמחה דשם הוי' דאצי' לפי שע\"י השמח' נפרץ הגדר, ואין ההעלאה דשמחה כמו העלא' דגוף המעשה אעפ\"י שהיא באוי\"ר שאין האהבה עליונה נמשך רק כפי צמצום המקבל לבד כנ\"ל, אבל השמחה הרי היא למעלה מן הגבלת הכלים דנר\"נ כנ\"ל וכך מעורר למעלה ג\"כ בחי' שמחה עליונה שהוא למעלה מהגבלת הכלים למעלה מעלה, והיינו שיוכל להיות אור פני הוי' למטה ע\"י שמחה עליונה שפורץ גדר דקו המדה למעלה כו' וד\"ל. ולא עוד אלא שע\"י שמחה ש\"מ מעורר למעלה בחי' שמח' העליונה שבמהו\"ע א\"ס ב\"ה ממש, לפי שהשמחה ש\"מ ה\"ז מצד שעשה נח\"ר ליוצרו ועשה רצונו מזה הוא שמח שמחה יתירה, א\"כ ודאי עי\"ז מעורר למעלה במהו\"ע ית' שישמח בשמח' ש\"מ זו בבחי' פנימי' רצה\"ע המלובש במצוה זו. ואעפ\"י שאין שמחה זו אשר מלובש ברצה\"ע שבמצוה זו ערך כלל לגבי השמחה העליונה שבעצמו' ממש שאינה רק מצד עצמותו לבד שלמעלה גם מן המצות כנ\"ל, עכ\"ז מתעורר מעצמו בשמחה שבעצמותו שהוא בבחי' א\"ס ממש ע\"י שמח' ש\"מ זו מטעם שטבע השמחה שפורץ גדר כו', עד שיוכל להיות גם בסיבת שמח' ש\"מ בחי' גילוי אור העצמות שמצד שמח' העצמיי' שאינה תלוי' באתדל\"ת כלל להיותו למעלה ממקור ההשתל' דקו\"ח בסובב וממלא כנ\"ל. וע\"כ הרי ממילא מובן שבחי' הארה זאת שנמשכת מעצמות א\"ס ב\"ה בשמחה ש\"מ הרי היא באה בתוס' אור כ\"כ למעלה מגדר דקו המדה לגמרי עד שמאיר למטה כמו למעלה ממש בלי שינוי כלל בין היותר עליון ליותר תחתון כנ\"ל לפי שהארה זו באה מעצמות דא\"ס ממש שלמעלה מבחי' מעלה ומטה לגמרי כנ\"ל, עד שגם נש\"י בגופים יכולים לקבל שמחה עליונה זו שבעצמות ממש שמאיר בשמחה ש\"מ אעפ\"י שאין אתדל\"ת דשמח' ש\"מ מגיע כלל לשמחה שבעצמות ממש כנ\"ל וד\"ל.\n[לה] <b>אך</b> הנה באמת אין כל הנ\"ל מתיישב לנכון דעכ\"ז מדוע לא יומשך הברכה במצות אף שלא ע\"י שמחה, ומה שמבואר הטעם לזה מצד ירידת האור האלקי בצמצומים רבים יכולים גם הקליפות לקבל כנ\"ל, זהו סותר לפשט הכתובים בשכר ועונש שהוא בגשמיות דוקא כמו את הברכה אשר תשמעון כו' והברכה באה ודאי מרוחניות לגשמיות בכמה ריבוי צמצומים ואיך תהי' הברכה בגשמיות דוקא עבור מעשה המצות בגשמיות דוקא כנ\"ל בלי"],[1900420074,"שום מונע מבית ומחוץ ויניח ה' מכל אויב ומקטרג, וזהו עיקר הברכה שישב שלום ובטח כו', וכברכות האבות וא\"י<sup data-n=\"277\">277</sup> כידוע. ועוד אינו מובן בגוף ענין וטעם בשמחה ש\"מ שגורם להמשיך ממקור הברכות למעלה מקו המדה כנ\"ל, דזהו פלא לכאורה, דאם גופה של מעשה המצוה שהוא פנימי' רצה\"ע כו' אין אתדל\"ת מגיע לשם כלל כמ\"ש אם צדקת כו' האיך שמחה ש\"מ תגיע לעורר שמחה שבעצמו' מאחר שהשמחה שלמעלה אינה באה רק מן השמחה שלמטה ושמחה שלמטה אינה רק מצד המצוה ונק' שמח' ש\"מ א\"כ היינו הך ממש (ומה שהשמחה פורץ גדר זהו לא יועיל לענין שמחה העצמי' ממש שאין ערוך אליו כלל וכלל כנ\"ל).\n<b>אך</b> הנה שרש הדברים הוא בטעם הדבר הנ\"ל ששמחה ש\"מ דוקא מגיע בשמחה שבעצמות הנ\"ל, להיות מבואר למעלה בענין המאמר דבמי נמלך בנש\"צ כו' שנמלך בהן על בחי' מח' ורצון הפשוט הזה שבבחי' מל' דא\"ס להיות מל' כ\"ע אם יהי' לו רצון ותענוג בזה אם לאו בנש\"צ, שזהו שא' לכבודי בראתיו<sup data-n=\"278\">278</sup> לכבודי ממש שהוא פנימי' דמל' דא\"ס כנ\"ל, והוא מה שיהי' לו דירה בתחתונים דוקא ע\"י תומ\"צ בפ\"מ ע\"י נש\"צ שהוא למעלה יותר מתענוג ורצה\"פ שבתו\"מ למעלה כי סוף מעשה דוקא עלה במ\"ת כו'. ולפי\"ז הגם שמצד עצם רצונו וחכמתו העליונה שבתו\"מ ש\"מ לא הי' לו רצון ותענוג העצמות ממש במל' דא\"ס להיותו בעצמותו ומהותו נבדל בערך גם מהם כנ\"ל בענין למתב\"כ אפי' מח' דתו' הקדומ' כו', אך בשביל תו\"מ בפ\"מ למטה דוקא בזה נתאוה להיות לו ממש דירה בתחתונים, והוא מה שנמלך בנש\"צ דוקא, (והוא מב' טעמים כא', א' מה שנש\"צ עלו במח' העצמי' ופנימי' כמ\"ש מ\"ה שמ\"ו ומ\"ה שם בנ\"ו<sup data-n=\"279\">279</sup>, והעיקר טעם הב' מה שנש\"צ ירדו למטה דוקא בקיום תו\"מ בפ\"מ כמ\"ש לעשות חסד ומשפט וצדקה בארץ דוקא כי באלה חפצתי<sup data-n=\"280\">280</sup> בפנימי' המח' כנ\"ל). והנה מובן מזה עכ\"פ שכאשר נמשך רצון ומח' במח' זו דמל' דא\"ס ע\"י נש\"צ כנ\"ל זהו שנמשך מבחי' עצמות התענוג ורצון הפשוט הכללי ההיולי שבעצמות א\"ס ממש שנק' בחי' שעשועי המלך בעצמו ממש שבלתי מורכב בדבר מה כלל אפי' לא ברצון ומח' דתו\"מ ש\"מ כנ\"ל (בשביל שיהי' לו דירה בתחתונים כו', וכמ\"ש כל הנק' בשמי ולכבודי ממש כו' כנ\"ל). והיינו ענין ובחי' השמחה העליונה שבעצמותו שהשמח' ושעשועי' ענין א' הוא כמ\"ש",[["277","277","<b>וא\"י</b>: אולי הפי': וארץ ישראל."],["278","278","<b>לכבודי בראתיו</b>: ישעי' מג, ז."],["279","279","<b>מה שמו ומה שם בנו</b>: משלי ל, ד."],["280","280","<b>לעשות חסד ומשפט. . באלה חפצתי</b>: ע\"פ ירמי' ט, כג. [שם: ”כי אני ה' עושה חסד ומשפט וצדקה בארץ כי באלה חפצתי נאום ה'\". אבל מובא בכ\"מ בשינוי. ראה גם ס' מאמרי אדהאמ\"צ בראשית ריש ע' תמז. שמות ח\"א ע' סה, וע' רחצ. ח\"ב ע' תלא, תע, תרמד. ויקרא ח\"ב ע' תרטז [ובהמ\"מ שם]. וע' תשא. ע' תשסד. במדבר ח\"ב ע' תקעא. דברים ח\"א ע' קמג. ח\"ב ע' תערב]."]]],[1900420075,"עוז וחדוה במקומו<sup data-n=\"281\">281</sup> דוקא שהוא במקומו העצמי ממש שנבדל בערך לגמרי אפי' מפנימי' דקו\"ח (שהוא בתו\"מ שלמעלה כנ\"ל) וחדוה ושמח' זו שבעצמות ממש שבלתי מורכב ומלובש אפי' בשמח' דתוה\"ק, ואעפ\"י שא' בה ואהי' אצלו שעשועי'<sup data-n=\"282\">282</sup> אצלו ממש, אין זה ערך כלל לבחי' שעשועים וחדוה שבמקומו ממש (שזהו עצם הרוממו' העצמי, כמו בבחי' יחיד' שבאדם שנק' שמחת הנפש בעצמה ממש שלמעלה גם ממדות וחכ' העצמי' שכלולי' בה כו' כנ\"ל). ועכ\"ז הרי מובן ממילא ששמחה זו העצמי' ממש מתלבשת בשמח' ש\"מ דוקא להיותה באה בהתלבשות גשמיות בסוף מעשה דוקא דנתב\"ס דוקא כנ\"ל, שזהו שנתאוה כו' ששרשה ודאי מגיע בשמחה העצמי' דא\"ס כו' (כמו שאו' וישמחו ב\"ך ב\"ך ממש כו' כנ\"ל), ודוקא שמחה ש\"מ במעשה דוקא ולא שמחה אחרת זולתה אעפ\"י שהשמחה תהי' בהשגו' דשם הוי' ואלקי' בבחי' סובב וממלא עד רום המעלות במל' דא\"ס שלפני הקו\"ח כנ\"ל, דכ\"ז ודאי אין ערך כלל לשמחה שבעצמות א\"ס שא' עוז וחדוה במקומו ממש כנ\"ל, ובודאי א\"א לומר דשמחה כזו באתדל\"ת בהשגות דהוי' ואלקי' אפי' בנשמות דבריא' וגם באצי' יוכל לעורר השמחה וחדוה שבעצמות ממש (ומ\"ש כי חדות הוי' היא מעוזכם<sup data-n=\"283\">283</sup> זהו בשמחה ש\"מ דוקא כמו בשמחה שבחג וכה\"ג שהוא מצוה בפ\"מ ולא מטעם שמחה שבהוי' למעלה בבינ' ומדות כו'), אך היינו בסתם שמחה שיוכל לבא בהשגת הנשמות ועולמות העליונים בסובב וממלא שאינו רק באור וזיו הנמשך ממל' דא\"ס בצמצום דקו\"ח כנ\"ל, אבל שמח' ש\"מ בגשמיות (אף שאינו אלא תוס' אור בשמח' בהוי' דאצילות כנ\"ל) כמו ויספו ענוים בהוי' שמחה<sup data-n=\"284\">284</sup> כו' וכה\"ג מ\"מ מגיע שמחה זו בשמח' וחדוה שבמקומו העצמי' ממש מטעם הנ\"ל שזהו מה שנמלך בנש\"צ ונתאוה כו' שזהו עצמו' השעשועים במלך כמו שהוא מרומם בעצמו ממש כנ\"ל. ולכן דקדק לומר תחת אשר לא עבדת בשמח' כו' שזהו שמח' ש\"מ דוקא ולא שמחה אחרת שמצד אור א\"ס הבא בהשגה בנשמו' למעלה כנ\"ל.\n[לו] <b>אך</b> הנה עדיין<sup data-n=\"285\">285</sup> יש להבין בזה, דמאחר שעיקר הטעם הוא רק ביתרון מעלה שבמצות בפ\"מ לבד מצד שסוף מעשה עבמ\"ת וכנ\"ל דזהו מה שנמלך כו' שמפני זה מגיע בעצמות התענוג הפשוט שמפני זה דוקא נמשך הרצון הפשוט במל' דא\"ס כנ\"ל, א\"כ זהו רק מצד עצם המעשה דמצות דוקא (כמ\"ש לעשות חסד כו' בארץ כי באלה כו') א\"כ למה דוקא בשמחה ש\"מ מעורר לשמחה ותענוג שבעצמות גם בלא שמחה מצד המצוה בעצמה דוקא",[["281","281","<b>עוז וחדוה במקומו</b>: דברי הימים-א טז, כז."],["282","282","<b>ואהי' אצלו שעשועי'</b>: ע\"פ משלי ח, לא."],["283","283","<b>חדות ה' היא מעוזכם</b>: נחמי' ח, י."],["284","284","<b>ויספו ענוים בה' שמחה</b>: ישעי' כט, יא."],["285","285","<b>[לו] אך הנה עדיין</b>: להבא להלן, ראה גם בתוס' ביאור ד\"ה שמח תשמח בסה\"מ תרנ\"ז ע' רס ואילך."]]],[1900420076,"מגיע בשעשועים העצמיי' כנ\"ל וד\"ל. אך הנה יש להקדים ענין א', והוא מה שיש הפרש גדול בין שמחה ועונג בדבר פרטי דאינו רק חלק א' קטן הנבדל מן העצמו' ממש אעפ\"י שהוא ג\"כ בחי' עונג ושמחה עצמי' ופשוט שנמשך מעצמו' התענוג הפשוט והיולי כנ\"ל, ובין השמחה ותענוג ושעשועים העצמי' שבעצמו' ממש שכל עצמותו נכלל ומתאחד בתענוג פשוט ועצמי' ההיולי שבלתי מתחלק לדבר פרט כלל כמו ברצון ועונג פרטי. ויובן זה במשל התענוג העצמי הפשוט שבנפש האדם עצמו שכולל הוא כל מה שעתיד להתפעל בעונג ורצון פרטי כו' שבודאי הוא בהעלם גדול בעצמות הנפש ולפרקים יוצא בגילוי מן ההעלם הזה והוא שמחת הנפש בעצמי' הנ\"ל כמו ביום חתונתו וכמו בגמר מלאכתו באיזה בנין נאה שמשתעשע בו ביותר שתענוג שעשועים זה הוא בעצמות הנפש ממש ולא בחלק פרטי בדבר רצון וחכ' פרטי' כלל, אבל העונג ברצון פרטי באיזה דבר מה כמו במלאכת הבנין בפרטי הרצון שבכל דבר שבבנין בפרט או בעונג שבחכ' הפרטי (וכן בשמחת לבו בחתונתו או בחתונת בנו בדבר הפרטי), אעפ\"י שהפרט הזה גם הוא עולה אל הכלל שבו בתשלום המלאכה שנשלם כל רצונו בכלל שאז מתענג ומשתעשע בעצמותו ממש (בכח היולי שבתענוג הפשוט כנ\"ל), עכ\"ז אינו אלא חלק פרטי לבד שנמשך מכללות העונג והרצון שיש לו בנפשו בכללות הבנין (או בפנימי' ביותר בתשלום רצונו בחתונתו לאחר שלקח אשה בחופה) שאין לו ערך כלל לגבי עצמות התענוג שבנפש, אעפ\"י שגם מה שמתענג בעצמו ממש אחר תשלום הבנין בכי טוב ויפה ברצונו זה ג\"כ רק ממלאכת הבנין בכי טוב, וא\"כ גם תענוג זה מורכב הוא בדבר מה, ואף שהוא בכלל הבנין מ\"מ נחשב הוא כמו פרט וחלק א' ממש לגבי כח עצמיות התענוג שבנפש שבלתי מורכב בדבר מה כלל כידוע שהוא בבחי' עצם אור פשוט לגמרי, הענין הוא דמה שמשתעשע בעצמו' אחר ראותו טוב המעשה (או מאשר נשא אשה ולקח מקח טוב וכה\"ג) זהו שעולה בעצמות התענוג ממש שבלתי מורכב כלל, ואעפ\"י שאין ערך לתענוג הזה המורכב בדבר מה לתענוג הפשוט ההיולי, הרי יש הפרש בזה בין כשמתענג מצד עצם הדבר ובין שמתענג מצד שנשלם כרצונו הפשוט שעולה במקור הכללי של כל רצון ועונג שזהו בעצם אור התענוג הפשוט לגמרי, רק שמה שנעשה המלאכה בכי טוב שמתענג מעצם הדבר בכללותו דוקא הוא שגורם התענוג הפשוט ממה שנשלם הכל כרצונו, שאין זה מצד עצם הרצון בכל פרט רק ממה שא' וכן נעשה שהוא המכוון בכללותו לפנימי' התענוג שבעצמו עד שכל עצמו ופנימיותו נמשך בתענוג זה, והוא השמחה העצמי' שבנפש שתשמח בעצמה ממש מגמר טוב הבנין או המקח שלקח ממה שנשלם הכל כרצונו בעצמותו, שזהו רק ממה שנעשה רצונו, ואמנם עכ\"ז פנימי' רצונו בזה דוקא הוא שגורם השמחה בנפשו אח\"כ מכללותו ושלימותו שיגיע בשמחת הנפש מצד עצמה ממש, אבל בדבר שאין פנימי' רצונו בזה כ\"כ שלא ישמח כלל ממה שנעשה כרצונו שאין זה מגיע לעורר"],[1900420077,"שמחה העצמי' הפשוטה, רק בדבר שפנימי' נפשו ברצון פשוט ועצמי רק שמורכב בדבר מה עולה הוא לעצמות התענוג והשמחה כשנעשה כרצונו בכללותו בתנאי כשישמח במעשיו דוקא במה שנעשה בכי טוב שמגיע זה בעצמו' בעל הרצון הפשוט שמשם מקור כל רצון ועונג עד ששמח בעצמו ממש כנ\"ל, כי שמחה זו ששמח ממה שא' ונעשה רצונו הרי הוא בבחי' עצמיות התענוג שלמעלה מהתפעלות עונג בפרט הדבר ההוא אעפ\"י שסיבתו בא מן העונג שמקבל מפרט הדבר.\n[לז] <b>ונמצא</b> מובן מכ\"ז<sup data-n=\"286\">286</sup> דאעפ\"י שעונג המורכב בפרט לא יוכל להגיע לעונג הפשוט הכללי הנ\"ל רק בדבר הזה עצמו בכללותו שהוא מה שנשלם כרצונו בדבר זה כו', אבל בבחי' השמחה שבעונג הגם שהוא בדבר פרטי שאין זה רק ממה שא' ונעשה רצונו ולא מצד העונג ברצון זה הפרטי אין הפרש בזה בין שמחה פרטי' שישמח בנפשו משלימות מלאכה פרטי' לשמח' הכללית שישמח בנפשו בכלל בכללות הבנין שנעשה רצונו הפנימי' שנוגע בפנימי' ועצמי' נפשו ממש (כידוע דכל עצם בלתי מתחלק<sup data-n=\"287\">287</sup> וחלק הפרט ממנו דומה להכלל ממש), וראי' לזה ממס\"נ שיוכל להפקיר כל נפשו עבור רצון וחשק בנפש לדבר פרטי כמו בשביל נצחון בדבר פרטי או לתאוות הממון והגדולה (וכמו חולת אהבה בדבר שנפשו חמדתו וכה\"ג יומשך כל הנפש בעצמה אף בחלק א' פרטי מתאוות הנפש, כי גם חלק הפרטי כמו הכלל יחשב אם הוא בבחי' רצון שמגיע בפנימי' שבנפש ומתאחד בכולה ממש ולכך תשמח הנפש בעצמה גם בפרט הרצון הפנימי כמו בכלל כנ\"ל (וכמו במע\"ב בכלל ובפרט דגם שבפרט בכל בריאה נא' וירא אלקי' כי טוב<sup data-n=\"288\">288</sup> אין זה רק בחי' עונג פרטי ברצון פרטי, אבל לאחר תשלום כל המלאכה דמע\"ב א' וירא אלקים את כל אשר עשה בכללותו והנה טוב מאד, ומאד זה היינו בבחי' התענוג הפשוט ועצמי שבעצמות א\"ס כמו בחי' שעשועי המלך בעצמו ממש כנ\"ל (וכמו שמחת הנפש בעצמה ממש כנ\"ל), והוא שנק' מאד בתענוג בלתי מוגבל כלל והוא במה שבלתי מורכב בדבר פרטי כנ\"ל אלא הוא תענוג פשוט הכלול באח\"פ ממש ואעפ\"י שסיבתו הוא מצד תענוג מורכב בכל אשר עשה שהוא טוב מאד וא\"כ מאד זה בכל אשר עשה שנשלם הכל כרצונו במלאכה זו דמע\"ב בכלל שמתאחד הוא בעצמו' התענוג הפשוט, ואעפ\"י שגם תענוג זה הכללי מכללות דמע\"ב נק' מורכב ולמה נק' טוב מאד שהרי משמע שתענוג זה הוא עצמו שנק' טוב מאד, היינו לפי שנעשה מכוון כרצונו הפשוט",[["286","286","<b>[לז] ונמצא מובן מכ\"ז</b>: להבא להלן, ראה ד\"ה שמח תשמח שם ע' רסא ואילך."],["287","287","<b>דכל עצם בלתי מתחלק</b>: ראה גם אמרי בינה שער הק\"ש פ\"ח. תו\"ח וישב סח, א. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשמ. דברים ח\"ב ע' תרמז. ח\"ג ע' תתא. תתכד. תתכו. סה\"מ תרמ\"ז ע' קב."],["288","288","<b>וירא אלקים כי טוב</b>: בראשית א, יב ואילך."]]],[1900420078,"בעצמותו כשעלה ברצונו הפשוט להיות בנין העולמות ומע\"ב שע\"ז א' כי אמרתי עולם חסד יבנה<sup data-n=\"289\">289</sup> פשוט ועצמי שהוא בבחי' התענוג הפשוט הנ\"ל, ובשלימות רצונו במע\"ב עולה הוא בעצמו' התענוג ממש כנ\"ל וד\"ל. (ולפי\"ז אין זה מצד עצם הרצון בכלל במע\"ב הוא שנק' טוב מאד אלא מצד שנעשה רצונו כנ\"ל, ובאמת הפשט מורה שכל אשר עשה במע\"ב הוא טוב מאד בתענוג בלתי מוגבל ומורכב כלל כעצמו' התענוג הפשוט ממש כו', ומוכרח לומר דגם תענוג זה שמורכב במע\"ב אף בכללותו נחשב מבחי' התענוג הפשוט ממש והוא עצמו נק' טוב מאד ממש, והיינו שזהו שהי' התענוג הפשוט העצמי בתחילת הרצון להשפיע בחסדו העצמי להיות בנין העולמות וכמ\"ש כי אמרתי כו', ואעפ\"י שהוא תענוג שבהשפעה לבד עכ\"ז נחשב מעצמות התענוג, לפי שכל עצמות התענוג נמשך גם בחלק פרטי זה, וכמו שרואים בכל משפיע אף שמשפיע שכל וחכמה גשמי בפ\"מ שמתענג בנפשו בעצמו ממש מטוב חסדו זה אעפ\"י שאינו רק פרט עונג, וכך במע\"ב מכל אשר עשה והשפיע נחשב תענוג עצמי ואעפ\"י שא' טוב מאד על עצם ההשפעה מצד עצמו שהוא טוב מאד דוקא והוא כמו שעלה ברצונו הפשוט שהי' זה בתענוג עצמי' ממש. וכ\"ז מטעם הנ\"ל דאין הפרש כלל בפנימי' רצון ועונג בין בדבר פרטי שחלק א' הוא מעצמות התענוג בין כללות עצמות התענוג מאחר שאנו רואין שכללות כח עצמיות התענוג נמשך בפרט זה. אך זהו דוקא במה שפנימי' רצונו בו ולא בדבר שחיצוניות הרצון בו לבד שאין עונג ורצון פרטי יוכל להגיע לעונג ורצון הכללי הנ\"ל, ואעפ\"י שמתענג אדם גם בשפע חיצוניו' בנפשו ממש, זהו דוקא בשמחה שבעצמותו כמו בחתונתו שישפיע בחסדו לכל בגשמיות כו' וכן בחנוכת הבית דהתענוג בבנין אעפ\"י שהוא פרטי מגיע בעצמות התענוג שבנפשו ממש. וכך יובן בחסד דמע\"ב שאחר שהוטב בעיניו כל אשר עשה נתענג בתענוג העצמי ממש וע\"כ נק' גם העונג שבמע\"ב בכלל בבחי' טוב מאד כי אין לחלק בין פרט לכלל בבחי' הפנימי', אך עכ\"ז יש הפרש בין פנימי' העונג שמגיע לעצמותו ממש כמו בחתונתו או בחתונת בנו וכל הנוגע לפנימי' עצמותו, ובין כל שפע שנמשך מחסדו אעפ\"י שמתענג בעצמו בזה, שא\"א שיגיע בעצמותו ממש אף מכללות כל אשר השפיע, רק בבנין ביתו שישב וידור בו וכה\"ג שאנו רואים שאדם בגמר מלאכתו בבנין בית עושה משתה וסעודה וישמח בשמח' עצמי' ממש לפי שהוא נחשב מבחי' עצמותו (כי הדירה וההיכל הוא בבחי' מקיף למקיף לנפשו כידוע, אך אין זה רק בהיכלות הפנימי' ולא במה שבונה לצורך אנשים כמו משרתיו עושי רצונו כו', וכך יובן במע\"ב בגוף הבריאה דעש\"נ שבחי' פנימי' יותר זהו מה שנתאוה להיות לו דירה במצות (וכמו בבנין בהמ\"ק וכה\"ג וד\"ל).",[["289","289","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."]]],[1900420079,"<b>ואמנם</b> הנה באמת עיקר ההפרש בכ\"ז הוא בין עונג לשמחה, דודאי בבחי' עונג שהוא מצד עצם הרצון כפי מה שהוא מורכב בדבר מה יש הפרש בין פרטי לכללי, ואעפ\"י שיוכל להגיע ממנו גם בעונג הכללי כמו מעונג ההשפעה בחיצוניות ובפנימי' כנ\"ל מ\"מ אין זה ערך לעצמו' התענוג הפשוט ההיולי שבעצמו' הנפש ממש כנ\"ל, אבל ענין השמחה אעפ\"י שהוא ענין א' עם העונג, ואדרבה השמחה אינו אלא גילוי העונג שהוא החדוה מעצם הדבר הטוב שמגלה אותו בשמחתו כמו כשעושה משתה ושמח' בהגיע לו בשורה טובה ששמחה זו מגלה העונג הצפון בלבו כו', אך עכ\"ז זה עצמו מה שיש בכח טבע השמחה שמגלה הנעלם שבעונג שבלבו זהו מורה שעצם השמחה הוא למעלה מן עצם העונג הפרטי הזה ע\"כ יביאנו לגילוי בהתפשטות חיצוניות כמו לרקד ולשחוק בהוללות כו'. והענין הוא לפי שהשמחה שרשה ברוממות ועצמיות הנפש ממש ע\"כ בכחה להמתיק כל דין לעשות היפוך הטבע האנושית בתולדתה כו' כנ\"ל, הגם שערך העונג מדבר הטוב מורכב הוא בדבר פרטי, אבל השמחה שישמח מזה הרי היא בעצמו' רוממות הנפש שבלתי מורכב בדבר מה כלל (והוא ג\"כ תענוג הפשוט שמתאחד בכל הנפש). ואמנם שמחה כזאת אינה באה רק מעונג שברצון כללי, שזהו הנוגע לעצמות נפשו דוקא, כמו ברצון ותענוג שיהי' לו מזה שעושי' רצונו בכל אשר יגזור אומר, שזהו התענוג שבעצם הנפש בלתי מורכב בדבר פרטי זה שעושה רצונו הפרטי רק נח\"ר לפניו מכל אשר יעשה רצונו יהי' מי שיהי', וכך יש תענוג ושמחה כללית מכל אשר עשה ונעשה הכל כרצונו שאין זה מצד עצם הרצון ועונג אלא ממה שהכל נשמעי' לרצונו וכל אשר חפץ נעשה כו' (שמגיע ברוממות דעצמות הנפש ממש), וא\"כ מהות השמחה עכ\"פ כללית היא מכל אשר נעשה לטובתו או השלמת רצונו יהי' מה שיהי' שאז תשמח נפשו בעצמו ממש כו'. וא\"כ ודאי מובן מזה שאין לחלק במהות השמחה בין שהיא מאיזה דבר רצון פרטי שנעשה רצונו שנח\"ר ושמחה ממה שעשה רצונו, או מכללות כל הרצונות שנעשה בחפצו, הכל אינו רק שמחה ונח\"ר ותענוג העצמי שנבדל בערך מן העונג ורצון הפרטי עד ששוה שם ענין ההשלמה שנשלם רצונו בפרט או בכלל כי גם הפרט כמו כלל הוא רק מה שמשמח בנפשו ממה שגוזר ועושה רצונו ולא מצד עצם הרצון לבד כנ\"ל וד\"ל (ובכ\"ז יתורץ כל ענין הנ\"ל בפנימי' העונג ובחיצוניות בהפרש שבין פרט לכלל ובהתכללות הפרט אל הכלל שבכ\"ז יש יתרון מעלה בשמחה על העונג בכלל ובפרט מטעם הנ\"ל וד\"ל).\n[לח] <b>והנה</b> הנמשל מכל הנ\"ל<sup data-n=\"290\">290</sup> יובן ג\"כ בדוגמא כזאת ממש בטעם ושרש ענין שמחה של מצוה הנ\"ל דגדול מעלתה כ\"כ יותר מגוף מעשה",[["290","290","<b>[לח] והנה הנמשל מכל הנ\"ל</b>: להבא להלן, ראה בתוס' ביאור ד\"ה שמח תשמח, בסה\"מ תרנ\"ז ע' רסג ואילך."]]],[1900420080,"המצוה עצמה אף שממנה דוקא יהי' שכר העוה\"ב כידוע דשכר מצוה מצוה עצמה<sup data-n=\"291\">291</sup> כו', והוא לפי שנתאוה כו' וסוף מעשה כו' כנ\"ל, להיות דודאי יש בכל מצוה ומצוה מבחי' פנימי' רצה\"ע ממש דאיהו ופנימי' רצונו חד ממש וכמ\"ש רחבה מצותך מאד בלי גבול כלל (כמשי\"ת), ואעפ\"י שעונג ורצה\"ע הזה הפנימי' מורכב הוא בדבר וענין פרטי כמו במצות תפילין או טלית וצדקה וכה\"ג, הרי יש שרש ומקור לרצה\"ע הזה במקור כל רצון ועונג העליון הכללי שנק' תענוג ורצון הפשוט בעצמו' א\"ס ממש (שנק' שעשועי המלך בעצמותו ממש כנ\"ל, והוא בחי' השמחה שבעצמו' ממש (כמשי\"ת), שהארה א' ממנו הוא העדן דעוה\"ב שבא בשכר המצות דעכשיו (שנק' פרס כו'). ואעפ\"י שמבואר למעלה דעונג פרטי המורכב בדבר מה אין לו ערך לגבי עצמו' התענוג ורצה\"פ ההיולי שממנו מקור כל רצון ועונג כו' כנ\"ל, כמשל הנ\"ל בעת חתונתו או בגמר מלאכתו אעפ\"י שמתענג בעצמו' ממש מכללות המעשה וגם הפרט עולה אל הכלל גם הכלל נחשב פרט לגבי עצמות התענוג כי מצד עצם הדבר תענוג מורכב הוא ואין לו ערך לתענוג פשוט, מ\"מ כשאינו מתענג רק ממה שנעשה רצונו כו' שעולה במקור הכללי של כל רצון ועונג כו' עד שכל עצמו נמשך גם בפרט זה ואין לחלק בזה בין פרט לכלל, ואך בתנאי שיהי' רצון לעונג בפנימי' דווקא ולא בחיצוניות לפי שבפנימי' ועצמי' שוה הפרט עם הכלל כו'. וכך הוא גם בענין עונג פרטי שבמצוה הפרטי' שגם שנק' תענוג מורכב בדבר מה מ\"מ עיקר התענוג העליון במצוה זו הוא ממה שא' ונעשה רצונו לבד שזה מגיע בעצמות התענוג הכללי הפשוט שהוא בעל הרצון הפנימי' שממנו מקור כל רצון העליון. וזהו כמו ענין שמחה של מצוה למטה בנפש האדם מלמטה למעלה שעיקר השמחה הוא רק מה שעשה נח\"ר ליוצרו לקיים רצונו יהי' מה שיהי' ולא מצד עצם הדבר מצוה שיודע בה איזה טעם וסוד להתענג בנפשו בכוונה טובה בסוד השכל וחכ' עילאה המושג ברצה\"ע שבמצוה כמצות תפילין בד' בתים שהוא להאיר בחי' מקיפים דד' מוחין וכה\"ג, אלא רק לפי שזהו יהי' לעונג ונח\"ר לבעל הרצון הזה, וא\"כ הרי העונג ושמחה זאת שישמח במעשה המצוה רק מצד שעשה רצון קונו מגיע למעלה ג\"כ בבחי' שמחה ועונג העצמי' ממש שלמעלה מן העונג הפרטי שמלובש במצוה זו רק מצד שא' ונעשה רצונו כנ\"ל שזהו בעצמות בעל הרצון דהיינו במקור כל פנימי' רצה\"ע שבכל המצות למעלה (וכמבואר למעלה שאין הפרש בזה בין פרט לכלל בדברים שהוא בפנימי' ועצמי' דוקא כו'). וזהו שרש ענין הנ\"ל דבשמחה ש\"מ למטה מעורר השמח' שמצד עצמותו ממש (וכמו וישמחו בך כו'), ולא מצד ההעלאה דאתדל\"ת שאין לו ערך (אפי' מצד רצה\"ע הפנימי' שבמצוה זו שאינה רק חלק פרטי מורכב מעצמות התענוג הפשוט וכנ\"ל), רק מצד שמח' ש\"מ זו ממה שעשה רצונו ית', לפי שעי\"ז דוקא מעוררים שמחה ש\"מ כמו שהוא למעלה",[["291","291","<b>כידוע דשכר מצוה מצוה עצמה</b>: אבות פ\"ד מ\"ב."]]],[1900420081,"שהוא בשמחה שבעצמותו ממש, והיינו מה שא' ונעשה רצונו זה במצוה זו כו' (ואין זה נק' אתדל\"ת בהעלא' שגורם המשכה מאחר שאין זה מצד עצם הרצה\"ע שבמצוה זו אלא ממילא יאיר בשמחה ש\"מ זו למעלה בבחי' שמחה דעצמיו' בעל הרצון כו' וד\"ל).\n<b>אך</b> עכ\"ז עדיין אין זה מובן דלמה דוקא בשמחה ש\"מ, הלא גם בלא שמח' מצד עונג הפשוט שמאיר בעונג פרטי הזה (מאחר שבפנימי' ועצמי' אין לחלק בין פרט לכלל כנ\"ל) מעורר לבחי' התענוג הפשוט והוא הנח\"ר שא' ונעשה רצונו עכ\"פ, ואין ענין שמח' ש\"מ מגיע רק בשמחה העצמיות שזהו התענוג הפשוט והיינו הך. ועוד למה בשמח' ש\"מ דוקא דמטעם שא' ונעשה רצונו לבד זה יוכל להיות אף ברצון שאינו ש\"מ כלל כמו ברצון ועונש שבחסד דמע\"ב וכמו וירא את כל אשר עשה שזהו שנשלם כרצונו בתחילה כו' כנ\"ל שמגיע ג\"כ בתענוג ושמחה הפשוטה שנק' טוב מאד כנ\"ל. אך הנה צריך לומר שיש בזה ב' תנאי' דוקא, הא' בשמח' דוקא שהוא למעלה מן העונג כנ\"ל שהשמחה מגיע ברוממות העצמות דנפש ממש שלמעלה מהגבלת העונג העצמי ג\"כ (מאחר שיוכל להפוך הטבע בשמחה העצמי' מעונג להיפוכו וכמו\"כ מצער לעונג כמו למאוס באוהבו ולחפוץ בשונאו כו'), וזהו מה שיש בכח השמחה לגלות הצפון כנ\"ל, וא\"כ גם שמחה זו ממה שנשלם ונעשה כרצונו מגיע ברוממו' העצמיו' שלמעלה גם מתענוג הפשוט הנ\"ל ואין הפרש בשמחה בין פרט לכלל כנ\"ל, ואמנם תנאי הב' שיהי' שמחה זו במה שהוא פנימי' ועצמי' רצונו דוקא כמו שמחה ש\"מ שאז שמחה זו מגיע בעצמות שמחת הנפש שבעצמותו ממש שלמעלה גם מן התענוג שבעצמות בכלל, כמו שיש הפרש בזה גם בדבר פרט בין שמחה לעונג כנ\"ל, וזהו שרש ענין שמח' ש\"מ בפרט שזהו כמו בכלל משא\"כ בעונג שבפרט כו' וד\"ל. וזהו ההפרש בין עצם רצה\"ע שבמצו' שע\"ז א' אם צדקת מה תתן לו כו', לפי שאינה מגעת רק עד שרש הכללי של אותו רצה\"ע שנק' רצון פשוט, ושרש רצון פשוט הזה בתענוג הפשוט לבד כו', אבל שמח' ש\"מ זו מגעת למעלה גם מתענוג הפשוט, והוא בבחי' שמחה שבעצמותו ית' שמגיע ברוממו' העצמיו' ממש (שלמעל' גם משעשועי' העצמי' שמאיר בעוה\"ב משכר מעשה המצות כנ\"ל וד\"ל). וראי' לזה ממה שמצינו בכתבי האריז\"ל שכל מה שהגיע האריז\"ל למדריגה גילוי אליהו ורוה\"ק בגילוי סודות הקבלה האמיתית הכל מן שמחה ש\"מ בלבד<sup data-n=\"292\">292</sup>, שזהו רק מה שהי' שמח בשמח' ש\"מ כפשוטו דוקא, והוא רק לעשות נח\"ר ליוצרו שעשה רצונו אף שלא הי' יודע עדיין בטוב טעם סוד ה' במצות כלל והי' עושה",[["292","292","<b>בכתבי האריז\"ל שכל מה שהגיע האריז\"ל. . מן שמחה ש\"מ בלבד</b>: בהקדמת ס' חרדים: וכן גילה הרה\"ח המקובל כהר\"ר יצחק אשכנזי זצ\"ל לאיש סודו שכל מה שהשיג שנפתחו לו שערי החכמה ורוה\"ק בשכר שהי' שמח בעשיית כל מצוה שמחה גדולה לאין תכלית כו'. וראה המובא ע\"ז עוד בארוכה ב”מילואים להמ\"מ\" בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"ג ס\"ע א'רפ. וראה ס' מאמרי אדהאמ\"צ נ\"ך ע' כז."]]],[1900420082,"שלא בכוונה פנימי' רק עכ\"ז הי' שמח שמחה גדולה כאיש פחות הערך ששמח בשמחה ש\"מ, לפי שבשמחה כזו הכל שוין ממש כקטן כגדול ממש מאחר שזהו שמחת הנפש בעצמו שמגיע למעלה מן העונג והרצון שמגיע למעלה בשמחה שבעצמותו ממש שהכל שוין שם להיות למעלה מן התו' והמצות רק ממה שאמר ונעשה רצונו שהוא למעלה גם מתענוג הפשוט שבעצמו' במצות כמו בעוה\"ב כנ\"ל, וע\"כ השמחה ש\"מ כולל ממילא גם כל מה שיש במצות בחי' תענוג הפשוט שהוא בחי' הסוד וטעם הגנוז ונעלם בבחי' העונג הנעלם דעוה\"ב שנק' טעמי מצוות בכלל וד\"ל.\n<b></b>[טל] ולהבין עד היכן מגיע כחה של שמחה ש\"מ אפי' בע\"ה שלא ידע מה שעושה רק מצד עוצם התמימות שמח לעשות נח\"ר ליוצרו בדבר זה שמדמה שנח\"ר הוא לבורא כמו שנמצא בס' משנת חכמי' בע\"ה ששמע דרשת הרב במצות לחם הפנים, והי' סבור שלחם הפנים הוא לאכילה לפני ה' שאוכלם כמו שאוכל אדם, ועשה שתי לחם בשמח' גדולה הוא ואשתו לבושים בבגדי שבת אחר חצי יום עש\"ק להטמינם בארון בבהכ\"נ, ולמחר לא מצאם בארון, סבר שאכלם הבורא ושמח הוא ואשתו שמחה גדולה ועשו כן כמה פעמים בכל ע\"ש, ושמש בהכ\"נ הי' לוקחם בכל שבת בבוקר לסעודתו, ונשמע הדבר להרב וגער עליו ונתבטל ונענש הרב ומת באותה שנה, ואמרו לו שמזמן בהמ\"ק ראשון ובימי משה במשכן לא הי' שמח' לפני ה' בלחה\"פ<sup data-n=\"293\">293</sup> כמו ממעשה לחה\"פ שעשה זה העני בתום לבב בשמחה וטוב לבב הוא ואשתו שעשה נח\"ר ליוצרו שאכל לחם זה כמביא לפני מלך כו'.\n<b>וזהו</b> תחת אשר לא עבדת כו', שאעפ\"י שהמצות נעשים ברצון ה' בתכלית הכשרון אעפ\"י שעי\"ז יומשך תוס' אור באצי' ובכל העולמות אפי' בג\"ע העליון (ושרש שרשה הוא בעונג ורצה\"ע העצמי' בבחי' א\"ס ממש כמ\"ש רחבה מצותך מאד<sup data-n=\"294\">294</sup>), אך נמשך ויורד העונג העליון הזה בריבוי הצמצומי' והעלמו' ומסכי' רבים ע\"י המסך שבין כל עולם ועולם שנק' פרסא, כמו הפרסא שבין עצמו' המאציל לנאצלים ומאצי' לבריאה עד המסך שבין יצי' ועשי' שבעוה\"ז השפל הוא תכלית ההסתר והצמצום, וע\"כ הרי אנו אומרים אשר קדשנו במצותיו ממש כמו המצוה שבעצמו' א\"ס שנק' מצותיך ממש כו' (ודוגמא לזה במצות שבת ויו\"ט<sup data-n=\"295\">295</sup> שהוא במוחי' דאו\"א שנק' קודש ומקראי קודש כידוע, ובחי'",[["293","293","<b>בס' משנת חכמים בע\"ה ששמע דרשת הרב במצות לחה\"פ</b>: להר\"מ חגיז, אות ר\"כ. [סיפור זה נזכר גם ברשימת חסיד א' בכת\"י 355 עו, א]."],["294","294","<b>רחבה מצותך מאד</b>: תהלים קיט, צו."],["295","295","<b>במצות שבת ויו\"ט. . קודש ומקראי קודש כידוע. . כי קודש היא לכם</b>: תשא לא, יד. זח\"ג צד, א ומק\"מ שם. פע\"ח שער ר\"ה פ\"ב. שער מקראי קודש פ\"א. לקו\"ת צו יא, ד ואילך. שם דרושים לר\"ה נז, סע\"א [בשם הע\"ח], וע\"ש בהמ\"מ [בהוצאת קה\"ת, ה'תשד\"מ ואילך]."]]],[1900420083,"או\"א שהוא חו\"ב יש בכל עולם לפ\"ע דוקא, והוא שמתצמצם ויורד מחו\"ב שבעצמו' המאציל באצי' ע\"י פרסא הנ\"ל, וכן מאצי' לבריאה, עד חו\"ב שבמל' מעשי' שנק' גם הוא שבת קודש כמ\"ש כי קודש הוא לכם, כי בעוה\"ז השבת הוא כפשוטו שבו שבת מכל מלאכתו ממש בפ\"מ כו' שזהו מה שכולם בחכ' עשית בפ\"מ, וכן ביו\"ט במוחי' דאימא שנק' מקראי קודש כו', ועכ\"ז או' וקראת לשבת עונג<sup data-n=\"296\">296</sup> העליון דפנימי' עתיק עד פנימי' התענוג הפשוט שבעצמות א\"ס ממש, וכן ביו\"ט נק' מועדים לשמחה בשמחה שבעצמותו ממש, ואין כל המסכים והעלמות מסתירים כלל וכלל, וכך הוא מ\"ש בע\"ח דכל עיקר המצות אינו רק להוסיף אור באצי'<sup data-n=\"297\">297</sup> לבד דמשמע מזה שאין תוס' אור זה שע\"י המצות מגיע למטה בבי\"ע רק ע\"י העלמות ומסכים כנ\"ל אבל באמת אינו כן דכל המסכים והצמצומים אינם מסתירים כלל וכלל, רק בתנאי כשיש שמחה ש\"מ דוקא מטעם הנ\"ל, כי מצד שהמצוה הוא בחי' פנימי' רצה\"ע ויש בה שמחה שעשה נח\"ר ליוצרו ממה שנעשה רצונו ה\"ז מגיע בבחי' שמחה ש\"מ זו עצמה בבעל הרצון עצמו שמצד רוממות עצמותו שלמעלה גם מן העונג כו' כנ\"ל, ובחי' שמחה שבעצמותו שנעשה משמח' ש\"מ שלמטה ה\"ז בא ומאיר למטה מטה בבחי' דילוג המדריגות שלא לפ\"ע סדר ההשתלשלות לגמרי עד שמאיר למטה כמו שהוא למעלה ממש (ואין כל צמצום מסתיר לפני אור שמחה העצמי' הזאת שבאה משמחה של מצוה ובוקע כל מסך ואפי' בצמצום הראשון דישת חושך סתרו שנק' מק\"פ כו' דקמי' כחשוכא כאורה ממש) (וראי' לזה ממה שנתלבש שמחה העצמי' שבבחי' מקיף העליון בסכך דסוכה ובענני כבוד כו' וד\"ל).\n<b>וזהו</b> תחת אשר לא עבדת את ה' בשמחה וטוב לבב מרוב כל יותר מכל חיי העוה\"ב שאינו רק אור א' משעשועים וחדוה העליונה שבמקומו העצמי' (ופי' הפשוט מרוב כל דכל טוב העליון שהגיע להם בעבור הטוב דמצות בא\"י שאז נמתק הדין בשרשו כשהוא בעצם הטוב שהתענוג והשמח' הוא כא' ממש והכל בעבודה דבמצות דוקא מרוב כל כו'). וכך גם עתה בשמחה של מצוה רק שהוא בטוב לבב אעפ\"י שאינו מרוב כל אדרבא מן המיצר ודוחק ועכ\"ז שמחים בשמחה של מצוה, נמשך עי\"ז ממקור הברכות יותר, והוא הברכה דעוה\"ב (שנק' ברכת ה' תעשיר כו' כידוע<sup data-n=\"298\">298</sup>) שאחר הגלות דוקא שיבא מחמת שמח' ש\"מ (כמו השמחים ביסורים א' ואוהביו<sup data-n=\"299\">299</sup> כצאת השמש בגבורתו שנמתקו כל הדינים בשרשם, והוא מה שכל הקללות יהופכו לברכות אעפ\"י שהי' זה תחת אשר לא",[["296","296","<b>שכולם בחכמה עשית. . וקראת לשבת עונג</b>: תהלים קד, כד. ישעי' נח, יג."],["297","297","<b>בע\"ח דכל עיקר המצות. . להוסיף אור באצי'</b>: ראה לעיל אות כ\"ט. וש\"נ."],["298","298","<b>שנק' ברכת ה' תעשיר כו' כידוע</b>: משלי י, כב. ראה שערי תשובה ח\"א סו, סע\"א ואילך. ס' מאמרי אדהאמ\"צ שמות ח\"ב ע' שעד."],["299","299","<b>השמחים ביסורים א' ואוהביו</b>: שבת פח, ב. שופטים ה, לא."]]],[1900420084,"עבדת כו' בשמחה מרוב כל (וזהו נראה בעליל בכל מי שהגיע לרוב כל ואינו עובד בשמחה וטוב לבב וחדוה לה' כו' כי רם לבבו יפול ביד אויביו כו', וכך הוא בכלל כאשר ייטיב ה' להם ישבעו וירום לבבם וישכחו על ה' לומר כוחי ועוצם ידי כו' ומתגאים, ואז יפלו בלחץ ודוחק לעבוד אויב כו', ובשמח' ש\"מ של עניי' יגאלו כמ\"ש ויספו ענוים<sup data-n=\"300\">300</sup> בהוי' שמחה ואביוני אדם בקדוש ישראל כו' וד\"ל).\n[מ] <b>ובכל</b> הנ\"ל יובן בתוס' ביאור ענין הברכה דשמח תשמח רעים האהובים כשמחך יצירך בג\"ע מקדם כו'. דהנה כמו שמבואר למעלה בשרש ענין שמחה ש\"מ שמגיע בבחי' שמחה העצמי' דעצמו' א\"ס ב\"ה שלמעלה מעלה מכל סדר ההשתל' דקו וחוט באבי\"ע ופורץ גדר דקו המדה כו' להאיר למטה כמו למעלה ממש כנ\"ל, הרי כ\"ז בשמחה פרטי' כמו ממצוה פרטי' לבד (שאינו רק המשכת עונג ורצה\"ע בפרט במצוה זו רק ששמחה של מצוה עולה למעלה גם מעונג ורצון זה ועכ\"ז השמחה אינה רק ממה שעשה רצה\"ע הזה בפרט), שגם שיש בכל מצוה ומצוה בפרט יחודים עליונים דהוי' ואלקים מ\"ה וב\"ן משפיע ומקבל דנק' יחוד קוב\"ה ושכינתיה, אבל ה\"ז דוקא בהמשכה פרטי' באו\"כ מיוחד שנק' אבר אחד לבד מבחי' רמ\"ח איברי' דמלכא כו' שהן רמ\"ח מ\"ע העליונים דאצי' כידוע, אבל הנה במצות שמחת חו\"כ למעלה שנק' ריעים האהובים בכלל שמיוחדים בעצמם נמשך כל יחודי' עליונים בפרטי' דמעשה המצות עליונים ותחתונים ה\"ז ודאי למעלה הרבה מכל השמחות הפרטי' שיש בכל מצוה בפרט, לפי ששמחת חו\"כ הרי הוא הגורם ועושה לעיקר היחוד במשפיע ומקבל בעצם מהותם שזהו למעלה יחוד הוי' ואלקים שנק' סובב וממלא בעצמם שבהם כלולים כל השמחות דמצות שיוכל להיות יחודים עליונים בכל מצוה בפרט שבא בגילוי באו\"כ מיוחד כנ\"ל וד\"ל. והענין הוא דכדי שיוכל להיות יחוד דחו\"כ דמשפיע ומקבל למעלה (שזהו שלימות דבחינת אד\"ם שהוא דכר ונוק' כו') צריך שיאיר עליהם מבחי' מקיף היותר עליון מבחי' עצמות אא\"ס ב\"ה שנק' שלימותא דכולא שממנו יבא שלימו' זה ביחוד דמשפיע ומקבל שיוכלו להתייחד יחד ולהיות מולידי' תולדו' אורות חדשים כו', וידוע דמקיף הזה הוא הנק' מזל\"א שחופף ושורה בחופה<sup data-n=\"301\">301</sup> דוקא שחופה הוא בחי' מקיף החופף על שניהם ביחד דוקא, כידוע בענין מקדש עמ\"י ע\"י חופה וקידושין כו', וכמו שא' דאין שמחה אלא בחופה דוקא, שהכונה הוא על בחי' שמחה העליונה שבעצמותו ית' שמשמח לחו\"כ שמאיר שמחה העליונה הזאת בחופה זו שעל חו\"כ דוקא וד\"ל.",[["300","300","<b>ויספו ענוים</b>: ישעי' כט, יט. וראה ס' מאמרי אדהאמ\"צ נ\"ך ע' כז."],["301","301","<b>דאין שמחה אלא בחופה</b>: סוכה כה, ב."]]],[1900420085,"<b>וזהו</b> שא' שמח תשמח, שמח לדכורא ותשמח לנוק' (או תשמח לע\"ל אחר תשלום הבירורים דכל מעשה המצות בפרט שיהי' למעלה ממדריג' דאדה\"ר וחוה קודם החטא לפי שנעוץ תחילתן בסופן דוקא כידוע), שהן ריעי' האהובי' ביחד דמשפיע ומקבל (עד רום המעלות גם בת\"ת ומל' דא\"ס עצמו), שהוא ע\"י בחי' השמחה שבעצמותו ממש עי\"ז יוכל להיות כח ועוז בחו\"כ מ\"ה וב\"ן שבכל הפרצופים להתייחד ולהוליד כו'. כשמחך יצירך בג\"ע מקדם מקדמונו של עולם<sup data-n=\"302\">302</sup> ששמח לאדה\"ר ואשתו בחופתם שעשה להם, והיינו מבחי' שמחה שבעצמות המשיך כח ועוז השמחה באו\"ח שישמחו גם הם בחופה שלהם (כמו עד\"מ מי שרוצה לשמח לריעהו צריך שיהי' הוא בעצמו בשמחה גדולה ביותר עד שמחמת זה יוכל לפעול אורה ושמח' בחו\"כ (וכמו שמרקדים לפני החו\"כ כו'), כטבע השמח' העצמי' שפורץ גדר לצאת ממקומו שלא בערך והדרגה כלל, והיינו לפי שבהתכללות דכר ונוק' יחד שורה מאח\"פ ממש דאדם אדמה לעליון ממש (אע\"פ שלא אדם הוא, אבל בחי' שלימות דהתכללות דאדם מעורר למהו\"ע ממש שלמעלה מבחי' משפיע ומקבל, וע\"כ משמחתו העצמי' דוקא שהוא שלימותא דכולא באח\"פ ממש הוא ששמח לאדה\"ר שכולל כל הנשמות דדכ\"ר ונוק' שיהי' מכחם שמחה בכל זיווג חו\"כ בפרט שיוכלו עי\"ז להתייחד ולהוליד תולדות כו'. וזהו הבקשה שכך יהי' שמחה דעכשיו לריעים האהובים בכלל ובפרט עד למטה כמו למעלה ממש, והוא כמו ששמחך יצירך בג\"ע מקד\"ם מקדמונו של עולם ממש כנ\"ל וד\"ל. ומה שא' כשמחך לשון יחיד אעפ\"י שמסיים משמח חתן וכלה, היינו לפי ששמחת הכלה שהיא חוה שהיתה אחת מצלעותיו נכלל בשמחת אדה\"ר, שמשמחת חתן יומשך שמחת הכלה דוקא (וכמו שמח לדכורא ואח\"כ תשמח גם לנוק'), אעפ\"י שבשמחה דעצמות ממש נכלל המקבל במשפיע (כמו כי הוי' הוא האלקים) רק בירידת האור והשמחה למטה משמח חתן ואח\"כ כלה כמו ואל אישך<sup data-n=\"303\">303</sup> כו' דאשה בעלה משמחה אחר הנשואין כו'. אבל לע\"ל נאמר אשת חיל עטרת בעלה<sup data-n=\"304\">304</sup> שיהי' מעלת הכלה למעלה מן החתן, ע\"כ א' בברכה האחרונה משמח חתן עם הכלה שהכלה עיקר, וכמ\"ש במ\"א בביאור זה באריכות<sup data-n=\"305\">305</sup> וד\"ל.",[["302","302","<b>מקדם מקדמונו של עולם</b>: ראה לעיל סוף אות כ'."],["303","303","<b>ואל אישך</b>: בראשית ג, טז."],["304","304","<b>אשת חיל עט\"ב</b>: משלי יב, ד."],["305","305","<b>משמח חתן עם הכלה. . במ\"א בביאור זה באריכות</b>: ראה לעיל ח\"א ע' כד [ובהמ\"מ שם נסמן לכמה מקומות]. ולהלן ד\"ה שמח תשמח השני (סוף אות ח'). ד\"ה משמח חתן וכלה. ד\"ה להבין שבברכה ראשונה (בתחילתו). ד\"ה אשר ברא (סוף אות ג')."]]],[1900420086,"<h3>שמח תשמח כו' ומסיים משמח חו\"כ</h3>\n<b>שמח</b> תשמח<sup data-n=\"306\">1</sup> ריעים האהובים כו' ומסיים משמח חתן וכלה, ויש להבין מה שייכות יש לשמחת חתן וכלה במה ששמח ישמח לריעים האהובים תחלה, ומהו כשמחך יצירך בג\"ע מקדם דוקא כו'. והנה בברכה זו מדבר בשמחת חתן ואח\"כ כלה כמ\"ש משמח חתן וכלה כו', ויש להבין דבשלמא לשמח את הכלה נצרך שתוכל לעלות להתייחד כו' כנ\"ל בענין הריקוד שמרקדין לפני הכלה<sup data-n=\"307\">2</sup>, ועוד מפני שהולכת מבית אבי' ואמה לדור עם בעלה כו', אבל למה צריך לשמח את החתן כו'. אך הענין הוא משום דכתיב ע\"כ יעזוב איש<sup data-n=\"308\">3</sup> את אביו ואת אמו ודבק באשתו והיו לבשר א', והטעם דע\"כ יעזוב הוא ממה שקדם שקרא לה אשה כי מאיש לוקחה זאת כו', וי\"ל דבשלמא באדה\"ר שבנין חוה הי' א' מצלעותיו כמ\"ש זאת הפעם עצם מעצמי ובשר מבשרי לזאת יקרא אשה כי מאיש כו' ע\"כ דבק באשתו, אבל בדור שאחריו למה יעזוב איש את אביו ואמו ודבק באשתו כו', ואם זה בא בטבע שיעזוב איש כו' למה צריך לשמח את החתן שיעזוב אביו ואמו כו'.\n<b>אך</b> הנה ידוע שרש ענין אב ואם שהן בחי' חו\"ב שהן המולידים את המדות שנק' איש, ואין למדות קיום ומציאות רק ע\"י השכל והשגה שמחמתו מתפעל ואם יסתלק השכל וההשגה מיד יבוטל התפעלות המדות, כמו שנראה בחוש בעבודה שבלב בתפלה שיתפעל בלב מחמת ההתבוננות ובהסתלקות ההתבוננות יפול מהתפעלות הלב לגמרי כו' וצריך לייגע א\"ע מחדש להתבונן כו', וכך הוא במילי דעלמא כידוע שאין התפעלות הלב בלא התבוננות במוח תחלה. אך הנה אנו רואי' שכאשר באה ההתפעלות שבלב בקול ודבור שבפה שיוצא מקירות הלב הנה נעשה התפעלות הלב בחי' משפיע לקול הדבור שידבר בקול רעש בהתלהבות והתפשטות כו' ואז התפעלות המדות שבלב נפרדין מן השכל והשגה שבמוח שמחמתה נתפעל והי' בחי' מקבל ממנו עד שנעשה השכל וההשגה בקיצור והסתלקות לגמרי וא\"א לו שיהי' אז שכלו ודעתו בהרחבת ההתבוננות מפני שלבו בא להתדבק באותיות הדיבור וקול ונדבק ונמשך להשפיע בדיבור בהתלהבות שמחמת זה מוכרח לסלק ולעזוב את השכל וההשגה ולקוצרו בתכלית, וכנראה בחוש בכל מי שדבריו בתפלה יוצאי' בהתפעלות הלב ביותר תסתלק ממנו השכל והשגה אלקי' לגמרי כו'.",[["306","1","<b>שמח תשמח</b>: מכאן עד ס\"ט — מיוסד על ד\"ה שמח תשמח בסידור עם דא\"ח קלז, ב-ג [מאמר הסידור הוא משנת תקס\"ד על חתונת כ\"ק אדמו\"ר הצ\"צ, ראה סוף סה\"מ תקס\"ד ע' שדמ]. והתוכן גם לעיל ח\"א ע' רלד-רמא [בתוך קונטרס ברכת חתנים].\nוראה עוד ע\"ד המאמר ותאריך אמירתו, להלן בהוספות ברשימת הכתבי-יד. ולהלן בהמ\"מ ריש אות ט."],["307","2","<b>כנ\"ל בענין הריקוד שמרקדין לפני הכלה</b>: ראה ד\"ה שוש תשיש, לעיל ח\"א ע' של ואילך [ומקבילו בקונטרס ברכת חתנים שם ע' רנא ואילך], שם נת' בארוכה במארז\"ל כיצד מרקדין [וראה בהנסמן עוד על מארז\"ל זה שם בע' רנא]. וראה להלן בהוספות ברשימת הכת\"י למאמר זה."],["308","3","<b>ע\"כ יעזוב איש</b>: בראשית ב, כד."]]],[1900420087,"ב) <b>וזהו</b> ענין ע\"כ יעזוב איש שהן המדות שבלב את אביו ואמו בחי' חו\"ב שבמוח המולידים אותו עד שנסתלקו לגמרי ודבק באשתו שהוא כלי הקול ודיבור שמשפיע להן דהיינו מפני שצריך לידבק באשתו שהוא בחי' הדיבור וחושק בה יותר משיהי' בחי' מקבל מאו\"א שהן בחי' המוחין שבראש כו'. ולהיפך כאשר רוצה לידבק בשכל והשגה שבמוח בהרחבה ולהיות מתפעל בזה בלב אז הלב נמשך ונדבק אחר השכל והשגה בעומק ומוכרח לעזוב את הקול ודיבור שלא יומשך מן הלב לקול ודיבור בהתפעלות ורעש אלא ידבר בחשאי (וזהו ב' מיני עבודה שבלב, א' ההעמקה וההתקשרות בשכל והשגה אלקי' בהרחבה והתפשטו' שהלב עולה אל השכל וממילא יהי' דבריו בחשאי וממילא כו', והב' אחר ההתבוננות שממנה נולד ההתפעלות שנמשך התפעלות הלב בדיבור דוקא שאז נסתלק השכל ונתקצר), והן ב' הפכים שא\"א שיהיו שניהם כא' ברוחב ההשגה ובהרמת קול ודיבור שיוצא מן הלב שהרמת קול בהתפעלות הלב בלבול השכל הוא והרחבת ההשגה ימנע הקול ודיבור (וכמו שרואי' בחוש במי שטרוד בעיון שכל ימעיט הדיבור ומי שמרחיב הדיבור בהתפעלות יסתלק הרחבת השכל כו', וגם בחכמי' שמלמדי' חכ' דבריהם בנחת דוקא ולא בקול רם מטעם זה וד\"ל. ואעפ\"י ששרש צירופי האותיות הוא מבחי' החכ' דוקא שאבא יסד ברתא<sup data-n=\"309\">4</sup> כידוע, היינו רק שרש<sup data-n=\"310\">5</sup>* הצירופים שמאליהם נעשה ממקור החכ', אבל קול הדיבור בא מהבל הלב דוקא שכבר נתפעל מהשכל ומבלבל הוא את השכל כו'). וזהו ע\"כ יעזוב איש את אביו ואמו שהן המוחין אז ודבק באשתו שהוא קול הדיבור כו' ואם אינו עוזב או\"א לא יוכל לדבק באשתו שהוא הדיבור (ואעפ\"י שהדיבור שהוא בחי' המל' ג\"כ נבנה מאו\"א כמ\"ש ויבן ה' אלקי'<sup data-n=\"311\">6</sup> את הצלע כו' וכמאמר והתקין לו ממנו כו' לפי שבנין המל' עצם מעצמי כו' לזאת יקרא אשה כי מאיש לוקחה זאת כמו שהדיבור נמשך מהבל הלב דוקא ע\"כ יעזוב או\"א הבונים לדיבור ודבק כו'), וזה פלא גדול למה יעזוב או\"א כו' ולא יהי' אור השכל וההשגה בשלימות בשעה שמדבר בהתפעלות הלב (וכמ\"כ למעלה בחי' המוחין דאו\"א שבמדות דז\"א דאצילות מסתלקים בשעה שנמשך ומשפיע לקול ודיבור די' מאמרות מטעם זה דבחי' המל' עצם מעצמי כו' כי מאיש לוקחה זאת מבחי' הבל הלב העליון כו' ע\"כ יעזוב איש העליון או\"א דאצי' ודבק כו' כידוע שזהו בחי' יחוד דזו\"נ דאצי' שנק' איש ואשה למעלה כו').\nג) <b>אך</b> הנה יש עצה לזה שלא יבלבל הקול ודיבור כלל את השכל והכוונה שבמוח אלא אדרבה יוכל להיות כל אמיתית הכוונה והשכל האלקי' שבמוח בכל פרטי קול הדיבור עד שלא יהי' אף קול ודיבור א' בלתי כוונה",[["309","4","<b>שאבא יסד ברתא</b>: זח\"ג רמח, א. רנו, ב. רנח, א. תקוני זהר תכ\"א (סא, ב). תס\"ט (קה, ב)."],["310","5","<b>שרש</b>: בכת\"י ב: סדר."],["311","6","<b>ויבן ה' אלקים</b>: בראשית ב, כב. ראה להלן אות ז' בתחילתו."]]],[1900420088,"שכלי' שמלובש בה. ויש בזה ב' תנאים, הא' כאשר לא יהי' השכל והשגה האלקי' בחיצוני' לבד שנק' חיצוני' בינה אלא בבחי' פנימי' בינה דוקא. וביאור הענין ידוע בענין הבן בחכ' וחכם בבינה<sup data-n=\"312\">7</sup> כו' שבחי' חיצוני' דבינה הוא ענין הבנת והשגת השכל שנק' התבוננות בהסבר דברים עפ\"י משלים וכה\"ג שמזה יולד ההתפעלות בלב שאז ודאי א\"א שיהי' השגה הזאת בהרחבה כאשר יתפעל בלב ויומשך מהבל הלב בקול הדיבור לפי שכבר נתקצר הרחב ההשגה מיד בבוא ההתפעלות בלב (דיסוד אימא הוא מסתיים בחזה דז\"א<sup data-n=\"313\">8</sup>) וגם קול הדיבור מבלבל כנ\"ל, אבל בחי' פנימי' בינה שנק' עומק המושג ותמציתו לאחר ההסבר שז\"ש וחכם בבינה הוא שמאיר דוקא בלב יותר ונק' בינה לבא ובה הלב מבין וכמ\"ש במ\"א ונק' כונה שבלב (בל\"א ער דער הערט דעם שכל אין הארץ כו'), אז ודאי יאיר פנימי' הלב בקול ודיבור בכל פרט ופרט, וכמו שנראה בחוש בקול הניגון ושיר שיוצא מהבל הלב לדיבור שהוא לפי אופן הכונה שבלב מבחי' תמצי' ההשגה שהי' במוח בינה באריכו' (וכשיר הלוים וכה\"ג בשיר המלאכים כו') וכמ\"ש לבי ובשרי ירננו כו' וחסידך ירננו<sup data-n=\"314\">9</sup> וכה\"ג בקול הדיבור אין זה מבלבל אדרבה מגלה כל עומק התפעלות שכליי' שבלב שנק' שיעור בלב כמ\"ש נודע בשערים בכאו\"א לפום מה דמשער<sup data-n=\"315\">10</sup> בליבי' דוקא, שזהו ענין הלב שומע וכן הלב רואה ראיי' עין השכל שהוא בחי' עומק חכ' שהוא בבחי' ראי' כידוע בענין ראי' ושמיעה שהן בחו\"ב שבלב דוקא כמ\"ש במ\"א ע\"פ ממעמקים עומק חו\"ב שבלב דוקא וד\"ל.\nד) <b>והתנאי</b> הב' הוא בחי' התענוג והשמחה שבהשגה והתבוננות האלקי' שישמח ויתענג מאד באותה ההשגה האלקי' ולא תהי' בחיצוני', דאם ההשגה היא רק בדרך מח' עיוני' בעיון השכל באיזה דבר חכ' אז כשיבא לכלל דיבור בקול יבוטל כנ\"ל אלא ידבר בחשאי כנ\"ל, אבל כאשר התפעלות התענוג ושמחה בהשגה אלקי' אז יבא מן הלב לקול הדיבור ג\"כ בשמחה ותענוג ממילא מכוון דוקא לפי ענין ההשגה ולא יבלבל כלל את הכונה שבמוח כמו שהיא (וכמ\"ש לבי ובשרי ירננו כו' וכשיר הלוים שהי' בהתפעלות שמחה ותענוג גדול), ואין השכל והשגה מתקצר כלל אדרבה מתפשט ומתגלה ביותר (והוא בחי' התגלות ע\"י בבינה בשיר הלוים כמ\"ש ועבד הלוי הוא כמ\"ש",[["312","7","<b>הבן בחכ' וחכם בבינה</b>: ס' יצירה פ\"א מ\"ד. וראה לעיל ח\"א ע' טל. ס' מאמרי אדהאמ\"צ במדבר ח\"ה ע' א'תשנ, ובהמ\"מ שם."],["313","8","<b>דיסוד אימא הוא מסתיים בחזה דז\"א</b>: ראה ע\"ח שער לידת המוחין (שכ\"א) פ\"ג. שער הנסירה (שכ\"ט) פ\"ח. שער פרצופי זו\"נ (של\"א) ספ\"ג. שער לאה ורחל (של\"ח) פ\"ב. סידור קפז, ד. פיה\"מ לאדהאמ\"צ פס\"ח. תו\"ח וארא ס\"ע קג ואילך."],["314","9","<b>לבי ובשרי. . וחסידך ירננו</b>: תהלים פד, ג. קלב, ט."],["315","10","<b>נודע בשערים. . דמשער בלבי'</b>: משלי לא, כג. זח\"א קג, א."]]],[1900420089,"במ\"א<sup data-n=\"316\">11</sup>), והטעם הוא לפי שכאשר יבא העונג והשמחה בהשגה והתבוננות הנה טבע השמחה להוציא מן ההעלם לגילוי, כידוע שכאשר ישמח אדם אז יגלה כל מצפוניו, ע\"כ ע\"י השמחה והתענוג בהשגה תצא כל בחי' ההעלם שבה לגילוי דוקא והוא בחי' פנימי' ותמצי' המושג שלא יכיל כלי מוחו להשיג בהסבר משלים וכה\"ג, וכמ\"כ בראי' עין השכל דחכ' ג\"כ יתגלה מן בחי' ההעלם דחכ' יותר מכמו שהוא במוח החכ' עצמה מטעם הידוע שבחי' התענוג והשמחה הוא בעצמות הנפש דבחי' יחידה שלמעלה ממקור החו\"ב (וזהו מ\"ם דממעמקים שכולל ב' עומקים דחו\"ב כמ\"ש במ\"א<sup data-n=\"317\">12</sup>), ואז אף שנסתלקו מוחין דחו\"ב בהגיע ההתפעלות ללב כנ\"ל חוזרים ונגלים ביתר שאת ותמציתם ועומקם הנעלם בא לגילוי ע\"י השמחה בשיר וניגון (וזהו שנק' שיר פשוט שממנו נמצא שיר כפול<sup data-n=\"318\">13</sup> דחו\"ב כו'), ובלא עומק דחו\"ב אין השמחה בהשגה החיצוני' מועיל אדרבה יסתלק השכל יותר, כ\"א בעומק דחו\"ב בלב כנ\"ל ובשמחה ותענוג שהן ב' תנאים הללו אז יתגלה ויתחבר תמצי' הכונה שבחו\"ב הנעלם בכל פרט של קול הדיבור והיו לאחדים ממש כידוע לטועמים טעם ותענוג בהתבוננות בעומק ההשגה שבלב דוקא וד\"ל.\nה) <b>וז\"ש</b> כל הנהנה מסעודת חתן ואינו משמחו עובר בה' קולות (שנתנה התורה כמ\"ש וכל העם כו' וכתיב קול ה' על המים קול ה' בכח כו' וכמ\"ש במ\"א<sup data-n=\"319\">14</sup>), ולכאו' מה שייכות ה' קולות דתורה לענין שמחת החתן ומה צריך לשמח את החתן כו'. אך הנה ידוע במ\"ש ביום חתונתו זו מ\"ת<sup data-n=\"320\">15</sup> כו' שהקב\"ה נק' חתן וכנ\"י שקבלו התורה נק' כלה וכמ\"ש והוא כחתן<sup data-n=\"321\">16</sup> יוצא מחופתו כו' והוא בחי' השפעה דחכ' דתו\"מ בקול ודיבור לכנ\"י ביו\"ד הדברו' דאנכי כו' כמ\"ש וידבר אלקי'<sup data-n=\"322\">17</sup> כו', ושרש חכ' זאת דיו\"ד הדברות בחו\"ב שבעצמותו ית' הוא אך שיצא מן ההעלם לגילוי ממדות שבלב אדם העליון בקול ודיבור כו'. וזהו ענין ה' קולות כנגד ה' חסדים כמו קול ה' על המים בחי' המשכה דחסד וקול ה' בכח בבחי' גבורה וקול ה' בהדר בחי' ת\"ת כו', ומבואר למעלה שבחי' גילוי קול ודיבור מהבל הלב מוכרח שיהי' הסתלקות המוחין דחו\"ב שנמשך למדות כו', שזהו ע\"כ יעזוב איש או\"א כו', אך ע\"י בחי' השמחה והתענוג חוזרים לבא מבחי' ההעלם והתמצית לגילוי בכל פרט דקול ודיבור דוקא, אבל בלא שמחה ותענוג כאשר משיג בהשגת השכל בחיצוני' ונדבק בה",[["316","11","<b>ועבד הלוי הוא כמ\"ש במ\"א</b>: קרח יח, כג. ראה תו\"א יא, ב [ובהנסמן בהמ\"מ לתחילת המאמר שם]. לעיל ח\"א ע' רלט. ובכ\"מ."],["317","12","<b>מ\"ם דממעמקים. . כמ\"ש במ\"א</b>: ראה לעיל ח\"א ע' יו\"ד, ובהמ\"מ שם."],["318","13","<b>שיר פשוט. . שיר כפול</b>: ע\"פ זח\"ג רכז, ב. תקוני זוהר בהקדמה ג, א. וראה לעיל ח\"א ע' רנד. וש\"נ."],["319","14","<b>כל הנהנה מסעודת חתן. . וכל העם. . קול ה'. . וכמ\"ש במ\"א</b>: ברכות ו, ב. יתרו כ, יח. תהלים כט, ג ואילך. ראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תרפה [ובהנסמן שם בהמ\"מ בסוף העמוד]."],["320","15","<b>ביום חתונתו זו מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."],["321","16","<b>שהקב\"ה נק' חתן וכנ\"י. . כלה. . והוא כחתן</b>: תהלים יט, ו. ראה להלן ריש ד\"ה לה\"ע מה שבברכה ראשונה. וש\"נ."],["322","17","<b>וידבר אלקי'</b>: יתרו כ, א ואילך."]]],[1900420090,"אינו יכול להביא בקול ודיבור כו'. וכך הוא בענין לימוד התורה כשבאה בדיבור ע\"י שמחה ותענוג שבחכ' דתורה אז יתגלה מבחי' ההעלם ופנימי' שבה בקול ודיבור דוקא, וכמו שהי' במ\"ת שהי' גילוי ההעלם דתענוג ושמחה העליונה בכל דיבור וע\"כ על כל דיבור פרחה נשמתן<sup data-n=\"323\">18</sup> כו', וזהו קול ה' על המים כו', וע\"כ צריך עכשיו ללמוד בשמחה ותענוג כמ\"ש ר\"ש חדאי נפשאי<sup data-n=\"324\">19</sup> לך קראי כו' וכן אומר ונשמח בדברי תורתיך כי הם חיינו כו', ולכך א' כל הלומד בקול<sup data-n=\"325\">20</sup> לא במהרה שוכח כו', אבל כשלומד בלא שמחה ותענוג רק במח' בעיון השגת שכל לבד ממילא ידבר ד\"ת בחשאי ולא בקול הרי לא נגלה בזה הדיבור מבחי' הפנימי' וההעלם דחכ' דתורה כלל וגם לא מתחבר בקול ודיבור כלל כנ\"ל, וזהו חיים הם למוצאיהם בפה דוקא וכן א' כי לא על הלחם דתורה כו' כי על כל מוצא פי ה' דתורה יחי' האדם וכמ\"ש ודברי אשר שמתי<sup data-n=\"326\">21</sup> בפיך דוקא מטעם הנ\"ל, כמו שהי' במ\"ת דכתי' ביום חתונתו וביום שמחת לבו פי' ביום חתונתו שהוא ירידת השפע דאור תורה אך זה הי' בבחי' שמחת לבו שעי\"ז יצא מן ההעלם הפנימי בגילוי בקול ודיבור כנ\"ל וד\"ל.\nו) <b>וזהו</b> כל הנהנה מסעודת החתן ואינו משמחו עובר בה' קולות. דהנה בחי' המדות שבלב שמשפיעים לבחי' הדיבור וקול נק' חתן לשון נחות דרגא כו' ונק' איש כנ\"ל בפי' ע\"כ יעזוב איש את או\"א שהן המוחין חו\"ב המולידים אותו ודבק באשתו שהוא בחי' הדיבור מה שמדבק נפשו באותיות הדיבור בתפלה (דאשתו הוא בחי' היראה שהוא בדיבור דוקא, ועוזב או\"א שהוא השכל שמקבל ממנו התפעלות כי אין השכל והתפעלות האהבה עיקר אלא היראה שהוא באותיות הדיבור דוקא, וכמו המדבר לפני המלך בקשתו ושאלתו שמדבר בהכנעה וביטול באימה ויראה גדולה שזהו העיקר ולא מה שמתפעל בלבו ודעתו כו' כמ\"ש בש\"ע שא' אדני שפתי תפתח כו' כי אתה שומע תפלת כל פה דוקא). והנה כאשר בחי' המדות שבלב באים בהתפעלות השמחה ותענוג שבהשגה שבמוח אזי לא יעזוב לאו\"א שהן המוחין דחו\"ב אדרבה הן באים בגילוי ההעלם שבהן דוקא בקול ודיבור, אבל כאשר המדות שבלב הן בלא שמחה בהתבוננות אז לא יוכל לעזוב לאו\"א שהן המוחין המולידים התפעלות הלב שנדבק בהשגה שבמוח בינה להיות קיום מציאות התפעלות המדות שבלב ואז ממילא לא יוכל לבא בהשפעה בקול ודיבור ונעזב הקול ודיבור לגמרי, אבל ע\"י השמחה בהשגה חוזר להיות הקול ודיבור עפ\"י הכוונה שבשכל דוקא כנ\"ל. וזהו שכאשר אינו משמח את החתן שהוא בחי' מדות שבלב בשמחה",[["323","18","<b>על כל דיבור פרחה נשמתן</b>: ע\"פ שבת פח, ב."],["324","19","<b>ר\"ש </b>[רב ששת]<b> חדאי נפשאי</b>: פסחים סח, ב."],["325","20","<b>כל הלומד בקול</b>: ראה עירובין נד, א. וראה להלן אות כ\"א."],["326","21","<b>חיים הם למוצאיהם בפה. . כי לא על הלחם. . ודברי אשר שמתי</b>: ע\"פ עירובין עקב ח, ג. ישעי' נט, כא."]]],[1900420091,"ותענוג שבהשגה עובר בה' קולות, פי' עובר שעובר עליהן בדרך מעבר בעלמא מבלתי יוכל לדבק נפשו בקול ודיבור כלל וגם הוא פוגם בעצם הקול ודיבור שאינו נמשך בכונה שעפ\"י שכל והשגה האלקי' שבמוח כלל כי יצא הקול ודיבור מופרד מן השכל והשגה לגמרי אם לא שיעזוב לאו\"א שהן המוחין ויקצר ההשגה ושכל לגמרי וידבק רק בקול ודיבור שלא בכוונת השכל וע\"כ צריך שמחה לשמח את החתן ואם לאו עובר בה' קולות והן ה' קולות דתורה שנתנה ע\"י שמחה כנ\"ל בפי' ביום חתונתו וביום שמחת לבו דוקא וכשלומד בלא שמחה ותענוג שלא מתחבר בחי' הפנימי' בקול ודיבור, זהו שעובר על ה' קולות דמ\"ת וד\"ל.\nז) <b>אך</b> הנה עדיין יש להבין למה צריך לשמח את החתן כו', דמשמעות ענין וטעם שצריך לשמח את החתן הוא כדי שיוכל לעזוב את או\"א וידבק באשתו, ולפי כל הנ\"ל ע\"י השמחה אינו עוזב כלל לאו\"א שהן המוחין אדרבה יומשכו מהעלמם לגילוי בקול ודיבור בכל פרט דוקא כנ\"ל, ועוד בעיקר הענין מאחר שנתן טעם להיותה עצם מעצמי כו' ע\"כ ממילא יעזוב לאו\"א ודבק באשתו כו', א\"כ למה צריך לשמח אותו שיוכל לעזוב לאו\"א הרי מצד עצמו עוזב או\"א כו', ועוד למה יעזוב או\"א המולידים אותו בשביל אשתו אף שהיא א' מצלעותיו הלא נאמר ויבן ה' אלקי' את הצלע כו' דאו\"א תקינו לה<sup data-n=\"327\">22</sup> כו'. אך הנה כ\"ז יובן בהקדים ענין א', והוא מה שאנו רואי' שאחר שיתפעל האדם במדות שבלב מצד ההשגה שבמוח יבא לכלל התפעלות האהבה יתירה בהתלהבות ותענוג גדול שלמעלה מכפי ערך ההשגה וטעם שבמוח שהוליד האהבה כידוע שזהו מצד שרש המדות בעצמות הנפש דבחי' יחידה שלמעלה גם מן המדות שברצון ותענוג המורכב בשכל וטעם אלא כמו אה\"ר בתענוג הפשוט ממש (כמאמר דז\"א בע\"י אחיד ותלי' כו' וכמ\"ש במ\"א<sup data-n=\"328\">23</sup>). והנה אין זה בא כ\"א ע\"י בחי' שמחה שבעצמו' הנפש דוקא שנק' שמחת הנפש מצד עצמה, והוא ג\"כ בחי' התענוג הפשוט שבעצמו' ממש שטבע זאת השמחה לגלות כל העלם העצמות ממש שלמעלה מתענוג ורצון המורכב בחו\"ב כידוע ומבואר במ\"א. וממילא מובן ששמחה זו למעלה הרבה משמחה שבהשגה שבמוח הנ\"ל רק שע\"י שמחה שבהשגת שכל יתעורר בחי' שמחה העצמי' הזאת, וכנראה בחוש בכל עובד ה' בשמחה בהתבוננות שיבא אח\"כ לבחי' שמחת הנפש עצמה שבלא הרכבה כלל באיזה טעם ושכל, והוא הסיבה שאחר שיתפעל בלב בשמחה המצומצמת בהשגה שבמוח יבא לכלל התפעלות שמחה יתירה בלב באה\"ר בתענוג הפשוט בלתי מוגבלת כלל כנ\"ל ואז הוא בא לבחי' התפשטות הקול",[["327","22","<b>ויבן ה' אלקי'. . דאו\"א תקינו לה</b>: בראשית ב, כב. זח\"א מט, א."],["328","23","<b>דז\"א בע\"י אחיד ותלי' וכמ\"ש במ\"א</b>: זח\"ג רצב, א. ד\"ה רישא דז\"א בעתיקא — בס' מאמרי אדה\"ז-מרז\"ל ע' שכג. ס' מאמרי אדה\"ז-ענינים ע' תיז [ושם בהמ\"מ נסמן למקומות רבים בדא\"ח]. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רמא [ובהמ\"מ שם]. לעיל ח\"א ע' רכ."]]],[1900420092,"ודיבור בהרחבה גדולה שנק' קול גדול כו' שלא לפ\"ע השכל שבמוח כלל, וראי' לזה ממה שע\"י שמחת הלב ביותר מכפי המדה שבאה מבחי' שמחת הנפש עצמ' ימצא בדיבור התגלות אור החכ' ג\"כ ביתר מכפי כח חכמתו בעצם בהעלם (וכמו אגברו חמרא אדרדקי דלימרו מילתא כו', וכמו ר\"ז דהוה בדיחא דעתי' אמר דכל חללי דעלמא<sup data-n=\"329\">24</sup> כו'), וזהו משום שבינה יתירה<sup data-n=\"330\">25</sup> ניתנה באשה יותר מבאיש כו' וכן אמר דקול מעורר הכונה שבמוח ולב כו', א\"כ ודאי שיש שרש ומקור לקול ודיבור למעלה במקור דחו\"ב גם למעלה מרצון ותענוג המורכב בחו\"ב כו' דהיינו בעצמות הנפש ממש (שנק' רוח ממללא כמ\"ש במ\"א<sup data-n=\"331\">26</sup>). וזהו הטעם שאמר זאת הפעם עצם מעצמי כו' ששרש בחי' המל' שהוא הדיבור בעצמות המדות דבחי' יחידה הנ\"ל שלמעלה גם ממדות שברצון ותענוג כו' כנ\"ל וע\"כ יעזוב איש את או\"א שהן בחי' המוחין דחו\"ב (אפילו למקור דחו\"ב שנק' עומק חו\"ב כנ\"ל) ודבק באשתו שהוא התפשטות דקול ודיבור וד\"ל. וזהו הטעם שצריך לשמח את החתן שהוא בחי' המדות שבלב מבחי' שמחה העצמי' שבנפש כדי שיעזוב לאו\"א כי נתבטל שמחה דחו\"ב ממילא והי' כלא הי' לגבי שמחה העצמי' ודבק באשתו שהוא קול ודיבור להשפיע בהתפשטות גדולה מצד שמחת לבו שהיא בלתי מוגבלת כלל שאין חו\"ב מגיעים לשם כלל אפי' בחי' ההעלם שלהם (והוא בחי' שיר פשוט הנ\"ל).\nח) <b>ובזה</b> מתורץ גם הקושי' שני' דמצד עצמו עוזב לאו\"א כו' שאין זה רק ע\"י שמחת לבו הנ\"ל דוקא, וכמו שהי' במ\"ת דכתיב וירד הוי'<sup data-n=\"332\">27</sup> וידבר כו' לפי שהי' בבחי' שמחת לבו דוקא שלמעלה גם ממקור דחו\"ב שזהו כמו ענין ע\"כ יעזוב כו' שע\"י שמחה שבעצמו' ממש דוקא כנ\"ל, ועכשיו הוא לימוד התורה בקול ודיבור דוקא וכמ\"ש כי על כל מוצא<sup data-n=\"333\">28</sup> פי ה' כו' שהוא ע\"י שמחה שבעצמו' דוקא מטעם הנ\"ל (ואעפ\"י שחו\"ב נק' בונים לדיבור זהו רק לעשות הצירופים כו' אבל שרש עצם הדיבור הוא בעצמו' ממש ולכך יעזוב או\"א כו'). וזהו שמח תשמח ריעים האהובים שמח לדכורא ותשמח לנוק' דהיינו חו\"ב שנק' או\"א שיומשך בהן משמחה העצמי' שלמעלה משמחה ותענוג שבחו\"ב מצד עצמו, והוא מ\"ש כשמחך יצירך למדות דאדם בג\"ע מקדם למקור דחו\"ב כו' מטעם הנ\"ל, ואז לא יהי' המוחין דחו\"ב נעזבים בשביל השפעה לקול ודיבור עד שלא יהי' הקול ודיבור נפרד גם מן השכל אעפ\"י ששמחה דחו\"ב בטילה במציאות אבל מפני ששמח תשמח משמחה העליונה גם לאו\"א שנק' ריעים",[["329","24","<b>אגברו חמרא. . ר\"ז </b>[ר' זירא]<b>. . דכל חללי עלמא</b>: סנהדרין לח, א. שבת עז, ב. וראה לעיל ד\"ה שמח תשמח (הראשון) אות י\"ז, ובהמ\"מ שם."],["330","25","<b>שבינה יתירה. . שקול מעורר הכונה</b>: נדה מה, ב. ראה של\"ה פב, ב [ולעיל ח\"א ע' לט, ובהמ\"מ שם]."],["331","26","<b>רוח ממללא כמ\"ש במ\"א</b>: תרגום אונקלוס בראשית ב, ז. ראה ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תעו."],["332","27","<b>וירד הוי'</b>: יתרו יט, כ."],["333","28","<b>כי על כל מוצא</b>: עקב ח, ג."]]],[1900420093,"האהובים דלא מתפרשין כידוע ולפ\"ע זה דוקא יומשך שמחת חתן וכלה, וז\"ש משמח חתן ואח\"כ כלה שלא יהי' הקול נפרד מן השכל ולא יעזוב או\"א כו' אעפ\"י שמשמחים החתן כו' שיוכל לעזוב כו' (ודוגמא לזה מצינו ברב שמואל דרקיד אתלת<sup data-n=\"334\">29</sup> כו' והריקוד הוא למעלה מן הדעת ולא נפסק הדעת ממנו כלל וד\"ל). ולפי ששרש נשמות דדכר ונוק' מאדם וחוה ע\"כ גם עתה יעזוב איש כו' (ומה שבאשר ברא אמר משמח חתן עם הכלה שהכלה עיקר זהו לע\"ל דאשת חיל עטרת בעלה למעלה משמחה דריעים האהובים כו') כמ\"ש<sup data-n=\"335\">30</sup> בענין שוש תשיש).\nט) <b>ולהבין</b> בתוס' ביאור ענין המאמר דהנהנה מסעודת חתן<sup data-n=\"336\">31</sup> ואינו משמחו עובר בה' קולות ואם משמחו מה שכרו זוכה לתורה שנתנה בה' קולות כו', ובאמת יש להבין למה מצות שמחת חתן וכלה שאינו אלא מצות פו\"ר דחו\"כ גדולה יותר משאר המצות שצריך להיות בשמחה גדולה כ\"כ עד שהמצוה על שאר בנ\"א לשמחם, והלא כל המצות צ\"ל בשמחה כו' ומה נשתנה מצוה זאת דפו\"ר דחו\"כ יותר מכל המצות זולתה כו'. אך כללות הענין הוא לפי שיחוד וזיווג זה דנשמות דו\"נ דחו\"כ שהן בצלם אדם העליון ממש הרי בזה יש בחי' כללות כל יחודים עליונים שנעשים למעלה ע\"י תו\"מ בפרטיות שהן רמ\"ח אברים כו', ע\"כ מצות שמחת חו\"כ למטה הוא ממש כמו למעלה ביחוד חו\"כ העליון שהוא יחוד זו\"נ דאצי' כידוע (וע\"כ מצות הכנסת כלה פוטרת גם מצות עשה דק\"ש דאורייתא כמ\"ש בעובדא דר\"י ורבי יהודא שהבין הינוקא<sup data-n=\"337\">32</sup> בריחא דלבושייהו שלא קרו ק\"ש לפי שעסקו במצות הכנסת כלה). וזהו הטעם שמצות שמחת חו\"כ למעלה מכל שמחה של מצוה בפרט, ולזה א' דמשמחו זוכה לתורה שנתנה בה' קולות שזהו כמו במ\"ת דכתי' ביום חתונתו כו' כידוע וד\"ל.\nי) <b>ולהבין</b> זה צריך להקדים עיקר ענין ההפרש בין נשמות למלאכים, שהנשמות הן בבחי' אדם בצלם אלקי' ממש וע\"כ יש בהן כח המוליד ביחוד דו\"נ להוליד בדומה להם נפש שכליי' חדשה מאין ליש משא\"כ במלאכים (כמשי\"ת). וביאור הענין, הנה אנו רואין ב' דברים שיש בנשמות מה שאין במלאכים, הא' יתרון מעלה שבמלאכים יותר מבנשמות מה שחומר וכלי",[["334","29","<b>ברב שמואל דרקיד אתלת</b>: כתובות יז, א."],["335","30","<b>שבאשר ברא. . עם הכלה. . כמ\"ש </b>[בכת\"י ב נוסף: במ\"א]<b> בענין שוש תשיש</b>: ראה בכ\"ז לעיל ח\"א ע' שדמ ואילך [שם הד\"ה הוא ”שוש תשיש\". וראה בהנסמן לעיל קרוב לתחילת המאמר]. וראה גם שם ע' כד [ובהמ\"מ שם]. קעח. רכ ואילך. רלא ואילך. שטו."],["336","31","<b>ט) ולהבין בתוס' ביאור ענין המאמר דהנהנה מסעודת חתן</b>: מכאן מיוסד על ד\"ה כל הנהנה בסה\"מ תקס\"ה ח\"א ע' מג. ונמצא גם תוכן המאמר בשינויים לעיל ח\"א ע' רמא-רנ [בתוך קונטרס ברכת חתנים]. ובד\"ה כל הנהנה תרמ\"ב (קונטרס דרושי חתונה, קה\"ת תשמ\"א)."],["337","32","<b>בעובדא דר\"י ורבי יהודא שהבין הינוקא</b>: זח\"ג קפו, א: רבי יצחק ורבי יהודה הוו אזלי כו'. וראה גם ס' מאמרי אדה\"ז הקצרים ע' רסה. ולעיל ח\"א ע' קה. וש\"נ."]]],[1900420094,"שלהם דק ורוחני הרבה יותר מחומר וגוף של הנשמות, והב' יתרון מעלה שבנשמות ממלאכים מה שיש בהן כח המוליד כנ\"ל שאין זה במלאכים, והא בהא תלי'. דהנה חומר וכלי של המלאכים הוא מבחי' הרכבה רוחניי' מאד מבחי' רוחניו' דיסודות דאש ורוח מורכבים יחד כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט וכמ\"ש הרמב\"ן<sup data-n=\"338\">33</sup> דאין ההרכבה בחומר וגוף המלאכים ממים ועפר כלל רק מרוח ואש (ואעפ\"י שנאמר והמים אשר מעל השמים<sup data-n=\"339\">34</sup> יהללו כו', אין המים גשמיי' כלל ולא כמו יסוד המים הרוחני אלא הן בחי' מים עליונים הרוחניי' ביותר מן האור<sup data-n=\"340\">35</sup>* הזך בתכלית, כמ\"ש במ\"א בענין יהי רקיע<sup data-n=\"341\">36</sup> בתוך המים, אך גלגל המזלות שקבועים ברקיע הרי הרקיע שנק' שמים מורכב מאש ומים דוקא, וכידוע בענין אמ\"ר אור* מים רקיע<sup data-n=\"342\">37</sup> כו'), וגם בירידת המלאכים שנק' חיות הקודש בהתלבשות למטה בלבושים גשמיי' בעוה\"ז השפל בד'<sup data-n=\"343\">38</sup> יסודות גשמיי' עכ\"ז אינם נראים בהגשמת דבר כמו בגוף גשמי כמלאך שראו מנוח והגר ואמנם אין זה רק למראית עין האדם לבד שהרי עולה המלאך בלהב העולה כו' וכלבוש זר ממש נחשב להם ויכולים לפושטו בקל כו', וכש\"כ כאשר אינם מתלבשים כלל בלבושים הגשמיי' שאז כל הגשמת העולם אינו תופס מקום כלל וכלל, וכמ\"כ גם לאחר שמתלבשים שהרי א' מיכאל בא' פי' ששט כל שטח עוה\"ז בשיטה ופריחה א' לבד כי אין נתפס חומריות היסודות דעוה\"ז כלל בבחי' דבר מה עד ששט את העולם בפריחה א', וגבריאל בשתיים שהוא למטה מעט במדריגה וקרוב יותר ביחוס וערך לרוחניות דד\"י עד שאינו נחשב כמו לבוש זר כ\"כ עד שנתפס מעט יותר במקום ושטח בעוה\"ז שיצטרך לשוט העולם בב' פריחות, ואליהו שהי' גופו מד\"י גשמיי' רק שהי' מזוכך ביותר כמלאך ואמנם יש לו חיבור וערך יותר לרוחניות דד\"י ע\"כ הוצרך לפרוח בד' פריחות כי נתפס יותר בגדר וסוג זה העולם אעפ\"י שרוח ה' נשאו ממקום למקום. והנה יהי' איך שיהי' הרי עכ\"פ חומר וכלי הגוף דמלאכים דק ורוחני מאד כי החומר קרוב בערך מעין<sup data-n=\"344\">39</sup>* הצורה שהוא בחי' הנפש שבו אפי' גלגל השמש או הירח חומרם דק ורוחני ואם הם מורכבים מאש ורוח אבל הם",[["338","33","<b>עושה מלאכיו רוחות. . וכמ\"ש הרמב\"ן</b>: תהלים קד, ד. ראה גם תו\"א ד, ב. לקו\"ת ברכה צח, א. ובסידור ערה, ד — בשם ”ספר הגמול\" להרמב\"ן. וראה לקוטי שיחות ח\"ט ע' 405."],["339","34","<b>והמים אשר מעל השמים</b>: תהלים קמח, ד-ה."],["340","35","<b>האור</b>: בכת\"י ב: האויר."],["341","36","<b>במ\"א בענין יהי רקיע</b>: ראה ס' מאמרי אדהאמ\"צ בראשית ע' קב [שם כנראה הנחה ממאמר אדהאמ\"צ ולא לשונו ממש]: וכמו שהשכילו חכמי התכונה שאיך שייך להיות מים גשמיים מעל השמים כמ\"ש והמים אשר מעל השמים שהוא המים העליונים אלא מוכרח להיות שהמים המה רוחני' כו'. ובהמ\"מ שם נסמן לרד\"ק תהלים קמח, ד. מו\"נ ח\"ב פ\"ל. אלשיך בראשית א, ב. וראה גם לעיל ח\"א ס\"ע רמז ובהמ\"מ שם."],["342","37","<b>וכידוע בענין אמ\"ר אור </b>[בכת\"י ב: אש]<b> מים רקיע</b>: ראה זח\"ב קסז, א ואילך. שם קלו, ב. ע\"ח שער המלכים (שי\"א) פ\"ו. אוה\"ת חיי\"ש (כרך ד') תשפח, ב. ובהנסמן עוד בס' הערכים-חב\"ד כרך ג' ע' תא ואילך. וראה להלן אות י\"ז."],["343","38","<b>מיכאל בא'. . ואליהו. . בד'</b>: ברכות ד, ב."],["344","39","<b>מעין</b>: בכת\"י ב ליתא."]]],[1900420095,"בחי' הרוחניו' וקרובים בערך לצורה שבהם שהוא בחי' ההשגה באלקי' שאומרים שירה ומשתחווים מיד בסיבובם כמ\"ש וצבא השמים לך משתחווים כו', וכן באופנים הרוחניי' יותר א' כי רוח החי'<sup data-n=\"345\">40</sup> באופני' לא יסבו בלכתם אל מקום כו' וד\"ל. אבל הנה חומר גוף האדם שמורכב מד\"י גשמיי' הוא חומר גס ביותר אעפ\"י שנפש האדם היא רוחניי' אין החומר בערך עם הצורה כלל וא\"א לשום מלאך גם היותר תחתון במדריגה להתלבש בלבוש גס כ\"כ כחומר גוף האדם (והמלאכים כעז\"א<sup data-n=\"346\">41</sup> כו' שהורידו אותם בגופים חומריי' הן הנפילים שנתגשמו ביותר כידוע), וכש\"כ מלאך עליון, אבל נפש האדם להיות שרשו עליון יותר מן המלאכים ע\"כ יש ביכולתם לירד כ\"כ למטה ממדריגה למדריגה להתלבש בחומר גופני הגס כ\"כ ולהאיר גם בגוף החומרי מאור העליון האלקי בבחי' ביטול היש וגסות כו', וראי' מן התפעלות אלקות בלב בשר ותשובה אמיתית בלב נשבר כו' וד\"ל.\nיא) <b>והנה</b> הגם שבדבר זה מעלת המלאכים למעלה מן האדם, אבל בדבר הב' מעלת הנשמות גדולה הרבה מן המלאכים, והוא מה שיש בנשמות כח המוליד כנ\"ל. דהנה אנו רואים שאין במלאכים כח המוליד כלל, שהרי לא נתהוה מלאך ממלאך העליון ממנו בדרך תולדה כלל רק שבא האור ושפע מעליון לתחתון בבחי' השתלשלות דעו\"ע לבד, וכמו וקרא זא\"ז<sup data-n=\"347\">42</sup> ותרגומו ומקבלין דין מן דין כו', דהיינו שבחי' האור ושפע האלקי עובר ויורד בהשתלשלות מעילה לעילה בריבוי רבבות מדריגות שונות כידוע, אבל לא שנתהווה מהותם ומציאותם מעליון לתחתון שזהו אין מקבלים דין מן דין כלל, רק בבחי' שפע אלקי הוא ששייך לשון קבלה כו', אלא כאו\"א יש לו מקור מיוחד בפ\"ע בבחי' כח אלקי המהוה אותם מאין ליש שהוא כח אלקי מיוחד בפ\"ע מפרטי הכלים דע\"ס דבריאה או דיצירה או ועשי', כמו מחנה מיכאל בבחי' החסד שמתהווה מכח האלקי שבבחי' חסד דמל' דבריאה או יצירה, ויש בזה ע\"ס בפרט וכלול מכמה מדריגות דבחי' הכלים מכלים שונים וכ\"א משפיע להיות התהוות מלאך בפרט, והן ק\"פ אלף מלאכים<sup data-n=\"348\">43</sup> מסט' דחסד והיינו מחנה מיכאל וכה\"ג מחנה גבריאל מבחי' גבורה שבמל' דבריאה או דיצירה כידוע, ועכ\"ז מקבלין דין מן דין מעילה לעלול שהוא מפני בחי' ריבוי ההשתלשלות דע\"ס דמל' בכלים מכלים שונים פנימי ואמצעי וחיצון וכלים פנימי' שלמטה מקבלי' מחיצוניו' הכלים דעליון, כמו ג' מיני אותיות דמחדו\"מ שמחיצוני' כלים דאותיו' המח' נעשה פנימי' לכלים שבדיבור וכן מדיבור לעשי', שבכלל",[["345","40","<b>וצבא השמים. . כי רוח החי'</b>: נחמי' ט, ו. יחזקאל א, כ-כא."],["346","41","<b>והמלאכים כעז\"א</b>: ראה זח\"א לז, א: עזא ועזאל כד נפלו כו'. מאדהאמ\"צ ויקרא ח\"ב ע' תקלה. וש\"נ."],["347","42","<b>וקרא זא\"ז</b>: ישעי' ו, ג."],["348","43","<b>ק\"פ אלף מלאכים</b>: כ\"ה בכ\"מ (סידור רלו, א. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רכד. סה\"מ ה'ש\"ת ע' 40. ועוד). ובהערת כ\"ק אדמו\"ר שליט\"א (בסה\"מ ה'ש\"ת): ”כנראה הוא ע\"פ מ\"ש בזוהר (ח\"ג קנד, א. קנה, א) וא\"כ צ\"ל כאן: קפ\"ו אלף. ולא קפיד להעתיק גם מספר המאות שבזוהר שם\"."]]],[1900420096,"הן ג' מדריגות דמלאכים דבי\"ע משרפים לחיות וחיות לאופנים ומאופנים למזלות כו', וכאו\"א יש לו שרש אות וכלי מיוחד בבחי' הכלים דע\"ס דבי\"ע שכללותם הן ג' מדריגות דמחדו\"מ כידוע וד\"ל. אבל הנשמות אעפ\"י שהן באים ג\"כ בהשתלשלות דע\"ס דבי\"ע כמ\"ש בראתיו יצרתיו אף עשיתיו<sup data-n=\"349\">44</sup>, אבל שרשם מפנימי' ועצמיו' דאורות דע\"ס דבי\"ע בבחי' יחוד הפנימי דחו\"ב וזו\"נ שבכל עולם שמולידים נשמות ביחודם בצלם אדם דבי\"ע כו', וע\"כ גם הנשמות יש בהם כח המוליד ביחוד דו\"נ שלהם שיולידו בדומה להם שאין זה במלאכים כלל כנ\"ל, וכמו שנראה בחוש בנפש האדם שיוליד בדומה לו נפש חדשה ממש שבאה מבחי' אין ממש (ואעפ\"י שגם בבהמות וחיות ועופות יש כח המוליד להוליד למיניהם דוקא וכמו והעוף ירב בארץ<sup data-n=\"350\">45</sup> והמלאכים נק' בשם בהמות וחיות ועופות כפני ארי' ופני שור ופני נשר ויש בהם בחי' דו\"נ כפרה ושור כו', אבל אין זה בבחי' תולדה דאדם בבחי' חכ' דבחי' מדבר שהוא בצלם אדם העליון ממש שזהו רק בנשמות ולא במלאכים אעפ\"י שנא' ודמות פניהם פני אדם זהו רק בבחי' אנפי זוטרי (וכמ\"ש במ\"א ע\"פ ויצר<sup data-n=\"351\">46</sup> ה' את האדם כו').\nיב) <b>והנה</b> טעם ענין ההפרש בין נשמות למלאכים בב' דברים הנ\"ל ענין אחד הוא והא בהא תליא, והוא מצד מקור ושרש הנשמות והמלאכים, ששרש המלאכים גם באצי' אינו רק מבחי' חיצוני' החכ' שבאה בדיבור בי' מאמרות לבד כמ\"ש כולם בחכ' עשית, וכידוע במ\"ש בראשית ברא בחוכמתא<sup data-n=\"352\">47</sup> כו' שזהו בחי' יש שבחכ' כו', אבל שרש הנשמות הוא מפנימיו' ועצמיו' דחכ' כמו שהוא בבחי' אין ממש וכמו והחכ' מאין תמצא<sup data-n=\"353\">48</sup> כו' ששם הוא בחי' גילוי אא\"ס ממש, וזהו הנק' בחי' אד\"ם אדמה לעליון ממש כמ\"ש ויברא כו' את האדם בצלמו<sup data-n=\"354\">49</sup> כו', מפני שנשמת האדם שרשה בעצמו' א\"ס ב\"ה ממש וכמ\"ש ישראל עלה במח'<sup data-n=\"355\">50</sup> וכן אנו אומרים ואתה נפחת בי כו', וגם בכל פרט ופרט דכל ניצוץ קטן שבישראל כמו באדה\"ר שהי' כללות כל הנשמות<sup data-n=\"356\">51</sup> דכתיב בי' ויפח",[["349","44","<b>בראתיו יצרתיו אף עשיתיו</b>: ישעי' מג, ז."],["350","45","<b>והעוף ירב בארץ</b>: בראשית א, כב."],["351","46","<b>ודמות פניהם פני אדם. . אנפי זוטרי. . במ\"א ע\"פ ויצר</b>: יחזקאל א, יד. חגיגה יג, ב [שם: אפי. ובזח\"ג ריז, ב: אנפי]. ראה תו\"ח בראשית כה, ב ואילך. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תב וע' תתלט. דברים ח\"ג ע' תתקא."],["352","47","<b>כולם בחכ' עשית. . בראשית ברא בחוכמתא</b>: תהלים קד, כד. ת\"י ר\"פ בראשית."],["353","48","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["354","49","<b>אד\"ם אדמה לעליון ממש. . האדם בצלמו</b>: ע\"פ ישעי' יד, יד: אדמה לעליון [ובהנסמן ע\"ז בארוכה במ\"מ בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' קמ]. בראשית א, כז."],["355","50","<b>ישראל עלה במח'</b>: ב\"ר פ\"א, ד."],["356","51","<b>באדה\"ר שהי' כללות כל הנשמות</b>: שער המצות להאריז\"ל פ' תצא. אגה\"ק ס\"ז (תניא קיא, ב). לקו\"ת נצבים מז, א. ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתיא. ובכ\"מ."]]],[1900420097,"באפיו נשמת חיים ומאן דנפח כו' שלא הי' זה הניפוח ע\"י בחי' ממוצעים כלל (כמ\"ש במ\"א עמ\"ש והאלקים עשה את האדם ישר<sup data-n=\"357\">52</sup> כו').\n<b>ולהבין</b> ביאור הדברים, הנה ידוע שיש ב' מדריגות בהשתלשלות א' הנק' יש מיש והב' הנק' יש מאין. ויובן זה בנפש האדם כאשר יומשך מחכ' לבינה הרי בחי' נקודת המושכל דחכ' הוא שנמשך לבא בהתפשטות בהשגה והסבר לאורך ורוחב בבינה כמעיין הנובע ונמשך ממנו הנהר זהו הנק' יש מיש שאין כל חדש בעיקר מציאת ההשגה דבינה שכבר היתה כלולה בנקודה דחכ' רק שיצאה מן ההעלם לגילוי לבד כנהר שיוצא מן המעיין כו' (הגם שהחכ' נק' אין ובינה יש כידוע<sup data-n=\"358\">53</sup> א\"כ זהו מאין ליש ולא מיש ליש, זהו בבחי' מקור דחכ' כמו שהיא נמצאת מבחי' אין כמשי\"ת, אבל מה שנמשך מחכ' לבינה זהו בחי' יש דחכ' כאשר היא במציאות חכ' עכ\"פ וא\"כ מחכ' לבינה נק' יש מיש רק שלגבי השגה דבינה נק' גם נקודה דחכ' בבחי' אין, ומזה הטעם כל השתלשלות העולמות שמקורם הראשון הוא בחכ' כנ\"ל נק' גם הבריאה מאין ליש ובאמת זהו רק יש מיש דחכ' וד\"ל), וכמו\"כ מן השכל למדות אין כל חדש בהתפעלות המדות שמתהווה מהתפעלות השכל ונק' יש מיש (אעפ\"י שהתפעלות השכל הוא בבחי' אין והעלם במדות כנ\"ל בחו\"ב), וכן ממדות למח' שמן התפעלות המדות תתפעל המח' ונק' יש מיש, וכן התפעלות המח' בדיבור כו' עד שכל אות ואות מן הדיבור אין כל חדש בו בעיקר מציאותו שכבר הי' בנקודה דחכ' שמאיר לבינה כו'. אבל מדריגה הב' שנק' יש מאין ממש הוא ענין התהוות החכ' עצמה מלמעלה מן החכ' כמ\"ש והחכ' מאין כו' שלא יש ערך כלל להיות מציאות התהוות שכל וחכ' לגבי עצמו' הנפש שלמעלה מן השכל לגמרי אלא הוא בבחי' יש מאין ממש (אעפ\"י שהנפש נק' נפש השכלי' מפני שממנה מקור מוצא להשכיל כל שכל א\"כ יש לה ערך ויחוס להיות ממנה המציאות של השכל ה\"ז עצמו שנק' יש מאין מאחר שבכח המשכיל שבנפש שעל שם זה נק' נפש השכלי' עדיין אין שם מציאות שכל וחכ' אפילו בהעלם כו').\nיג) <b>וא\"כ</b> יובן מזה עכ\"פ שכאשר האדם חושב במוחו ולבו ומדבר איזה דבר חכ' הנה עפ\"י סדר ההשתלשלות מנקודת חכ' בבינה ומדות ומחשבה ודיבור לא יגרע אפי' אות א' בדיבור עצמו מכמו שהוא בהשגת השכל במוחו ולא יוכל לשנותו כי כל אות ואות הרי יש לו שרש מיוחד באור השכל וחכ' כו', וכידוע דכל צירופי אותיות הדיבור הוא מן החכ' לפי אופן ההשגה בבינה",[["357","52","<b>ויפח באפיו. . ומאן דנפח. . במ\"א עמ\"ש וה' אלקים עשה את האדם ישר</b>: בראשית ב, ז. זוהר — הובא בתניא רפ\"ב: מאן דנפח מתוכי' נפח. [וראה גם תניא באגה\"ק סט\"ו. סה\"מ ”אתהלך-לאזניא\" ע' קה — בשם מאחז\"ל. וב”לקוטי הגהות\" לתניא פ\"ב ע' ט]. ובארוכה בס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תקנ ואילך — ע\"פ קהלת ז, כט."],["358","53","<b>שהחכ' נק' אין ובינה יש כידוע</b>: ראה ביאוה\"ז לאדהאמ\"צ קג, ב, ולהצ\"צ ח\"ב ע' תתרא. וש\"נ. וראה אור תורה להה\"מ דף י, א (הוצאת קה\"ת) ובהוספות להערות וציונים לשם."]]],[1900420098,"דוקא כו'. וכך הוא ענין מע\"ב דבדבר ה' שמים נעשו כו' ששרשם הראשון הוא בחכ' שמאיר בבינה, וגם החכ' עצמה נמדד בשיעור ומדה להיות נמצא שרש שפע לבינה ומדות ומחדו\"מ שממנו ראשית ההשתלשלות בבחי' יש מיש ממדריגה למדריגה עד שיתהווה הבריאה דמלאכים וכל צבאם מבחי' הדיבור העליון מאין ליש ממש כידוע, וא\"כ לא יוכל להיות שינוי כלל במלאכים ונבראים מכמו שהן במקורם הראשון דחכ' עד אותיות הדיבור לפי שכל מלאך ובריאה יש לו צירוף אות מיוחד ששרשו מיוחד במקור הראשון שהוא החכ' אשר מאין תמצא בקצבה ושיעור ומדה דוקא כנ\"ל ולא יוכל לשנות מצירוף לצירוף אחר, ע\"כ אין מלאך א' עושה ב' שליחות<sup data-n=\"359\">54</sup> כי כאו\"א שליחותו לפי מקור התהוותו מצירופי אותיות הדיבור, וע\"כ א\"א שיתהווה מלאך ממלאך העליון ממנו שלא יוכל להיות הוספה על עצם השיעור ומדה הקצובה ממקור הראשון דחכ' עד אותיות הדיבור (ובאמת יכול להיות ריבוי צירופים בדיבור ממח' א' כו' וכן בדיבור עצמו יש כלל ופרט דפרט וכמ\"כ בג' מדריגות דמחדו\"מ בבי\"ע שיוכל להיות שיתהווה התחתון מן העליון כמו שמתהווים אותיות הפרטי' מדיבור וצירוף הכללי כנ\"ל כמו ממאמר דתוצא הארץ נפש חי' יתהווה בסדר ההשתלשלות התחלקות וריבוי מלאכים כמו ריבוי מיני חיות ובהמות למטה כו', אבל זהו הכל בבחי' יש מיש מצד מקורם הראשון דחכ' בבינה כנ\"ל וד\"ל).\nיד) <b>אבל</b> שרש הנשמות באה במקורם הראשון מבחי' אין דחכ' כמו שהיא למעלה טרם שנמצא בבחי' יש ששם הוא גילוי עצמו' אא\"ס שיוכל להיות משם חידוש יש מאין ממש, עד\"מ כאשר יאיר אור חדש במושכל דחכ' מלמעלה מן החכ' מאין ממש הרי יוכל להיות התחדשות כללי בכל השתלשלות דחכ' עד הדיבור העליון לשנות מצירוף לצירוף ולהוסיף דבר חדש שלא הי' תחלה בדיבור מפני שלא הי' גם במושכל הראשון דחכ' (וכמו כל הניסים ונפלאות שמהפכים הטבע כמו מי שאמר לשמן וידליק<sup data-n=\"360\">55</sup> כו' זהו מצד בחי' אור חדש דבחי' אין דחכ' כנ\"ל, וכך כל עליות העולמות מעשי' ליצירה ומיצירה לבריאה ומבריאה לאצי' שלא כפי ההשתלשלות שזהו כמו שהדיבור עולה במח' וממח' למדות עד שהחכ' עולה למעלה בבחי' אין דחכ' כנ\"ל שזהו ענין שבת כידוע, ולהיפך בירידת האור למטה ביותר כנסים (כנבואה ושכינה בהיכל ק\"ק) וגם אפי' בהשגחה אלקי' הפרטי' למטה על צבא המרום<sup data-n=\"361\">56</sup> להשפיל ולהרים כו' עד בנ\"א שבגופים וכל חלקי דצח\"מ כו' הכל הוא בא בבחי' אור חדש דחכ' דעצמו' המאציל באבי\"ע וד\"ל). אלא צ\"ל דיתרון מעלת הנשמות הוא למעלה מבחי' אין דחכ' שהוא אור חדש במושכל כו' שזהו רק ענין שפע",[["359","54","<b>אין מלאך א' עושה ב' שליחות</b>: ב\"ר פ\"נ, ב. ובכ\"מ."],["360","55","<b>מי שאמר לשמן וידליק</b>: תענית כה, א. ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' שכח. ח\"ב ע' תסה. תשצא. דברים ח\"א ע' רעו. ח\"ב ע' תשיט. ח\"ג ע' תשצט. לעיל ח\"א ע' קיז. וש\"נ."],["361","56","<b>על צבא המרום</b>: ע\"פ ישעי' כד, כא: יפקוד ה' על צבא המרום במרום ועל מלכי האדמה על האדמה."]]],[1900420099,"חיצוני' דשכל ממקור השכל הנק' כח המשכיל, אבל שרש הנשמות הוא מבחי' פנימי' ועצמו' דאא\"ס שמלובש בפנימי' ועצמי' דחכ' כמשל הטפה שמתהווה ממוח האב שממנו נולד נפש בדומה לה ממש שהוא מצד עצמו' ומהות הנפש ממש כו', וע\"כ יש בנשמות כח המוליד להוליד נפש חדשה בדומה לה בבחי' אדם בצלם האדם העליון שהוא בבחי' א\"ס ממש שאין זה במלאכים ששרשם רק מיש דחכ' כנ\"ל וד\"ל. ומטעם זה חומר המלאכים דק ורוחני בערך א' עם הצורה לפי שנמשך מבחי' אותיות הדיבור הצורה עם החומר יחד (כמ\"ש במ\"א בענין תוצא הארץ<sup data-n=\"362\">57</sup> נפש חי' שיצאו בצביונן ובקומתן כשור שיצא נפשו וגופו כא' משא\"כ האדם שגופו מן העפר ונשמתו מלמעלה מעלה כמ\"ש ויפח באפיו נ\"ח כו'), ולכך אין ביכולת המלאכים לירד בלבוש גופני יותר מכפי מדתם וערכם במקור חוצבו באותיות הדיבור שנתהוו בצורה וחומר רוחני כא', אבל הנשמה לפי ששרשה מבחי' אין כמ\"ש ויפח באפיו כו' שלמעלה מבחי' השתלשלות דחכ' ע\"כ יש ביכולתו לירד בגוף חומרי וגס יותר ולהפוך גם אותו לבחי' אין האלקי ע\"י תשובה ומע\"ט לפי שאין הגוף רק כלבוש זר בלבד ואינו נחשב כלל מערכה ומהותה, וזהו הכלל שכל הגבוה גבוה ביותר יותר יוכל להשפיל א\"ע ולהיות גם בגוף גשמי ולהפכו בבחי' ביטול היש לאין שאין כח זה במלאכים כלל, וראי' מן הנפילים כנ\"ל. ונמצא דמה שיש הפרש בין נשמות למלאכים בב' דברים הנ\"ל הא בהא תלי' והכל ענין א' וד\"ל.\nטו) <b>והנה</b> אחר כל זה יובן הטעם שבמצות פו\"ר דחו\"כ צ\"ל שמחה גדולה יותר מכל המצות כנ\"ל. דהנה ידוע בשרש ענין השמחה שבטבעה לגרום להיות בחי' גילוי ההעלם והנסתר, שהרי כאשר ישמח אדם יצא כל ההעלם המוסתר שבנפשו לגילוי, וזה הגילוי מן ההעלם שבעצמו' הנפש ממש נק' יש מאין ולא יש מיש, ואעפ\"י שענין גילוי ההעלם בכ\"מ הוא רק יש מיש כמו גילוי הדיבור מהעלם המח' וכן המח' מן המדות והמדות מן השכל כידוע, זהו דוקא רק כמו שבא בסדר והדרגה בהשתלשלות עו\"ע כו', אבל ע\"י השמחה יוצא גילוי ההעלם ממש שלא הי' נגלה כלל בסדר ההשתלשלות, ואין זה אלא ע\"י שמחת הנפש בעצמה דוקא שהוא כאשר השמחה מגעת בנקודת עצמו' הנפש אז יאיר בגילוי מבחי' העלם פנימי' ועצמו' ממש שנק' יש מאין ממש, וראי' לזה ממה שרואים בשמחה העצמי' יולד רצון חדש מה שלא הי' נולד ונמשך לפי טבעו ומהותו, כמו בעת שמחת לבו ביותר ירצה גם בשונאו ויפזר הון רב נגד טבעו והוא מצד שבא העלם העצמו' לגילוי, וכן יוכל לחדש שכל וחכ' חדשה שלא הי' בערך כח שכלו כלל וכלל, וזהו בחי' יש מאין ממש. ונמצא ששרש השמחה יש בכחה להמשיך יש מאין ממש. אמנם זהו בשמחת הנפש בעצמותה ממש, אבל בשמחה בפרטי הכחות כרצון ושכל ומדות אין זה",[["362","57","<b>במ\"א בענין תוצא הארץ</b>: ראה תו\"א בראשית ג, ד. ומקבילו בתו\"ח בראשית יח, ד ואילך. ובכ\"מ."]]],[1900420100,"גורם גילוי העלם העצמי ממש רק גילוי ההעלם דמדה זו לבד שנק' יש מיש ולא יש מאין ממש מאחר שאינה בעצמות הנפש ממש.\n<b>וכדוגמא</b> זו יובן ג\"כ בטעם שמחת חו\"כ להיות שמצות פו\"ר דחו\"כ הוא בבחי' כח המוליד שבנפש להוליד יש מאין שזהו בנשמות דוקא שאין זה במלאכים כנ\"ל, וזה א\"א להיות כ\"א ע\"י בחי' השמחה הגדולה שבעצמות הנפש ממש שגורם בחי' גילוי ההעלם שבעצמו' ממש כנ\"ל ואז יומשך בחי' כח המוליד שבנפש מן ההעלם לגילוי עד אין שיעור כו', ובחי' גילוי העלם זה דכח המוליד הוא בחי' יש מאין ממש כי כח המוליד מוליד נפש חדשה בדומה לו כנ\"ל והוא בחי' כללות דאד\"ם אדמה לעליון ממש כנ\"ל וא\"א להגיע לזה ע\"י שמחה שבפרטי כחות הנפש כשמחת רצון ושכל טוב כו' רק ע\"י שמחת הנפש עצמה דוקא. וזה עיקר הטעם שמצוה לשמח לחו\"כ ביותר מכפי המדה דוקא וכענין הריקוד לפני הכלה כו' והנהנה מסעודת חתן ואינו משמחו עובר בה' קולות כו' שצ\"ל בשמחה גדולה שיהי' גילוי העלם העצמו' דחו\"כ שיוכלו להמשיך כח המוליד שבנפש שהוא בחי' יש מאין ממש כו'. וכך הוא בענין הרוחניות דיחו\"ע דדו\"נ במצות פו\"ר מפני שכולל כל יחוד פרטי שבמצוה פרטי' והוא בבחי' יש מאין ע\"כ צ\"ל בשמחה יותר מכל המצות, אעפ\"י שגם הם צ\"ל בשמחה אך הוא בשמחה פרטי' בדבר פרטי בשמחה של מצוה בצדקה וחסד וכה\"ג (לבד מצות ת\"ת<sup data-n=\"363\">58</sup> כו' כמשי\"ת) שזהו בבחי' יש מיש לבד כרמ\"ח אברים שמקבלים חיותם בסדר השתלשלות מעליון לתחתון ממקורם הראשון מחכ' לבינה ומבינה למדות ומדו\"מ כו', משא\"כ בשמחה דחו\"כ שהוא ע\"י פנימי' ועצמו' הנשמות דדו\"נ שיהי' גילוי ההעלם בכח המוליד להוליד פרי טוב ביח\"ע דמצות שעשו כל ימיהם כו' ה\"ז יש מאין ממש כנ\"ל (וכענין הנ\"ל בהפרש שבין יש מיש ליש מאין שהוא ההפרש בין נשמות למלאכים בכלל). והגם שמצות<sup data-n=\"364\">59</sup>* חו\"כ הוא בגשמי' ביחוד גופני דמצות פו\"ר ושארי מצות הן ברוחניו' ביותר, אך זהו הכלל שכל הגבוה גבוה יותר יוכל לירד למטה כנ\"ל בנשמות שיוכלו לבא בגופים גשמיי' כו', וע\"כ מצות פו\"ר דחו\"כ שביחוד גופני שמלובש בזה מיחו\"ע דנשמות כמו שהן בשרשן למעלה בפנימי' ועצמיו' דאא\"ס שמלובש בפנימי' דחכ' כנ\"ל, וע\"כ א' ביחוד דו\"נ זכו שכינה ביניהם<sup data-n=\"365\">60</sup> כו' להיותם בבחי' אד\"ם אדמה לעליון ממש כנ\"ל<sup data-n=\"366\">61</sup> כידוע וד\"ל.\nטז) <b>וז\"ש</b> ואם משמחו מה שכרו זוכה לתורה שנתנה בה' קולות, ויש להבין מה שייכות שכר זה בשמחת חתן שיזכה לתורה שנתנה כו'. אך הנה",[["363","58","<b>ת\"ת</b>: בכת\"י ב: ת\"ת דחכ'."],["364","59","<b>שמצות</b>: בכת\"י ב: דשמחת."],["365","60","<b>זכו שכינה ביניהם</b>: סוטה יז, א."],["366","61","<b>כנ\"ל כידוע</b>: בכת\"י ב: כנ\"ל באריכות."]]],[1900420101,"יש להקדים תחלה בשרש מצות עסק התורה שגדולה מכל המצות ג\"כ וכמ\"ש ת\"ת כנגד כולם<sup data-n=\"367\">62</sup> הוא, ומוכרח לומר שזהו ג\"כ מטעם הנ\"ל בהפרש שבין יש מיש ליש מאין שבנשמות ומלאכים כו'. והענין הוא שבמצות ת\"ת ה\"ז בבחי' יש מאין ממש יותר מכל המצות, אעפ\"י שהן ג\"כ רצה\"ע ממש כמצות תפילין וציצית וצדקה וכה\"ג, אבל בחי' רצה\"ע דכל המצות הן מורכבים בטעם וחכ' שבתורה שהוא כל מקור רצה\"ע שבמצות ואין זה רק בחי' יש מיש כו', אך בחי' מצות ת\"ת ה\"ז על בחי' ח\"ע דתורה עצמה כמו שהיא באה מבחי' אין ממש דהיינו מעצמות אא\"ס ממש שלמעלה מעלה מן החכ' לגמרי (אפי' מח\"ע דתוה\"ק) וזהו ענין עוסק בתורה לשמה וה\"ז לשמה לשם התורה שהוא להמשיך מעצמו אא\"ס ממש בבחי' מאין ליש בחכ' שבתורה (כמאמ' דוד הי' מחבר תורה של מעלה<sup data-n=\"368\">63</sup> בהקב\"ה), וכידוע דאורייתא מחכמה עילאה נפקת<sup data-n=\"369\">64</sup> והחכ' מאין ממש תמצא. ובזה יש ג' מדריגות, בחי' אין דח\"ע דתורה כמו שהיא בטרם שירדה למטה, ובחי' יש דח\"ע דתורה כשירדה למטה להיות מקור לחכ' דמע\"ב, וכמ\"ש בראשית ברא בשביל התורה<sup data-n=\"370\">65</sup> שנק' ראשית כו' דבראשית זה דח\"ע דתורה הוא פנימי' ומקור לחכ' דמע\"ב שנאמר כולם בחכ' עשית וכן א' בראשית דחכ' ברא<sup data-n=\"371\">66</sup> שהוא בבריאה מאין ליש ממש כידוע, אבל על בחי' האין דח\"ע דתורה כמו שהיא בשרשה צריך להמשיך אותה בגילוי מן ההעלם זהו ענין עוסק בתורה לשמ\"ה לשם התורה עצמה כנ\"ל, וכמו שהי' במ\"ת שהי' בחי' גילוי אור דתורה ביו\"ד הדברות מבחי' העלם העצמו' דא\"ס ממש, והן בכלל ענין ה' קולות שנתנה התורה כו', ועתה ג\"כ ע\"י כל העוסק בתורה לשמה לשם התורה כנ\"ל. וז\"ש קרוב ה' כו' לכל אשר יקראוהו באמת ואין אמת אלא תורה<sup data-n=\"372\">67</sup> שע\"י קריאת התורה הוא קורא וממשיך לבחי' מהו\"ע א\"ס ב\"ה ממש שלמעלה גם ממקור החכ' דהשתלשלות כו', וע\"כ עיקר המצוה בת\"ת הוא להמשיך אא\"ס עצמו, ולהיכן הוא ממשיך אותו בתורה דוקא כנ\"ל, וזהו באמת בתוך התורה שנק' אמ\"ת, והטעם שנק' אמת לפי שבה מתגלה מבחי' אמיתית מהו\"ע אא\"ס ב\"ה דוקא, וזהו הנק' בחי' יש מאין ממש שאין זה בשאר המצות זולתה וד\"ל.\n<b>והנה</b> עד\"ז יובן ענין ה' קולות שניתנה התורה בדרך פרט. דהנה ידוע בפי' קול בכלל שזהו בחי' גילוי המשכה מן ההעלם לבד, כמו הקול של אדם הגשמי שהוא רק ענין גילוי ההעלם, כמו קול הדיבור שמגלה הנעלם וצפון שבמח', וכה\"ג גם קלא פנימאה כקול המשכה דמח' מן המדות והמדות",[["367","62","<b>ת\"ת כנגד כולם</b>: פאה רפ\"א."],["368","63","<b>דוד הי' מחבר תורה של מעלה</b>: ראה זח\"ג רכב, ב. ולעיל ח\"א ע' רמט. וש\"נ."],["369","64","<b>דאורייתא מח\"ע נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. זח\"ג פא, א. קפב, א. רסא, א."],["370","65","<b>בראשית ברא בשביל התורה</b>: פירש\"י ר\"פ בראשית."],["371","66","<b>כולם בחכ'. . בראשית דחכ' ברא</b>: נסמן לעיל סי\"ב."],["372","67","<b>קרוב ה'. . ואין אמת אלא תורה</b>: תהלים קמה, יח. ראה ברכות ה, ב. ירושלמי ר\"ה פ\"ג ה\"ה."]]],[1900420102,"מן השכל כו', אך גילוי העלם זה הוא רק בחי' יש מיש לבד שהרי אין כל חדש בקול ודיבור שכבר הי' במח' וכן במח' אין עיקר חידוש המציאות שכבר הי' במדות וכן משכל למדות (כנ\"ל בענין השמחה), אבל בחי' ה' קולות דמ\"ת בכלל הוא בחי' גילוי ההעלם דעצמו' אא\"ס ממש שנק' יש מאין ממש שהוא בחי' התחדשות גמור שלא הי' תחלה במציאות כלל וכלל מפני שאין ערוך ביניהם כלל, והוא ענין בחי' גילוי התהוות מציאות מקור החכ' דתורה כמו שהיא מבחי' אין והעלם דעצמו' א\"ס ממש כנ\"ל בענין עוסק בתורה לשמה לשם התורה עצמה כו' וד\"ל.\nיז) <b>ומעתה</b> י\"ל בדרך פרט בבחי' ה' קולות דמ\"ת למה הן במספר ה' קולות דוקא. דהנה ה' קולות הללו הן בבחי' ה' מדריגות בהמשכת שפע מן ההעלם העצמות לגילוי, וקול הראשון הוא בחי' המשכה מן ההעלם דעצמו' אא\"ס מאין ליש בבחי' חכ' שבתורה כנ\"ל היינו להיות מציאות עיקר ומקור החכ' שהוא כמו ענין העיון בעומק החכמה שבתורה, כמו ענין הפלפול שהוא בא בהתחכמות וטרדת עומק השכל להמציא שרש ומקור לסברא וטעם לדין והלכה שבתורה שזה בא מכח המשכיל בעצם שלמעלה גם ממקור החכ' הגלוי' שנק' בשם תעלומות חכ' או פלאות חכ', והוא בא מבחי' האין והעלם דעצמות להיות בחי' כח העלם חכ' זו בפרט, ונק' קול זה בחי' המשכה נעלמת עדיין אחר שכל עיקר בחי' המשכה זו הוא שיהי' בחי' העלם ומקור השכל והטעם לבד שנק' תעלומות חכ', ועכ\"ז נק' גילוי ההעלם לגבי העצמו' ממש (שזהו כמו כח המשכיל בעצם כמו שהוא טרם שמשפיע בהעלם ג\"כ כו'). וכמ\"כ יובן גם בבחי' פנימי' וסודות התורה שנק' ג\"כ בשם טעמי תורה עכ\"פ כידוע במ\"ש הנסתרות לה' אלקינו<sup data-n=\"373\">68</sup> כו' שבודאי יש מקור נעלם לגילוי סוד וטעם זה בפרט שבתורה, וא\"כ יש בחי' מקור כללי להמשכות סודות ופנימי' טעמי התורה בכללות שהוא בא מעצמות אא\"ס ממש שלמעלה גם ממקור כללי זה וכמ\"ש ואהי' אצלו כו' שעשועי'<sup data-n=\"374\">69</sup> כו', והוא ענין העוה\"ב שנק' עדן אשר עין לא ראתה רק יעשה למחכה לו למאן דדייק מילין דחכמתא דתורה דוקא כמ\"ש במ\"א שהוא מי שמייגע<sup data-n=\"375\">70</sup> בעיון עומק כח השכל להמציא שרש ומקור הטעם כמו חכה לי ל' המתנה כו' שעי\"ז יזכה לראות בעדן שהוא מקור הכללי להעלם סודות וטעמי התורה כו' (כמו שבנגלה הטעמים וסברות בחכ' ממקור הנעלם הכללי כך הוא בבחי' סתום שבתורה בטעמים הפנימי' כו'). וזהו קול ה' על המים<sup data-n=\"376\">71</sup> כו' למעלה מעלה מבחי' מ\"ע דחכ' דתורה והוא בחי' המשכה נעלמת הנ\"ל שמן",[["373","68","<b>הנסתרות לה' אלקינו</b>: נצבים כט, כח."],["374","69","<b>ואהי' אצלו שעשועים</b>: משלי ח, ל."],["375","70","<b>עדן אשר עין לא ראתה. . למאן דדייק. . במ\"א שהוא מי שמייגע</b>: ישעי' סד, ג. ברכות לד, ב. זח\"ג קל, ב. ראה להלן ד\"ה להבין מה שבברכה, אות ו' ואילך."],["376","71","<b>קול ה' על המים</b>: תהלים כט, ג ואילך."]]],[1900420103,"העצמו' ממש להאיר אור ומקור הכללי להיות בחי' תעלומות חכ' בכל פרט ופרט של דין והלכה כענין הפלפול כנ\"ל, וכמ\"ש במ\"א בענין אמ\"ר או\"ר מי\"ם רקי\"ע<sup data-n=\"377\">72</sup> שבחי' מקור התפשטות החכ' כשבאה מן ההעלם לגילוי נק' מים וקדם לזה בחי' הקול שזהו בחי' שפע המשכה הכללי' מהעלם העצמו' ממש שנק' המשכה נעלמת כי לא באה בגילוי כלל רק להיות מקור להעלם החכ' שבכל שכל בפרט, וזהו על המים שהוא בבחי' מקיף על מ\"ע דתורה להיות התהוות מ\"ע דתורה מטעם הנ\"ל וד\"ל.\n<b>ובחי'</b> קול הב' הוא מ\"ש קול ה' בכח אחר קול ה' על המים עליונים דח\"ע הנ\"ל, והוא כאשר נמשך עוד מהעלם דחכ' הנ\"ל שנק' תעלומות חכ' כנ\"ל לבחי' בינה שהוא בחי' ההשגה וטעם הבא בגילוי שכל וסברא שהוא בחי' יש, ולא יש מיש שהרי זהו הבא מבחי' אין דהעלם החכ' רק שבא ההעלם לגילוי אור בפנים מסבירות שנק' טעם כמו טוב טעם ודעת למדני<sup data-n=\"378\">73</sup> כו' (שהוא קול התחתון דיו\"ד שע\"ז א' הבן בחכ' וחכם בבינה<sup data-n=\"379\">74</sup>) שהוא עומק המושג דבינה, וכמו מ\"ט דר' פלוני אמר קרא כו', ולזה צריך קול המשכה בפ\"ע מהעלם לגילוי, אבל אין זה יש מאין ממש כקול הראשון דהעלם החכ' עצמה כנ\"ל (וכמ\"כ בטעמי תורה בסודות ורזין דאורייתא כנ\"ל), וזהו ג\"כ בבחי' המשכה מהעלם המקור לסוד זה הבא בגילוי טעם עכ\"פ רק שהוא בבחי' הנסתר וכמ\"ש סוד ה' ליראיו<sup data-n=\"380\">75</sup>, כמו בעוה\"ב שיתגלה ההעלם דחכ' בהשגה וטעם דבינה ממש (משא\"כ קול הא' דהיינו על העלם ומקור הסודות ורזין עצמן הוא שנק' עדן עצמו שנק' רזא דרזין זהו בבחי' המשכה נעלמת עדיין כנ\"ל).\nיח) <b>וזהו</b> שעל המשכת העלם החכ' עצמה א' קול ה' על המים בבחי' מקיף כנ\"ל ועל המשכת קול הב' מהעלם החכ' לגילוי בבינה כנ\"ל א' קול ה' בכח בבי\"ת השימוש שמורה שהמשכה זאת באה בתוכה ממש ולא בבחי' מקיף לבד כו'. והענין הוא כידוע ההפרש בין חכ' לבינה בכלל הוא במ\"ש והחכ' מאין<sup data-n=\"381\">76</sup> תמצא ואי זה מקום בינה, הרי בחכ' א' בחי' אין ממש כפשוטו מאין תמצא כלומר מאין ממש תמצא מפני שלא נודע כלל מקורה הנעלם בהעלם אחר העלם ולא בא לגילוי כלל כנ\"ל, אבל בבינה א' ואיזה מקום בינה, פי' ואיזה מקום כו' שיש לשאול על מקומה של בינה מפני שכבר ישנה במציאות בשרשה בהעלם דחכ' רק שלא בא לגילוי בהשגה גמורה עדיין כנ\"ל ע\"כ קיימא לשאלה עכ\"פ לומר איזה איך הוא ומה הוא, כמו איש הנסתר מן",[["377","72","<b>במ\"א בענין אמ\"ר אור מים רקיע</b>: ראה לעיל אות י', ובהמ\"מ שם."],["378","73","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו."],["379","74","<b>הבן בחכ' וחכם בבינה</b>: ראה לעיל אות ג. וש\"נ."],["380","75","<b>סוד ה' ליריאיו</b>: תהלים כה, ד."],["381","76","<b>והחכ' מאין. . הבינה</b>: איוב כח, יב."]]],[1900420104,"העין שעכ\"פ יודעים אותו שישנו במציאות אלא ששואלים אי' מקומו שיראו אותו בגילוי ממש, וכמו ששואלים מי הוא זה כו' שיש על מי לשאול עכ\"פ, וכך הוא בפנימי' ומקור דבינה (שנק' הוא ל' נסתר כמ\"ש מי הוא זה מלך הכבוד כו' וכן מי ברא<sup data-n=\"382\">77</sup> אלה כו') א' ואיזה מקום בינה, משא\"כ על שרש ומקור דהעלם החכ' א' והחכ' מאין ממש תמצא שלא שייך לומר ע\"ז לשון שאלה איזה מקומו או מי הוא לפי שלא נודע מציאותו כלל ונק' כ\"ח מ\"ה ממש כמו מ\"ה פשפשת<sup data-n=\"383\">78</sup> כו' לפי שבאה מבחי' ההעלם דעצמו' ממש להיות מקור לכח ומקור החכ' שנק' תעלומות חכ' כנ\"ל וד\"ל. וזהו הטעם שא' בחכמה קול ה' על המים דחכ' בבחי' מקיף והעלם לגמרי, משא\"כ בקול המשכה דבינה מן ההעלם דחכ' א' קול ה' בכח בבי\"ת שהרי בא בגילוי השגה רק שבתוכו נעלם ומלובש בחי' קול ההמשכה שמבחי' ההעלם דחכ' וא\"כ ה\"ז בתוכו ממש עכ\"פ רק שהקול מלובש ונעלם בתוכו כו' וזהו בכח כו', והוא לפי שבחי' העלם זה אינו בבחי' אין ממש אלא הוא אין של היש דבינה וכבר נתעלם בה בחי' האין האמיתי ובא בבחי' המשכה מקורי' לגילוי השגה שכל וע\"כ יש מי ששואלים עליו כנ\"ל, ולכך נאמר בכח, בכח דבינה מלובש ונעלם קול זה ולא על הבינה וד\"ל.\n<b>והנה</b> ב' קולות הללו דקול ה' על המים וקול ה' בכח הוא בבחי' חו\"ג וכמ\"ש אני בינה לי גבורה<sup data-n=\"384\">79</sup> דגילוי זה שבא בטעם והשגה הוא בא בבחי' גבורה שבחסד כידוע בענין אתה גיבור<sup data-n=\"385\">80</sup> כו' (והוא העוה\"ב שנאמר להנחיל אוהבי יש האמיתי דעצמו' התענוג מורגש בהשגה ממש כמ\"ש במ\"א<sup data-n=\"386\">81</sup>), וענין קול הג' קול ה' בהדר הוא בחי' המדות חג\"ת כקול הדר מג' גוונין הממוזג מחו\"ג, והוא כולל לב' קולות דחו\"ב להיותו בחי' הדעת שכלול מחו\"ג, וזהו ירידה הג' מחו\"ב למדות חג\"ת שבא בגילוי במורגש יותר מן ההשגה שבמוח בינה כו' וד\"ל. וקול ה' שובר ארזים הוא ירידה ד' ממדות שבלב לבחי' נו\"ה שהוא מ\"ה שבמדות דתורה חייב זכאי טמא טהור כו' בא עוד למטה לברר לעה\"ד טו\"ר לפסק דין למעשה בפו\"מ, וזהו קול הד' לשבור ארזים למדות דנוגה ששרשה בבחי' התוהו כידוע. וקול ה' חוצב להבות אש הוא ירידה הה' מנו\"ה שהוא מדות שבאים במח' ודיבור שהוא קול האחרון, וז\"ש קול ה' חוצב להבות אש",[["382","77","<b>מי הוא זה מלך הכבוד. . מי ברא</b>: תהלים כד, י. ישעי' מ, כו."],["383","78","<b>מה פשפשת</b>: זח\"א א, ב."],["384","79","<b>אני בינה לי גבורה</b>: משלי ח, יד."],["385","80","<b>כידוע בענין אתה גיבור</b>: ראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תפו. תקו. ס\"ע תרמח ואילך [שם: וכידוע בכוונה דאתה גבור כו' מכלכל חיים בחסד שזהו בחי' גבורה שבחסד הפשוט שמחלק אור העצמי לחלקים כו' לכלכל חיים בכלים מכלים שונים כו']. ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תשעה."],["386","81","<b>להנחיל אוהבי יש האמיתי. . בהשגה ממש כמ\"ש במ\"א</b>: משלי ח, כא. ראה ס' מאמרי אדהאמ\"צ בראשית ע' נה. שיא. שפו. תח. תפח. שמות ח\"א ע' קנג. רטו. ח\"ב ע' שעד. תלד. תנו. תסג. תקיח. במדבר ח\"ב ס\"ע תרא. ח\"ג ע' תתקמג. דברים ח\"ג ע' תתקפה. ח\"ד ע' א'קפה. א'שיז."]]],[1900420105,"כו' כמ\"ש הלא דברי כאש<sup data-n=\"387\">82</sup> כו', והוא ה' קולות דמשפיע עצמו שנק' נותן התורה עד שנתנה התורה לכנ\"י בדיבור כמו ויאמר ה' אל משה לאמר וד\"ל.\n<b>וזהו</b> אז ראה ויספרה<sup data-n=\"388\">83</sup> הכינה וגם חקרה כו' עד ויאמר לאדם הן יראת ה' היא חכ', בהיות מבואר למעלה בבחי' קול הראשון דקול ה' על המים שהוא בבחי' החכ' ממש זהו מ\"ש אז רא\"ה פי' שראה את שרש החכ' דתורה כמו שהיא בבחי' ראי' עדיין שהוא בהעלם העצמו' שלא בא עדיין גם לבחי' מקור ההשגה דבינה כו', עד שבא בבחי' השגה דבינה מהעלם החכ' זהו שאמר ויספר\"ה ל' ספיר שהוא האור הזהיר ובהיר, והוא בבחי' קול הב' דקול ה' בכ\"ח שהוא בחי' גילוי אור הנעלם דחכ' בבינה שמאירה ומזהירה לאור הנעלם להיות בו השגה במקצת כנ\"ל דקיימא לשאלה כנ\"ל (וגם פי' ויספר\"ה לשון סיפו\"ר שבאה התורה באותיות בספר וסיפור כו'), הכינה בבחי' המדות חג\"ת שיורד עוד למטה כנ\"ל, והוא קול ה' בהדר כנ\"ל, וגם חקרה במח' ודיבור שהוא קול ה' שובר ארזים וקול ה' חוצב להבות אש כו', עד שבאה התורה בבחי' דיבור כנ\"ל, וזהו ויאמר לאדם הן כו' שבאה בבחי' אמירה ודיבור וד\"ל.\n<b>וזהו</b> ענין הה' קולות שנתנה התורה. אך באמת הרי יש ז' קולות בפרט שהן ה' קולות הנ\"ל וקול ה' יחיל מדבר וקול ה' יחולל אילות שזהו בחי' יסוד ומל' וא\"כ למה א' ה' קולות לבד. הענין הוא דה' קולות הללו הן של המשפיע עצמו קודם שנתנה במקבל, וכמ\"ש ויהי קולות וברקים הרי ב' קולות וקול השופר חזק ואח\"כ ויהי קול השופר הולך כו' עד והאלקי' יעננו בקול<sup data-n=\"389\">84</sup>, ב' קולות הראשונים הן בחי' חו\"ב כנ\"ל וקול שופר בחי' ת\"ת וקול שופר הולך וחזק בחי' נצח ויעננו בקול בחי' הוד שזהו קול ה' שובר ארזים וקול ה' חוצב כו' כנ\"ל (ומ\"ש עוד וכל העם רואים את הקולות הנ\"ל היינו ב' קולות הנ\"ל), אבל בחי' ב' קולות דיסוד ומל' ה\"ז מה שכבר נמשך למקבל ונתקבל בתוך המקבל זה אינו נחשב מצד בחי' המשפיע עצמו, והוא ענין קול ה' יחיל מדבר שזהו לאחר גילוי השפע דאור דתורה בדיבור באש למקבל שהן כנ\"י, וקול ה' יחולל כו' הוא מה שעשה בכנ\"י כלי קיבול לקבלת התורה, ולזה לא אמר רק ה' קולות שבהן נתנה התורה מיד הנותן שהן בחי' ה' קולות דחו\"ב ומדות ומו\"ד שהוא עד קול האחרון דחוצב כו' בדיבור באש כנ\"ל וד\"ל.\nיט) <b>והנה</b> מעתה יש להבין מה שא' ויאמר לאדם הן יראת ה' היא חכ' כו', דהיינו לאחר שבאה התורה מראשית דחכ' במקורה הנעלם לגמרי",[["387","82","<b>הלא דברי כאש</b>: ירמי' כג, כט."],["388","83","<b>אז ראה ויספרה</b>: איוב כח, כז-כח: אז ראה ויספרה הכינה וגם חקרה ויאמר לאדם הן יראת אד' היא חכמה וסור מרע בינה."],["389","84","<b>ויהי קולות. . והאלקי' יעננו בקול</b>: יתרו יט, טז. יט."]]],[1900420106,"עד בחי' הדיבור כנ\"ל אז אמר לאדם הן יראת ה' כו'. דהנה ידוע במה שא' אם אין חכ' אין יראה אם אין יראה אין חכ' וא\"כ במה יקדים דאם יתחיל ביראה כמ\"ש ועתה ישראל<sup data-n=\"390\">85</sup> מה ה' שואל מעמך כ\"א ליראה כו' הרי אם אין חכ' אין יראה ואם יתחיל בחכ' הרי אם אין יראה אין חכ', אלא צ\"ל דהחכ' והיראה א' הוא ממש ובאיזה שיתחיל כולל הוא לחבירו אם ביראה יש בה החכ' ואם בחכ' יש בה היראה דשניהם כא' יחשב ממש וא\"א לזה בלא זה עד שאין לא' קדימה על זולתו כלל. וזהו שא' הן יראת ה' היא חכ' עצמה, כי הגם שהיראה היא סוף כל המדריגות שאחר בחי' הדיבור והוא בחי' המעשה לקיים דבר ה' במצות בפו\"מ כמ\"ש סוף דבר כו' ואת מצותיו שמור בפו\"מ, אבל זה כל האדם דחכ' כו' שבתחילת כל ההשתלשלות כי נעוץ תחילתן בסופן וסופן בתחילתן דוקא, וכמאמר תכלית חכ' תשובה ומע\"ט וכמ\"ש ראשית חכ'<sup data-n=\"391\">86</sup> יראת ה' שכל טוב לעושיהם דוקא שזהו בחי' התכלית השלימות דחכ' כמו שהיא במקורה בהעלם העצמו' ממש כנ\"ל, ואעפ\"י שהוא סוף כל המדריגות המסתעפים מן החכ' למטה אבל למעלה היראה ראשית לחכ' (משום דמקור החכ' הוא תלוי בסוף מעשה דוקא ולא בדיבור כמו שאין חכם כבעל הנסיון<sup data-n=\"392\">87</sup> וכמו מי שחכמתו עמדה לו במעשה דוקא כידוע). וזהו שאמר ויאמר לאדם אחר שהביא החכ' דתורה בדיבור כמ\"ש וגם חקר\"ה בגילוי גמור מן ההעלם כמו חקור דבר כו' אח\"ז אמר לאדם שאין זה שלימות החכ' כ\"א יראת ה' שבמעשה שאחר הדיבור דוקא הוא תכלית ושלימות דח\"ע שראה ויספרה כנ\"ל וכמ\"ש שכל טוב לעושיהם ולא ללומדיהם<sup data-n=\"393\">88</sup> בדיבור כו' וכמ\"ש כי זה כל האדם מטעם הנ\"ל (ומ\"ש וסור מרע, בינה, הוא קול הב' דקול ה' בכח דאני בינה לי גבורה<sup data-n=\"394\">89</sup> להיות סור מרע שנק' ירא חטא, ויראת ה' היא חכ' הוא במעשה טוב דמ\"ע שהוא קול הא' קול ה' על המים כנ\"ל).\nכ) <b>ובכ\"ז</b> יובן המאמר דאם משמחו לחתן מה שכרו זוכה לתורה שנתנה בה' קולות דוקא, דהנה ענין קשר וחיבור לזכי' דמ\"ת בה' קולות עם מצות השמחה בפו\"ר דחו\"כ הרי הוא ענין א' ממש לפי כל הנ\"ל דכל עיקר ענין שמחת חו\"כ הוא כדי שע\"י בחי' שמחה העצמיי' יומשך מהעלם העצמו' בבחי' יש מאין ממש להיות כח המוליד ביחודם כנ\"ל, ולכך זוכה לה' קולות דמ\"ת שהוא ג\"כ רק להמשיך מבחי' העלם העצמו' מאין ליש בבחי' ה' קולות הנ\"ל בתורה וכמ\"ש למעלה בענין לשמ\"ה לשם התורה והכל ענין א' הוא ממש וד\"ל. וזהו בשביל המשכת התורה עצמה בה' קולות דמשפיע עד שבא בדיבור",[["390","85","<b>אם אין חכ' אין יראה. . ועתה ישראל</b>: אבות פ\"ג מי\"ז. עקב י, יב."],["391","86","<b>נעוץ תחילתן. . תכלית חכ'. . ראשית חכ'</b>: ס' יצירה פ\"א מ\"ז. ברכות יז, א. תהלים קיא, יו\"ד."],["392","87","<b>שאין חכם כבעל הנסיון</b>: ראה לעיל ח\"א ע' פב, ובהמ\"מ שם. לעיל ד\"ה שמח תשמח (הראשון) סט\"ו."],["393","88","<b>שכל טוב לעושיהם ולא ללומדיהם</b>: ראה ברכות יז, א (הגירסא שהובאה על הגליון שם)."],["394","89","<b>דאני בינה לי גבורה</b>: משלי ח, יד."]]],[1900420107,"כנ\"ל, אבל כדי לחבר ולקשר את התורה בנפש האדם צריך עוד ב' קולות שהן קול ה' יחיל כו' וקול ה' חוצב כו' שהי' במ\"ת בשביל שיתקבל בכנ\"י, והוא להמשיך את התורה מן ההעלם דמשפיע בגילוי במקבל כו', וזהו מצות עסק התורה אדעתא דנפשי' כמ\"ש כ\"א בתורת ה'<sup data-n=\"395\">90</sup> חפצו כו' ואח\"כ ובתורתו יהגה שהוא עסק התורה לשמה כנ\"ל, ואעפ\"י שבמ\"ת הי' ה' קולות דבשביל התורה תחלה, זהו מלמעלה למטה, אבל האדם שעוסק בתורה הוא מלמטה למעלה צריך שיכוון תחלה להיות כלי קיבול לדבר ה' כמו תען לשוני אמרתיך<sup data-n=\"396\">91</sup> כו', וזהו קול ה' יחולל וקול ה' חוצב כו' כנ\"ל. וזהו שא' מעיקרא כי עביד אינש אדעתי' דנפשי' ואח\"כ יוכל לעסוק בתורה לשמה לשם התורה להמשיך בה מעצמו' אא\"ס כנ\"ל וד\"ל. וז\"ש זוכה לתורה שנתנה כו' היינו שיהי' בדומה למשפיע ממש להמשיך מהעלם העצמי' בתורה כנ\"ל שהוא מלמעלה למטה, והוא מפני שישמח בשמחת חו\"כ דוקא דכמו שמשמח לחתן למטה כך ישמח לבחי' חתן העליון שבמ\"ת דכתיב בי' ביום חתונתו וביום שמחת לבו כו' וד\"ל.\nכא) <b>ובכ\"ז</b> יובן מארז\"ל שהלומד תורה בלחש במהרה שוכח כו', ולכאורה מה ענין שכחה ללימוד בלחש הלא בלחש הוא מצד העיון בעומק השכל דוקא והקול מבלבל הכונה הפנימי', וכידוע בענין המשמיע קולו<sup data-n=\"397\">92</sup> בתפלתו כו' (ואדרבה מה שדיבור בלחש דמרחשי' שפתיו<sup data-n=\"398\">93</sup> הוא רק מפני הטרדא בעומק פנימי' השכל כידוע שזהו מצות הגיון שבתורה כמ\"ש והגית<sup data-n=\"399\">94</sup> כו'). אך הנה תחלה יש להבין למה נתנה התורה בקולות וברקים דוקא כמ\"ש ויהי קולות וברקים וקול שופר חזק כו', שאם כדי לאיים עליהם שיהי' בהם בחי' ביטול זה לא שייך לגוף ענין מ\"ת כו'. והנה ידוע שעיקר ענין הקול הוא הבא ברעש גדול כמו ואשמע אחרי<sup data-n=\"400\">95</sup> קול רעש גדול כו', וידוע שעיקר סיבת קול הבא ברעש גדול מאד באדם אינו רק מצד ההתפעלות גדולה המופלגת ביותר מכפי המדה דהיינו כאשר הוא בבחי' הפלאת הדבר ביותר כאשר יתפלא מאד על המראה הגדולה פתע פתאום מאיזה דבר חידוש גדול ונורא מאד אז יבא לכלל התפעלות הנפש בהפלגה גדולה מאד עד שיצעק בקול רעש גדול ממילא ומאליו בלי בחירה ורצון כלל, כמו כאשר פתאום יראה אש שלהבת",[["395","90","<b>אדעתא דנפשי'. . כ\"א בתורת ה'</b>: פסחים סח, ב. מעיקרא כי עביד איניש אדעתא דנפשי' קא עביד. ובע\"ז יט, א: בתחילה נקראת על שמו של הקב\"ה ולבסוף נקראת על שמו שנאמר (תהלים א, ב) בתורת ה' חפצו ובתורתו יהגה יומם ולילה. וראה גם לעיל ח\"א ע' יט. קעד. רסז."],["396","91","<b>תען לשוני אמרתיך</b>: תהלים קיט, קעב."],["397","92","<b>שהלומד תורה בלחש במהרה שוכח. . המשמיע קולו בתפילתו</b>: עירובין נד, א. [וראה לעיל סוף אות ה']. ברכות כד, ב."],["398","93","<b>דמרחשי' שפתיו</b>: ראה מגילה כז, ב: תפילתו סדורה בפיו ורחושי מרחשן שפוותי'. וראה גם לעיל ח\"א ע' רלה, ובהמ\"מ שם."],["399","94","<b>והגית</b>: יהושע א, ח."],["400","95","<b>ואשמע אחרי</b>: יחזקאל ג, יב."]]],[1900420108,"שריפה גדולה או ברקים ורעמים ברעש גדול יצעק בקול רעש, והוא לפי שזהו חידוש דבר מופלא בפתע פתאום שלא הי' בנפשו תחלה כו', והעיקר הוא בא מצד עוצם ההתחדשות המופלגת ומופלאת מאד בדבר מה שהי' מופלא ונעלם מעין שכלו וטבעו ונתגלה לו פתאום דוקא, כמו הרואה נס נפלא מאד שלמעלה מן הטבע לגמרי להיותו בבחי' הפלאת הדבר ובהתחדשות גדולה שלא ראה מעולם יבא לכלל התפעלות הנפש בעצמה בהזזה ממקומו ממש, והוא לפי שבא חידוש זה הנפלא מבחי' אין האלקי ממש שבא בגילוי לעין כל כמו הנס הנפלא, וכאשר בחי' האין האלקי הנעלם בא בגילוי זהו הפלאה גדולה וחידוש גדול ונורא בטבע האנושי ע\"כ מזה יבא סיבת קול הרעש באופני' וחיות ברעש גדול כו' מצד גילוי אור האלקי המופלא מהם שנתגלה עליהם כו'. ונמצא זהו הכלל בכל מקום שכאשר בא התחדשות גמור מאין ממש ליש מזה יבא סיבת הקול רעש כו'. וכך יובן במ\"ת לפי שהי' גילוי אא\"ס ממש מבחי' העלם העצמו' בדיבור אנכי כו' שזהו חידוש גדול ונורא ביותר להיותו בבחי' אין ממש, ע\"כ הי' קולות וברקים בתחלה שהוא ברעש גדול כו' וכן קול השופר חזק מאד, וגם מ\"ש והאלקי' יעננו בקול ודיבור הי' בקול רעש ונורא מטעם זה שכאשר בחי' האין המוחלט דעצמו' אא\"ס יבא לידי גילוי לעיני בשר זהו חידוש גדול הרבה יותר מן הניסים וכה\"ג.\nכב) <b>וזהו</b> הטעם ג\"כ בעוסק בתורה צריך להיות שיהי' בקול רם ורעש ולא בלחש, לפי שבקוראו דבר ה' בתורה ה\"ז בחי' גילוי החכ' מאין ממש כמו במ\"ת ממש שדבריו חיים וקיימים כו' שהוא חידוש גדול ונורא ביותר וד\"ל. משא\"כ הלומד בלחש במהרה שוכח, כי הלומד בלחש הרי אין בזה התפעלות עצמות הנפש מפני בחי' גילוי האין דחכ' שאין מאיר בדבריו מבחי' האין דקול ה' על המים הנ\"ל (דכתיב הרעים ה' על מים רבים<sup data-n=\"401\">96</sup> כו'), וע\"כ הוא לומד בלחש (אעפ\"י שטרוד בעומק העיון זהו רק בהעלם דחכ' שבא לידי השגה ואין זה יש מאין ממש רק יש מיש כנ\"ל), ולזה במהרה שוכ\"ח, כי ענין השכחה באה מבחי' חיצוני' ואחוריי' דחכ' כידוע ע\"פ לא תשכ\"ח ת\"ש כ\"ח<sup data-n=\"402\">97</sup> היפך כ\"ח מ\"ה דחכ', כי פנימי' החכ' שנק' כ\"ח מ\"ה היינו בחי' הכח של בחי' מ\"ה ואין העצמו' דא\"ס שהוא בבחי' נצחי' שלא ישתנה כלל מריבוי חלקי הזמן שמזה יסתעף השכחה כידוע בענין מי איכא זיקנא קמי'<sup data-n=\"403\">98</sup> כו', והעיקר הוא מטעם דכל שהוא בבחי' אין האלקי כמו פנימי' חכ' אין השכחה שם כלל, והוא בחי' מוח הזכרון דפנימי' אבא כו' לפי שקרובי' יותר לבחי' האין, וכעוסק בתורה לשמה",[["401","96","<b>הרעים ה' על מים רבים</b>: תהלים כט, ג."],["402","97","<b>כידוע ע\"פ לא תשכח ת\"ש כ\"ח</b>: תצא כח, יט [וראה במקביל להמאמר כאן בסה\"מ תקס\"ה ח\"א ר\"ע מו]. סה\"מ תקס\"ח ח\"א ע' שפז. ס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תקמב."],["403","98","<b>כידוע בענין מי איכא זיקנא קמי'</b>: יבמות טז, ב. ראה לקו\"ת בחוקותי מח, ג. ולהלן ד\"ה אשר ברא (הראשון) סי\"א."]]],[1900420109,"לשם התורה כו', וכמו החסידים שדביקותן תמיד באין האלקי תמיד תורתם משתמרת<sup data-n=\"404\">99</sup> בקרבם ולא ישכח מהם כו'. אבל העוסקים אדעתי' דנפשי' כנ\"ל שאין זה לשמה ממש דהיינו שלא לשם התורה בקול ה' על המים הנ\"ל הרי זהו באחוריי' דחכ' שאין בחי' האין ממש מאיר שם בגילוי רק בהסתר מאד שם יכול להיות השכחה. וזהו הסימן כשלומד בלחש דוקא שאז אין מאיר בדבריו מבחי' האין ממש ע\"כ שוכ\"ח הוא במהרה על לימודו משא\"כ הלומד בקול רם ברעש וביטול גדול מאד כרואה דבר חידוש ונפלא ביותר כנ\"ל, כמו שהי' במ\"ת שכל העם רואים את הקולות שראו לבחי' האין האלקי' שבקולות וברקים, לא במהרה הוא שוכח, וכמ\"ש למעלה שזוכה לתורה שנתנה בה' קולות כו' כמו קול ה' על המים וקול ה' בכח שהן בבחי' רעש גדול וכן קול ה' שובר ארזים וחוצב כו' ויחיל מדבר וכה\"ג וד\"ל.\n<b>וזהו</b> שהתורה נק' עוז ותושי'<sup data-n=\"405\">100</sup> עוז לנשמה לחזק לבחי' כ\"ח מ\"ה שבה ע\"י בחי' אין דחכ' שבתורה ותושי' שמתשת כח האדם. והענין הוא כנ\"ל בפי' תשכ\"ח ת\"ש כ\"ח שתשש כח החכ' להיות שוכח כו', והוא בחי' אחוריי' דחכ' כשהיא בבחי' יש וגסות ופירוד כח' דנפש הטבעית, אבל ע\"י עוז דנשמה בבחי' אין דחכ' נק' ג\"כ תושי' להתיש לכח החכ' דנה\"ט ששרשה רק באחוריי' דחכ' להיות גם היא בבחי' ביטול היש לאי\"ן בעסקו בתורה כנ\"ל בענין החותם<sup data-n=\"406\">101</sup> שבתורה שבע\"פ כו', וכמ\"ש במ\"א בענין וכד\"ה על שכמ\"ה כ\"ד ספרים דאורייתא<sup data-n=\"407\">102</sup> כשבאה התורה לברר לעה\"ד טו\"ר שהוא בבחי' אחוריי' דחכ' שנק' כתף כמ\"ש במ\"א ע\"פ הנה נתתי לך שכם א' וכן לעבדו שכם א'<sup data-n=\"408\">103</sup> כו', וזהו וכדה על שכמה דוקא לברר לבחי' הכתפיים כו', והוא כענין תושי' שמתיש כח החכ' דנפש הטבעית כו' וד\"ל.",[["404","99","<b>החסידים. . תורתם משתמרת</b>: ברכות לב, ב."],["405","100","<b>שהתורה נק' עוז ותושי'</b>: ע\"פ איוב יב, טז: עמו עוז ותושי'. ראה ספרי ברכה לג, ב. סנהד' כו, ב. ערכי הכינויים (לבעהמ\"ח סדר הדורות) מע' תושי'. אגה\"ק סכ\"ב. תו\"א סז, סע\"א ואילך. ובכ\"מ."],["406","101","<b>כנ\"ל בענין החותם שבתשבע\"פ</b>: ראה ד\"ה אשר יצר, לעיל ח\"א ע' רפד ואילך [ובהמ\"מ בתחילת המאמר שם]. ולהלן בהוספות ברשימת הכת\"י למאמר זה."],["407","102","<b>במ\"א בענין וכדה על שכמה כ\"ד ספרים דאורייתא</b>: חיי\"ש כד, טו. תקוני זהר תכ\"א (מו, ב). וראה לקו\"ת ברכה צד, סע\"א ואילך. סה\"מ תקס\"ט ע' ד וס\"ע ח ואילך וע' כד ואילך. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' רכו, ובהמ\"מ שם."],["408","103","<b>שנק' כתף כמ\"ש ע\"פ הנה נתתי לך שכם. . לעבדו שכם א'</b>: ויחי מח, כב. צפני' ג, ט. וראה תו\"א קב, ב ואילך. סה\"מ תקס\"ג ח\"א ע' פ ואילך. תו\"ח לך לך צ, ג ואילך."]]],[1900420110,"<h3>שמח תשמח כו' סובב וממלא</h3>\n<b></b><b>תורת אדמו\"ר בעת חתונת בתו</b>\n<b>שמח</b> תשמח<sup data-n=\"409\">1</sup> ריעים האהובים. הנה ידוע שהקב\"ה וכנ\"י הוא בחי' סובב וממלא, והוא הנק' חתן וכלה שזהו יחוד קוב\"ה ושכינתי', פי' שכינתי' הוא בחי' אור האלקי השוכן ומתלבש בעולמות בתוך כל עלמין ובבחי' ממלא להחיותן מאין ליש והוא הנמשך בבחי' פנימיות ותוך תוכם ממש, אבל בחי' סובב כל עלמין הוא למעלה מבחי' השפעה והמשכה בתוך כל עלמין, אבל הוא בחי' מקור הראשון שממנו נמצא מציאות האור והשפע האלקי בעולמות בבחי' ממלא כו' כמ\"ש כי עמך מקור חיים כו' כידוע בענין כי הוי' הוא האלקי'<sup data-n=\"410\">2</sup> כו', וע\"כ נק' בחי' זו בשם סוכ\"ע שהארתו רק בבחי' מקיף ברחוק על כל העולמות ומקיף לכולם בשוה כידוע. והנה בחי' סובב זה הוא הנק' בחי' חתן ובחי' ממלא זה נק' כלה, והטעם מובן להיות ידוע בפי' חתן ל' נחות דרגא<sup data-n=\"411\">3</sup> והוא בחי' ירידת האור מן המשפיע אל המקבל, כך הוא בחי' ירידת אור המשפיע שהוא בחי' סובב הנ\"ל שהרי הוא בחי' מקור הראשון שממנו נמשך בחי' הארה האלקי' בבחי' ממלא כנ\"ל, ונמצא שבחי' ממלא הנ\"ל נק' כלה בהיותה בחי' מקבל הארתה מן החתן שהוא בחי' סובב שהוא עיקר המשפיע כמ\"ש כי ממך הכל<sup data-n=\"412\">4</sup> כו' משום דעמך מקו\"ח כו', וכמו הלבנה שמקבלת מן השמש כידוע.\n<b>וזהו</b> פי' ריעים האהובים עד\"מ חו\"כ הגשמיים שהן ריעים האהובים זע\"ז כמ\"ש ע\"כ יעזוב איש כו' ודבק באשתו, ובאשה נא' ואל אישך תשוקתך, [דתיאובתא דדכורא<sup data-n=\"413\">5</sup> לגבי נוק' להשפיע לה, ותיאובתא דנוק' לגבי דכורא לקבל השפע כמ\"ש ואל אישך תשוקתך כו'[ וכך יובן למעלה בבחי' חו\"כ למעלה בבחי' סובב וממלא שהוא קודב\"ה ושכינתי' כנ\"ל, שבחי' ממלא הנק' כלה אל אישה תשוקתה לקבל האור והשפע מבחי' סובב הנ\"ל שנק' חתן, וחפצה ותשוקתה נפלאה בתמידות כמ\"ש בזוהר ע\"פ למען יזמרך כבוד ולא ידום כו' וכן אלקים אל דמי לך כו' דנהורא תתאה<sup data-n=\"414\">6</sup> קארי תדיר לנהורא עילאה ולא",[["409","1","<b>שמח תשמח</b>: מיוסד על ד\"ה זה בס' מאמרי אדה\"ז על מארז\"ל ע' תצב ואילך. ונמצא מאמר זה באריכות לעיל ד\"ה שמח תשמח הראשון, וראה בהנסמן בתחילת המאמר שם.\nבהכתבי-יד אחר מאמר זה בא ד\"ה שוש תשיש [נדפס לעיל ח\"א ע' שיז ואילך], ובכ\"מ שם מציין ?כמ\"ש למעלה\" וקאי על המאמר שלפנינו.\nראה עוד ע\"ד המאמר להלן בהוספות ברשימת הכתבי-יד."],["410","2","<b>כי עמך. . כידוע בענין כי הוי' הוא האלקי'</b>: תהלים לו, יו\"ד. ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשסו וס\"ע תשפח ואילך [ושם ג\"כ ע\"פ כי עמך מקו\"ח. וראה ג\"כ ע\"פ זה לעיל ח\"א ע' שיח ובהמ\"מ שם]. לקו\"ת בלק עג, ב. שם סע\"ג ואילך. לקו\"ת ואתחנן ט, סע\"א ואילך [ומקבילו בסה\"מ תקס\"ח ע' שפא ואילך]."],["411","3","<b>בפי' חתן ל' נחות דרגא</b>: ראה יבמות סג, א."],["412","4","<b>כי ממך הכל</b>: דברי הימים א כט, יד."],["413","5","<b>ע\"כ יעזוב. . ואל אישך תשוקתך. . דתיאובתא דדכורא</b>: בראשית ב, כד. ג, טז. ראה זח\"א פה, ב וזח\"ב קסה, א."],["414","6","<b>בזוהר ע\"פ למען יזמרך. . אלקים אל דמי. . דנהורא תתאה</b>: תהלים ל, יג. פג, ב. ראה לעיל ד\"ה שמח תשמח (הא'), ס\"ה. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רלז. וש\"נ."]]],[1900420111,"שכיך לעלמין כו' וכמ\"ש ואל אישך תשוקתך בתמידות, וידוע שיותר ממה שהעגל רוצה לינק<sup data-n=\"415\">7</sup> הפרה רוצה להניק א\"כ יותר יש תשוקה במשפיע להשפיע מתשוקת המקבל לקבל, וע\"כ נא' שיעזוב איש את אביו כו' ודבק באשתו כו'. ולמעלה היינו בחי' תשוקת המשפיע שהוא בחי' סובב הנ\"ל שחפץ בתשוקה נפלאה ביותר להאיר ולהשפיע בבחי' ממלא הנ\"ל שנק' כלה, וע\"כ נק' בשם ריעים האהובים בתמידות שאהבתם ותשוקתם זל\"ז נפלאה תמיד ביותר כו' וד\"ל.\n<b>וכמ\"כ</b> יובן בנשמות שבגופים שנק' כנ\"י דלתתא שבהם נאמר ג\"כ ואל אישך תשוקתך שהוא הקב\"ה שנק' חתן וכנ\"י נק' כלה כידוע, להיות שנשמות שבגופים יש להם ג\"כ בחי' תשוקה ואהבה נפלאה ליכלל ולידבק בה' אחד שהוא הקב\"ה בחי' סובב הנ\"ל, וכמ\"ש שמע ישראל שהוא הניצוץ האלקי בפרט ובכללות נק' כנ\"י שמלובשי' בגופי' כו' למסור נפשו באחד כו' וזהו ואהבת ממילא בכל נפשך כו', וכמים הפנים כו' נתעורר בחי' אהבה עליונה של הקדב\"ה לכנ\"י שהוא בחי' סובב הנ\"ל, כמו אהבתי אתכם<sup data-n=\"416\">8</sup> אמר הוי' וכן הבוחר בעמו ישראל באהבה כו', ומבואר למעלה דיותר ממה שהעגל כו' הפרה רוצה כו' דאהבת המשפיע גדולה יותר, א\"כ הרי אהבת ה' לישראל גדולה יותר, והוא ענין כפה עליהם הר כגיגית שהאהבה נק' הר כמו לא כאברהם שקראו הר<sup data-n=\"417\">9</sup>, כמו הר הבולט מן הארץ כך אור האהבה צומחת ועולה למעלה כו', והר כגיגית ה\"ז אהבה שבבחי' מקיף שמקיף למקבל כמו הגיגית שמכסה ומקיף על האדם לבלתי יוכל לצאת משם כו'. והענין הוא דמשום שאהבת המשפיע אל המקבל גדולה יותר כנ\"ל ע\"כ יש בכחה יותר לפעול גם התפעלות חיזוק אהבה יתירה במקבל אל המשפיע לבלתי יוכל להפרד לעולם (כמו שאין האשה כורתת ברית אלא למי שעשאה כלי כו' הרי לא תוכל להפרד ולידבק באחר משום דאהבת המשפיע נקשרה בה ברוחא דשביק בגוה<sup data-n=\"418\">10</sup> שאין נזקקת אלא לבן זוגה כו' משום דרוח זה שעשאה כלי מתחלה הוא מבחי' המקיף כו' שאין כח זה במקבל לפעול פעולה זו במשפיע שלא יוכל להפרד כו'). וזהו כפה עליהם הר כגיגית בבחי' מקיף באהבה נפלאה וחזקה יותר מאהבתם עד שפועל ישועו' בקרב הארץ באה\"ר אליו שלא יוכל להפרד לעולם. וזהו ג\"כ ענין החבוק וכמ\"ש וימינו תחבקני<sup data-n=\"419\">11</sup> שאהבה מבחי' החבוק הוא אהבה שבבחי' מקיף שפועל למקבל הנחבק שלא יפרד מאהבתו ולא תשכח ממנו האהבה לעולם ויהי' תמיד",[["415","7","<b>שיותר ממה שהעגל רוצה לינק</b>: פסחים קיב, א."],["416","8","<b>שמע. . ואהבת. . אהבתי אתכם</b>: ואתחנן ו, ד-ה. מלאכי א, ב."],["417","9","<b>כפה עליהם הר כגיגית. . לא כאברהם שקראו הר</b>: שבת פח, א. פסחים פח, א [וראה לעיל ח\"א ע' ריד. ס' מאמרי אדה\"ז עה\"ת ח\"א ע' שצב. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' קט. ח\"ב ע' תרסו ובהמ\"מ שם]."],["418","10","<b>שאין האשה כורתת. . ברוחא דשביק בגוה</b>: סנה' כב, ב. ראה זח\"ב צט, ב וע\"ח שער מ\"ן ומ\"ד\nדרוש ז, ח."],["419","11","<b>וימינו תחבקני</b>: שה\"ש ב, ו."]]],[1900420112,"אחוז וקשור בברית האהבה בל תמוט ממנו לנצח, כמו שאנו רואים בחוש בענין מעשה החבוק הגשמי שמחבק אדם את אוהבו בידו שענינו מורה ע\"ז שלא יפרד לעולם הימנו, והוא במה שמחבקו בידו על אחוריו באה\"ר ונפלאה עד שמחזירו כלפי פניו ואיננו מניחו להפרד ממנו בחבוק שחובקו אליו וצומדו כאילו הן גוף אחד ממש כו' והרי ידו מקיף לגופו עד שמסבבו מכל צד שלא יוכל לנטות ממנו, וה\"ז מורה ענין כח ועוז תוקף האהבה שפועל אצל הנחבק שלא ינטה לבבו ולא ינתק חבל ההתקשרו' ברית ביניהם לעולם לא בשכחה ולא במונעים המפרידים כו'. וזהו הבוחר בעמו ישראל באהבה, פי' באהבה שבבחי' מקיף וחיבוק כו', וזאת האהבה קודמת לק\"ש שהוא בחי' יחוד לקוב\"ה ושכינתי' ממש כנ\"ל כמו החיבוק שקודם ליחוד וזיווג, וכך במ\"ת כפה עליהם הר כגיגית בבחי' חיבוק שקודם לגוף היחוד שבשעת מ\"ת שעל כל דיבור פרחה<sup data-n=\"420\">12</sup> כו' וד\"ל.\n<b>והנה</b> כל הנ\"ל בחי' יחוד קודשא בריך הוא ושכינתי' בבחי' סו\"מ<sup data-n=\"421\">13</sup>* שנק' חו\"כ ה\"ז בא בבחי' ההשתלשלות עכ\"פ דהיינו בבחי' וענין ההשתלשלות האור והשפע מבחי' מהות ועצמות דאחדות פשוטה אז יש ב' מדריגות בחי' משפיע מקור האור הנק' סובב כו' ובחי' מקבל האור הזה להיות בחי' ממלא כנ\"ל, אבל בבחי' מהו\"ע דאח\"פ ממש כמו שהוא טרם שיומשך ויבא לכלל בחי' משפיע<sup data-n=\"422\">14</sup>* עדיין הרי הוא ממש בתכלית האח\"פ ולא יתכן לקרותו גם בבחי' סובב כו' מאחר שהוא למעלה מבחי' משפיע עדיין שאין בחי' סובב אלא לגבי עלמין כו', וע\"ז הוא שאמר ג\"כ כי עמך מקו\"ח, דגם בחי' מקור החיים האמיתי שבבחי' סובב הנ\"ל אין ערוך כלל לגבי עצמותו ממש כי אינו רק בחי' הארה בעלמא לגבי בחי' עצמותו ממש כמו שהוא טרם שיבא לכלל בחי' משפיע שנק' חתן כו' וד\"ל.\n<b>וזהו</b> יחי\"ד ח\"י העולמי\"ם מלך, פי' בחי' עצמותו ממש כנ\"ל הוא הנק' יחי\"ד לבדו שאין שיתוף<sup data-n=\"423\">15</sup>* וחיבור כלל גם להיות נק' בשם ראש ומקור להשתל', וזהו ההפרש בין יחיד לראשון שלראשון יש שני וליחיד אין לו שני כו' כידוע, אך מה שנק' ח\"י העולמים בבחי' סובב שממנו מתפשט הארה בעולמות דאבי\"ע בבחי' ממלא שע\"כ נק' ח\"י העולמים בחי' עצם<sup data-n=\"424\">16</sup> מקורו הוא רק בחי' מלך דהיינו מה שעלה במחשבה הקדומה אנא אמלוך<sup data-n=\"425\">17</sup> כו' שמזה נמשך להיות בבחי'",[["420","12","<b>שעל כל דיבור פרחה</b>: שבת פח, ב."],["421","13","<b>סו\"מ</b>: סובב וממלא. [ובמקומות אחרים במאמר זה, פיענוח ר\"ת זה הוא: סובב ומקיף]."],["422","14","<b>משפיע</b>: בכת\"י ב: משפיע ומקבל."],["423","15","<b>שיתוף</b>: בכת\"י ב: שייכות."],["424","16","<b>עצם מקורו</b>: בכת\"י ב: עצם ומקור כו'."],["425","17","<b>אנא אמלוך</b>: אד\"ר ? הובא בדרמ\"צ קע, סע\"ב. וראה לקו\"ת נשא כא, ד ובהמ\"מ לשם [בהוצאת קה\"ת, ה'תשד\"מ]."]]]]});
